INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('klinicheskiy-analiz-krovi', 'Клинический анализ крови (общий анализ крови, ОАК, развёрнутый анализ крови) с лейкоцитарной формулой и СОЭ', 'Общеклинические исследования', 'Кровь', 'Базовое исследование крови: подсчёт клеток, лейкоцитарная формула и СОЭ для оценки воспаления, анемии и общего состояния.', 'Утром натощак или через 3 ч после лёгкого приёма пищи; вода без ограничений. Накануне исключить алкоголь и тяжёлые нагрузки.', 1);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('obschiy-analiz-krovi', 'Общий анализ крови (ОАК, клинический анализ крови без лейкоцитарной формулы)', 'Общеклинические исследования', 'Кровь', 'Подсчёт эритроцитов, лейкоцитов, тромбоцитов и гемоглобина для базовой оценки состояния здоровья.', 'Утром натощак или через 3 ч после лёгкого приёма пищи; вода без ограничений. Накануне исключить алкоголь и тяжёлые нагрузки.', 2);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('leykotsitarnaya-formula-ruchnaya-metodika', 'Лейкоцитарная формула (ЛФ, микроскопия мазка, ручной подсчёт лейкоцитов)', 'Общеклинические исследования', 'Кровь', 'Ручной подсчёт видов лейкоцитов под микроскопом для оценки воспаления, инфекций и болезней крови.', 'Утром натощак или через 3 ч после лёгкого приёма пищи; вода без ограничений. Накануне исключить алкоголь и тяжёлые нагрузки.', 3);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('retikulotsity', 'Ретикулоциты (подсчёт ретикулоцитов, ретикулоцитарные индексы, RET)', 'Общеклинические исследования', 'Кровь', 'Подсчёт молодых эритроцитов для оценки активности кроветворения и диагностики анемий.', 'Утром натощак или через 3 ч после лёгкого приёма пищи; вода без ограничений. Накануне исключить алкоголь и тяжёлые нагрузки.', 4);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('soe', 'Скорость оседания эритроцитов (СОЭ, РОЭ, ESR)', 'Общеклинические исследования', 'Кровь', 'Неспецифический показатель воспаления; ускорение СОЭ указывает на инфекции, воспаление или другие процессы.', 'Утром натощак или через 3 ч после лёгкого приёма пищи; вода без ограничений. Накануне исключить алкоголь и тяжёлые нагрузки.', 5);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('gemoglobin', 'Гемоглобин (Hb, гемоглобин крови)', 'Общеклинические исследования', 'Кровь', 'Определение уровня гемоглобина для выявления анемии и оценки переноса кислорода кровью.', 'Утром натощак или через 3 ч после лёгкого приёма пищи; вода без ограничений. Накануне исключить алкоголь и тяжёлые нагрузки.', 6);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('gematokrit', 'Гематокрит (Ht, HCT, гематокритное число)', 'Общеклинические исследования', 'Кровь', 'Доля эритроцитов в объёме крови; помогает выявить анемию, обезвоживание и сгущение крови.', 'Утром натощак или через 3 ч после лёгкого приёма пищи; вода без ограничений. Накануне исключить алкоголь и тяжёлые нагрузки.', 7);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('eritrotsity', 'Эритроциты (RBC, подсчёт эритроцитов, красные кровяные тельца)', 'Общеклинические исследования', 'Кровь', 'Подсчёт эритроцитов для диагностики анемий, эритроцитозов и оценки кроветворения.', 'Утром натощак или через 3 ч после лёгкого приёма пищи; вода без ограничений. Накануне исключить алкоголь и тяжёлые нагрузки.', 8);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('leykotsity', 'Лейкоциты (WBC, подсчёт лейкоцитов, белые кровяные тельца)', 'Общеклинические исследования', 'Кровь', 'Подсчёт лейкоцитов для выявления инфекций, воспаления и заболеваний системы крови.', 'Утром натощак или через 3 ч после лёгкого приёма пищи; вода без ограничений. Накануне исключить алкоголь и тяжёлые нагрузки.', 9);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('trombotsity', 'Тромбоциты (PLT, подсчёт тромбоцитов, кровяные пластинки)', 'Общеклинические исследования', 'Кровь', 'Подсчёт тромбоцитов для оценки свёртывания крови и риска кровотечений или тромбозов.', 'Утром натощак или через 3 ч после лёгкого приёма пищи; вода без ограничений. Накануне исключить алкоголь и тяжёлые нагрузки.', 10);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('morfologiya-eritrotsitov', 'Морфология эритроцитов (оценка формы и размеров эритроцитов, анизоцитоз, пойкилоцитоз)', 'Общеклинические исследования', 'Кровь', 'Микроскопическая оценка формы и размеров эритроцитов для уточнения типа анемии.', 'Утром натощак или через 3 ч после лёгкого приёма пищи; вода без ограничений. Накануне исключить алкоголь и тяжёлые нагрузки.', 11);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('le-kletki', 'LE-клетки (волчаночные клетки, клетки красной волчанки, LE-cells)', 'Общеклинические исследования', 'Кровь', 'Выявление волчаночных клеток в крови при подозрении на системную красную волчанку.', 'Утром натощак или через 3 ч после лёгкого приёма пищи; вода без ограничений. Накануне исключить алкоголь и тяжёлые нагрузки.', 12);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('dlitelnost-krovotecheniya', 'Длительность кровотечения по Дьюке (время кровотечения, проба Дьюке, Duke)', 'Общеклинические исследования', 'Кровь', 'Оценка времени остановки кровотечения для проверки функции тромбоцитов и стенок сосудов.', 'Специальной подготовки не требуется. За 5–7 дней (по согласованию с врачом) исключить аспирин и препараты, влияющие на свёртываемость крови.', 13);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('analiz-mochi-po-zimnitskomu', 'Анализ мочи по Зимницкому (проба Зимницкого, 8 порций мочи)', 'Общеклинические исследования', 'Моча', 'Сбор мочи 8 порциями за сутки для оценки концентрационной и выделительной функции почек.', 'Обычный питьевой и пищевой режим (без переизбытка жидкости). Собрать 8 порций каждые 3 часа в течение суток в отдельные ёмкости с указанием времени.', 14);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('issledovanie-mochi-po-nechiporenko', 'Исследование мочи по Нечипоренко (проба Нечипоренко, подсчёт форменных элементов)', 'Общеклинические исследования', 'Моча', 'Подсчёт эритроцитов, лейкоцитов и цилиндров в 1 мл мочи для выявления скрытого воспаления почек и мочевых путей.', 'Утренняя средняя порция мочи после туалета наружных половых органов. Женщинам не сдавать во время менструации.', 15);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('eozinofily-v-moche', 'Эозинофилы в моче (эозинофилурия, эозинофилы мочи)', 'Общеклинические исследования', 'Моча', 'Выявление эозинофилов в моче при подозрении на аллергическое или интерстициальное воспаление почек и мочевых путей.', 'Утренняя средняя порция мочи после туалета наружных половых органов. Женщинам не сдавать во время менструации.', 16);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('obschiy-analiz-mochi', 'Общий анализ мочи с микроскопией осадка (ОАМ, клинический анализ мочи)', 'Общеклинические исследования', 'Моча', 'Оценка физико-химических свойств мочи и микроскопия осадка для диагностики болезней почек и мочевых путей.', 'Утренняя средняя порция мочи после туалета наружных половых органов, в чистый контейнер. Женщинам не сдавать во время менструации.', 17);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('2-h-stakannaya-proba-mochi', 'Двухстаканная проба мочи (2-х стаканная проба, двухпорционная проба)', 'Общеклинические исследования', 'Моча', 'Сбор мочи в 2 порции за одно мочеиспускание для топической диагностики воспаления мочевых путей', 'Утром, не мочиться 3–4 часа до сбора. После туалета половых органов собрать мочу в 2 контейнера за одно мочеиспускание, не прерывая струю.', 18);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('3-h-stakannaya-proba-mochi', 'Трёхстаканная проба мочи (3-х стаканная проба, трёхпорционная проба)', 'Общеклинические исследования', 'Моча', 'Сбор мочи в 3 порции за одно мочеиспускание для уточнения уровня поражения мочеполового тракта.', 'Утром, не мочиться 4–5 часов до сбора. После туалета половых органов собрать мочу в 3 контейнера за одно мочеиспускание, не прерывая струю.', 19);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('osmolyalnost-mochi', 'Осмоляльность мочи (осмолярность мочи, концентрация осмотически активных веществ)', 'Общеклинические исследования', 'Моча', 'Определение осмоляльности мочи для оценки концентрационной функции почек и водно-солевого баланса.', 'Обычный питьевой режим. Собрать разовую или суточную порцию мочи по назначению врача.', 20);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('proba-sulkovicha', 'Проба Сулковича (кальций в моче полуколичественно, тест Сулковича)', 'Общеклинические исследования', 'Моча', 'Полуколичественная оценка выделения кальция с мочой для контроля обмена кальция и дозировки витамина D.', 'Утренняя порция мочи натощак. За 2–3 дня по согласованию с врачом ограничить продукты, богатые кальцием.', 21);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('ketonovye-tela-v-moche', 'Кетоновые тела в моче (кетоны, ацетон в моче, ketones)', 'Общеклинические исследования', 'Моча', 'Выявление кетоновых тел в моче при диабете, голодании и нарушениях обмена веществ.', 'Утренняя средняя порция мочи после туалета наружных половых органов, в чистый контейнер.', 22);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('belok-bens-dzhonsa-v-moche', 'Белок Бенс-Джонса в моче (протеин Бенс-Джонса, лёгкие цепи иммуноглобулинов в моче)', 'Общеклинические исследования', 'Моча', 'Выявление белка Бенс-Джонса в моче при подозрении на миеломную болезнь и парапротеинемии.', 'Собрать суточную или свежую утреннюю порцию мочи в чистый контейнер по указанию лаборатории.', 23);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('urobilinogen-v-moche', 'Уробилиноген в моче (уробилиноген, urobilinogen)', 'Общеклинические исследования', 'Моча', 'Определение уробилиногена в моче для оценки функции печени и выявления гемолиза.', 'Утренняя средняя порция свежей мочи в чистый контейнер; доставить в лабораторию быстро, беречь от света.', 24);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('zhelchnye-pigmenty-v-moche', 'Жёлчные пигменты в моче (билирубин в моче, жёлчные пигменты)', 'Общеклинические исследования', 'Моча', 'Выявление билирубина и жёлчных пигментов в моче при заболеваниях печени и жёлчевыводящих путей.', 'Утренняя средняя порция свежей мочи в чистый контейнер; доставить в лабораторию быстро, беречь от света.', 25);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('proba-addisa-kakovskogo', 'Проба Аддиса-Каковского (анализ мочи по Аддису-Каковскому, суточный подсчёт форменных элементов)', 'Общеклинические исследования', 'Моча', 'Подсчёт форменных элементов в суточной моче для выявления скрытого воспаления и болезней почек.', 'Собрать мочу за 10–24 часа по указанию лаборатории. Мужчинам и женщинам — тщательный туалет половых органов; женщинам не сдавать при менструации.', 26);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('gemosiderin-v-moche', 'Гемосидерин в моче (гемосидеринурия, гемосидерин)', 'Общеклинические исследования', 'Моча', 'Выявление гемосидерина в моче как признака внутрисосудистого гемолиза эритроцитов.', 'Утренняя средняя порция мочи после туалета наружных половых органов, в чистый контейнер.', 27);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('soli-i-kristally-v-moche', 'Соли и кристаллы в моче (оксалаты, ураты, фосфаты, кристаллурия)', 'Общеклинические исследования', 'Моча', 'Выявление солей и кристаллов в моче для оценки риска мочекаменной болезни и нарушений обмена.', 'Утренняя средняя порция мочи после туалета наружных половых органов. За сутки не менять резко характер питания.', 28);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('issledovanie-kala-na-prosteyshie-i-yaytsa-gelmintov', 'Исследование кала на простейшие и яйца гельминтов (кал на я/глист, гельминты и простейшие, ova & parasites)', 'Общеклинические исследования', 'Кал', 'Микроскопия кала для выявления яиц гельминтов и простейших — диагностика глистных и паразитарных инвазий.', 'Свежий кал в чистый контейнер, без клизм и слабительных. За 3 дня отменить сорбенты, препараты железа и висмута.', 29);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('issledovanie-na-enterobioz', 'Соскоб на энтеробиоз (Enterobius vermicularis, острицы, яйца остриц)', 'Общеклинические исследования', 'Кал', 'Соскоб с перианальных складок для выявления яиц остриц — диагностика энтеробиоза.', 'Утром до дефекации и подмывания. Не подмываться перед взятием материала.', 30);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('kal-na-skrytuyu-krov-colon-view-hb-hp', 'Кал на скрытую кровь без диеты (иммунохимический тест, Colon View Hb/Hp, гемоглобин/гаптоглобин)', 'Общеклинические исследования', 'Кал', 'Иммунохимическое выявление скрытой крови в кале для скрининга кровотечений ЖКТ и колоректального рака.', 'Специальной диеты не требуется. Не собирать при менструации, кровоточащем геморрое и кровоточивости дёсен.', 31);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('obschiy-analiz-kala', 'Общий анализ кала (копрограмма, копрологическое исследование)', 'Общеклинические исследования', 'Кал', 'Комплексная оценка кала для диагностики нарушений пищеварения и всасывания в ЖКТ.', 'Свежий кал в чистый контейнер без клизм и слабительных. За 3 дня отменить сорбенты, препараты железа и висмута.', 32);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('ag-helikobaktera-v-kale', 'Антиген Helicobacter pylori в кале (АГ хеликобактера, H. pylori antigen, хеликобактер пилори, антигенный тест)', 'Общеклинические исследования', 'Кал', 'Выявление антигена H. pylori в кале для диагностики инфекции и контроля лечения гастрита и язвы.', 'За 2 недели отменить антибиотики и препараты висмута, за 7 дней — ингибиторы протонной помпы (по согласованию с врачом).', 33);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('kalprotektin-fekalnyy', 'Кальпротектин фекальный (fecal calprotectin, кальпротектин в кале)', 'Общеклинические исследования', 'Кал', 'Определение кальпротектина в кале — маркер воспаления кишечника при ВЗК (болезнь Крона, язвенный колит).', 'Свежий кал в чистый контейнер. По согласованию с врачом за несколько дней отменить НПВС.', 34);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('elastaza-pankreaticheskaya', 'Эластаза-1 панкреатическая в кале (панкреатическая эластаза, pancreatic elastase)', 'Общеклинические исследования', 'Кал', 'Определение эластазы-1 в кале для оценки внешнесекреторной функции поджелудочной железы.', 'Свежий кал в чистый контейнер. Приём ферментных препаратов отменять не требуется.', 35);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('uglevody-v-kale', 'Углеводы в кале (редуцирующие вещества, проба на лактазную недостаточность)', 'Общеклинические исследования', 'Кал', 'Определение углеводов в кале для диагностики лактазной недостаточности, преимущественно у детей.', 'Обычный режим кормления/питания. Свежий кал в чистый контейнер, доставить в лабораторию быстро.', 36);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('ph-kala', 'pH кала (кислотность кала, реакция кала)', 'Общеклинические исследования', 'Кал', 'Определение кислотности кала для оценки процессов брожения и всасывания в кишечнике.', 'Свежий кал в чистый контейнер, доставить в лабораторию быстро.', 37);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('ag-lyambliy-v-kale', 'Антиген лямблий в кале (АГ лямблий, Giardia lamblia antigen, лямблиоз, антигенный тест)', 'Общеклинические исследования', 'Кал', 'Выявление антигена лямблий в кале для диагностики лямблиоза.
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('ag-rotavirusa-i-adenovirusa-v-kale', 'Антигены ротавируса и аденовируса в кале (АГ ротавируса и аденовируса, rotavirus/adenovirus antigen, кишечные инфекции)', 'Общеклинические исследования', 'Кал', 'Выявление антигенов ротавируса и аденовируса в кале для диагностики острых кишечных инфекций.', 'Свежий кал в чистый контейнер, желательно собрать в острый период болезни.', 39);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('ag-clostridioides-difficile-v-kale', 'Токсины A/B Clostridioides difficile в кале (АГ C. difficile, токсины А и B, C. difficile toxin, клостридиум диффициле, псевдомембранозный колит)', 'Общеклинические исследования', 'Кал', 'Выявление токсинов A/B C. difficile в кале для диагностики антибиотик-ассоциированного колита.', 'Свежий жидкий кал в чистый контейнер, доставить в лабораторию быстро.', 40);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('issledovanie-kala-metodom-obogascheniya', 'Исследование кала методом обогащения Parasep (концентрация паразитов, гельминты и простейшие)', 'Общеклинические исследования', 'Кал', 'Микроскопия кала методом обогащения Parasep для повышения выявляемости гельминтов и простейших.', 'Свежий кал в чистый контейнер без клизм и слабительных. За 3 дня отменить сорбенты и препараты железа.', 41);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('issledovanie-otdelyaemogo-iz-uha-zeva-nosa-na-eozinofily', 'Отделяемое уха, зева и носа на эозинофилы (риноцитограмма, эозинофилы в мазке, назоцитограмма)', 'Общеклинические исследования', 'Выделения и мокрота', 'Микроскопия мазков из уха, зева и носа на эозинофилы для выявления аллергического воспаления.', 'Не полоскать нос и горло, не использовать капли и спреи за 2–3 часа до взятия материала.', 42);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('obscheklinicheskoe-issledovanie-sekreta-predstatelnoy-zhelez', 'Микроскопия секрета предстательной железы (сок простаты, секрет простаты, исследование секрета простаты)', 'Общеклинические исследования', 'Выделения и мокрота', 'Микроскопия секрета простаты для диагностики простатита и воспаления предстательной железы.', 'Половое воздержание 2–3 дня. Материал получают после массажа простаты у врача.', 43);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('obscheklinicheskoe-issledovanie-otdelyaemogo-urogenitalnogo', 'Микроскопия отделяемого урогенитального тракта, 3 точки (мазок на флору, уретра/влагалище/цервикальный канал, гинекологический мазок)', 'Общеклинические исследования', 'Выделения и мокрота', 'Микроскопия мазка из 3 точек урогенитального тракта для оценки флоры и выявления воспаления.', 'Женщинам — вне менструации, не спринцеваться, исключить свечи и половой контакт накануне. Не мочиться 2–3 часа.', 44);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('obscheklinicheskoe-issledovanie-otdelyaemogo-uretry', 'Микроскопия отделяемого уретры (мазок из уретры, уретральный мазок на флору)', 'Общеклинические исследования', 'Выделения и мокрота', 'Микроскопия отделяемого уретры для выявления воспаления и оценки микрофлоры мочеиспускательного канала.', 'Не мочиться 2–3 часа до взятия материала. Исключить местные препараты накануне.', 45);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('obscheklinicheskoe-issledovanie-soskoba-na-demodeks', 'Соскоб на демодекс (Demodex folliculorum/brevis, клещ демодекс, демодекоз, ресницы и кожа)', 'Общеклинические исследования', 'Выделения и мокрота', 'Микроскопия соскоба кожи и ресниц на клеща демодекс для диагностики демодекоза.', 'За сутки не умываться с мылом в зоне взятия, не использовать кремы, мази и косметику.', 46);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('obscheklinicheskoe-issledovanie-mokroty', 'Общий анализ мокроты (микроскопия мокроты, клинический анализ мокроты)', 'Общеклинические исследования', 'Выделения и мокрота', 'Микроскопия мокроты для диагностики болезней бронхов и лёгких и оценки характера воспаления.', 'Утром натощак, после чистки зубов и полоскания рта. Собрать мокроту при откашливании в стерильный контейнер.', 47);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('obscheklinicheskoe-issledovanie-biomateriala-na-nalichie-pat', 'Микроскопия на патогенные грибы (микозы, дрожжевые и плесневые грибы, грибковая инфекция)', 'Общеклинические исследования', 'Выделения и мокрота', 'Микроскопия биоматериала для выявления патогенных грибов при подозрении на микоз.', 'Не обрабатывать очаг антисептиками и противогрибковыми средствами за 3–5 дней до взятия материала.', 48);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('mazok-na-stepen-chistoty-vlagalischa', 'Мазок на степень чистоты влагалища (степень чистоты, гинекологический мазок на флору, влагалищный мазок)', 'Общеклинические исследования', 'Выделения и мокрота', 'Микроскопия влагалищного мазка для определения степени чистоты и выявления воспаления.', 'Вне менструации; не спринцеваться, исключить свечи и половой контакт накануне. Не мочиться 2 часа.', 49);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('mikroskopiya-soskoba-kozhi-i-nogtey-na-griby', 'Микроскопия соскоба кожи и ногтей на грибы (онихомикоз, дерматомикоз, патогенные грибы, микоз ногтей)', 'Общеклинические исследования', 'Выделения и мокрота', 'Микроскопия соскоба кожи и ногтей для выявления грибковой инфекции (микоз, онихомикоз).', 'За 3–5 дней не использовать противогрибковые кремы и лаки, не стричь и не обрабатывать поражённые ногти и кожу.', 50);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('issledovanie-na-chesotochnogo-klescha', 'Соскоб на чесоточного клеща (Sarcoptes scabiei, чесотка, scabies, чесоточный клещ)', 'Общеклинические исследования', 'Выделения и мокрота', 'Микроскопия соскоба кожи для выявления чесоточного клеща при подозрении на чесотку.', 'Не мыться и не наносить мази и кремы на поражённые участки за 12 часов до взятия материала.', 51);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('mikroskopiya-otdelyaemogo-glaza', 'Микроскопия отделяемого глаза (мазок с конъюнктивы, отделяемое конъюнктивы, глазной мазок)', 'Общеклинические исследования', 'Выделения и мокрота', 'Микроскопия отделяемого глаза для диагностики воспаления конъюнктивы и оценки его характера.', 'Не закапывать капли и не использовать мази за 2–3 часа до взятия. Утром не умываться до сдачи.', 52);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('alfa-amilaza', 'Альфа-амилаза в разовой моче (диастаза мочи, амилаза мочи, alpha-amylase)', 'Биохимия', 'Биохимия мочи', 'Определение амилазы в разовой порции мочи для диагностики болезней поджелудочной железы и слюнных желёз.', 'Разовая порция мочи в чистый контейнер. Накануне исключить алкоголь и жирную пищу.', 53);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('alfa-amilaza-2', 'Альфа-амилаза в суточной моче (диастаза суточной мочи, амилаза мочи, alpha-amylase)', 'Биохимия', 'Биохимия мочи', 'Определение амилазы в суточной моче для оценки работы поджелудочной железы при панкреатите.', 'Собрать мочу за 24 часа в контейнер, первую утреннюю порцию слить. Указать суточный объём. Накануне исключить алкоголь.', 54);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('belok', 'Белок в суточной моче (суточная протеинурия, экскреция белка за сутки, total protein urine)', 'Биохимия', 'Биохимия мочи', 'Определение потери белка с мочой за сутки для диагностики болезней почек и оценки протеинурии.', 'Собрать мочу за 24 часа, первую утреннюю порцию слить. Указать суточный объём. Избегать чрезмерных физических нагрузок.', 55);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('glyukoza', 'Глюкоза в разовой моче (сахар в моче, глюкозурия, glucose urine)', 'Биохимия', 'Биохимия мочи', 'Определение глюкозы в разовой порции мочи для выявления глюкозурии при диабете и болезнях почек.', 'Разовая порция мочи в чистый контейнер. Соблюдать обычный режим питания.', 56);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('glyukoza-2', 'Глюкоза в суточной моче (суточная глюкозурия, экскреция глюкозы за сутки, glucose urine)', 'Биохимия', 'Биохимия мочи', 'Определение выделения глюкозы с мочой за сутки для диагностики и контроля сахарного диабета.', 'Собрать мочу за 24 часа, первую утреннюю порцию слить. Указать суточный объём.', 57);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('kaliy-natriy-hlor', 'Калий, натрий, хлор в суточной моче (K/Na/Cl, электролиты мочи, electrolytes urine)', 'Биохимия', 'Биохимия мочи', 'Определение калия, натрия и хлора в суточной моче для оценки водно-электролитного баланса и функции почек.', 'Собрать мочу за 24 часа, первую утреннюю порцию слить. Указать суточный объём. Обычный питьевой режим.', 58);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('kaltsiy', 'Кальций в разовой моче (кальций мочи, кальциурия, calcium urine)', 'Биохимия', 'Биохимия мочи', 'Определение кальция в разовой порции мочи для оценки обмена кальция и риска мочекаменной болезни.', 'Разовая порция мочи в чистый контейнер. Накануне не менять резко характер питания.', 59);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('kreatinin', 'Креатинин (в раз.моче)', 'Биохимия', 'Биохимия мочи', 'Креатинин в разовой моче (креатинин мочи, creatinine urine)', 'Определение креатинина в разовой моче; используется для расчёта соотношений и оценки функции почек.', 60);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('mikroalbumin', 'Микроальбумин в разовой моче (микроальбуминурия, МАУ, MAU, microalbumin)', 'Биохимия', 'Биохимия мочи', 'Определение микроальбумина в моче для ранней диагностики поражения почек при диабете и гипертонии.', 'Разовая порция мочи (утренняя) в чистый контейнер. Избегать физических нагрузок накануне; не сдавать при менструации.', 61);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('mochevina', 'Мочевина в суточной моче (экскреция мочевины за сутки, urea urine)', 'Биохимия', 'Биохимия мочи', 'Определение выделения мочевины с мочой за сутки для оценки белкового обмена и функции почек.', 'Собрать мочу за 24 часа, первую утреннюю порцию слить. Указать суточный объём.', 62);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('obschiy-belok', 'Общий белок в разовой моче (белок мочи, протеинурия, protein urine)', 'Биохимия', 'Биохимия мочи', 'Определение общего белка в разовой порции мочи для выявления протеинурии и болезней почек.', 'Разовая порция мочи в чистый контейнер. Избегать чрезмерных физических нагрузок; не сдавать при менструации.', 63);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('ekskretsiya-kaltsiya', 'Экскреция кальция за сутки (суточная кальциурия, кальций в суточной моче, calcium excretion)', 'Биохимия', 'Биохимия мочи', 'Определение выделения кальция с мочой за сутки для оценки обмена кальция и диагностики мочекаменной болезни.', 'Собрать мочу за 24 часа, первую утреннюю порцию слить. Указать суточный объём. Накануне не менять диету.', 64);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('ekskretsiya-magniya', 'Экскреция магния за сутки (суточная магнийурия, магний в суточной моче, magnesium excretion)', 'Биохимия', 'Биохимия мочи', 'Определение выделения магния с мочой за сутки для оценки обмена магния и функции почек.', 'Собрать мочу за 24 часа, первую утреннюю порцию слить. Указать суточный объём.', 65);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('ekskretsiya-mikroalbumina', 'Экскреция микроальбумина за сутки (суточная микроальбуминурия, МАУ, MAU excretion)', 'Биохимия', 'Биохимия мочи', 'Определение выделения микроальбумина с мочой за сутки для ранней диагностики поражения почек.', 'Собрать мочу за 24 часа, первую утреннюю порцию слить. Указать суточный объём. Избегать нагрузок; не сдавать при менструации.', 66);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('ekskretsiya-mochevoy-kisloty', 'Экскреция мочевой кислоты за сутки (суточная урикозурия, мочевая кислота в суточной моче, uric acid excretion)', 'Биохимия', 'Биохимия мочи', 'Определение выделения мочевой кислоты с мочой за сутки при подагре и мочекаменной болезни.', 'Собрать мочу за 24 часа, первую утреннюю порцию слить. Указать суточный объём. Накануне исключить алкоголь и мясной избыток.', 67);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('ekskretsiya-fosfora', 'Экскреция фосфора за сутки (суточная фосфатурия, фосфор в суточной моче, phosphorus excretion)', 'Биохимия', 'Биохимия мочи', 'Определение выделения фосфора с мочой за сутки для оценки фосфорно-кальциевого обмена и функции почек.', 'Собрать мочу за 24 часа, первую утреннюю порцию слить. Указать суточный объём.', 68);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('oksalaty-v-moche', 'Оксалаты в моче (оксалатурия, щавелевая кислота в моче, oxalate urine)', 'Биохимия', 'Биохимия мочи', 'Определение оксалатов в моче для оценки риска оксалатных камней и нарушений обмена.', 'Собрать мочу по указанию лаборатории (разовая или суточная). За сутки ограничить продукты, богатые оксалатами (шпинат, свёкла, шоколад).', 69);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('tsitraty-v-moche', 'Цитраты в моче (цитратурия, лимонная кислота в моче, citrate urine)', 'Биохимия', 'Биохимия мочи', 'Определение цитратов в моче для оценки риска камнеобразования в почках.', 'Собрать мочу по указанию лаборатории (разовая или суточная). Накануне не менять резко характер питания.', 70);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('mochevaya-kislota', 'Мочевая кислота в разовой моче (мочевая кислота мочи, урикозурия, uric acid urine)', 'Биохимия', 'Биохимия мочи', 'Определение мочевой кислоты в разовой порции мочи при подагре и мочекаменной болезни.', 'Разовая порция мочи в чистый контейнер. Накануне исключить алкоголь и избыток мясной пищи.', 71);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('yod-v-moche', 'Йод в моче (йодурия, экскреция йода, iodine urine)', 'Биохимия', 'Биохимия мочи', 'Определение йода в моче для оценки обеспеченности организма йодом и йодного дефицита.', 'Разовая порция мочи в чистый контейнер. За несколько дней исключить йодсодержащие препараты и контрастные вещества (по согласованию с врачом).', 72);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('sootnoshenie-albumin-kreatinin-v-moche', 'Соотношение альбумин/креатинин в моче (АКС, ACR, альбумин-креатининовое соотношение, albumin/creatinine ratio)', 'Биохимия', 'Биохимия мочи', 'Расчёт соотношения альбумин/креатинин в моче для ранней диагностики поражения почек.', 'Утренняя разовая порция мочи в чистый контейнер. Избегать физических нагрузок накануне; не сдавать при менструации.', 73);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('ekskretsiya-kreatinina', 'Экскреция креатинина за сутки (суточный креатинин мочи, creatinine excretion)', 'Биохимия', 'Биохимия мочи', 'Определение выделения креатинина с мочой за сутки; используется для оценки функции почек и клиренса.', 'Собрать мочу за 24 часа, первую утреннюю порцию слить. Указать суточный объём. Накануне избегать интенсивных нагрузок.', 74);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('glyukoza-3', 'Глюкоза (глюкоза крови, сахар крови, glucose, гликемия)', 'Биохимия', 'Глюкоза и диабет', 'Определение уровня глюкозы в крови для диагностики сахарного диабета и контроля углеводного обмена.', 'Строго натощак, 8–12 ч голодания; можно пить воду. Накануне исключить алкоголь, не менять привычный режим питания.', 75);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('glikirovannyy-gemoglobin', 'Гликированный гемоглобин (HbA1c, гликозилированный гемоглобин, гликгемоглобин)', 'Биохимия', 'Глюкоза и диабет', 'Показатель среднего уровня глюкозы за последние 2–3 месяца для диагностики и контроля сахарного диабета.', 'Показатель среднего уровня глюкозы за последние 2–3 месяца для диагностики и контроля сахарного диабета.', 76);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('glyukozotolerantnyy-test', 'Глюкозотолерантный тест, 3 точки: натощак, 30 мин, 1 час (ГТТ, тест толерантности к глюкозе, глюкозная нагрузка, OGTT)', 'Биохимия', 'Глюкоза и диабет', 'Измерение глюкозы натощак и после нагрузки для выявления нарушения толерантности к глюкозе и скрытого диабета.', 'Строго натощак, 8–14 ч голодания. 3 дня — обычное питание без ограничения углеводов. Во время теста не есть, не курить, не нагружаться.', 77);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('fruktozamin', 'Фруктозамин (fructosamine, гликированный альбумин)', 'Биохимия', 'Глюкоза и диабет', 'Показатель среднего уровня глюкозы за последние 2–3 недели для краткосрочного контроля сахарного диабета.', 'Желательно натощак, 8–12 ч голодания; можно пить воду. Накануне исключить алкоголь.', 78);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('glyukozotolerantnyy-test-2', 'Глюкозотолерантный тест, 2 точки: натощак, через 2 часа (ГТТ, тест толерантности к глюкозе, глюкозная нагрузка, OGTT)', 'Биохимия', 'Глюкоза и диабет', 'Измерение глюкозы натощак и через 2 часа после нагрузки для диагностики диабета и преддиабета.', 'Строго натощак, 8–14 ч голодания. 3 дня — обычное питание без ограничения углеводов. Во время теста не есть, не курить, не нагружаться.', 79);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('glyukozotolerantnyy-test-pri-beremennosti', 'Глюкозотолерантный тест при беременности, 75 г глюкозы (ГТТ беременных, ПГТТ, гестационный диабет, OGTT)', 'Биохимия', 'Глюкоза и диабет', 'Нагрузочная проба с 75 г глюкозы для выявления гестационного сахарного диабета у беременных.', 'Строго натощак, 8–14 ч голодания. 3 дня — обычное питание. Тест проводят с 3 заборами (натощак, 1 ч, 2 ч); во время теста сидеть спокойно, не есть и не курить.', 80);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('insulinorezistentnost', 'Индекс инсулинорезистентности QUICKI (QUICKI, инсулинорезистентность, глюкоза и инсулин натощак)', 'Биохимия', 'Глюкоза и диабет', 'Расчётный индекс по глюкозе и инсулину натощак для оценки чувствительности тканей к инсулину.', 'Строго натощак, 8–12 ч голодания; можно пить воду. Накануне исключить алкоголь и интенсивные физические нагрузки.', 81);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('k', 'Калий (K+, Potassium, калий крови)', 'Биохимия', 'Электролиты и минералы', 'Определение калия в крови для оценки водно-электролитного баланса, работы сердца и функции почек.', 'Утром натощак, 8–12 ч голодания; можно пить воду. Накануне исключить алкоголь и интенсивные нагрузки.', 82);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('kaliy-natriy-hlor-2', 'Калий, натрий, хлор (K+/Na+/Cl-, электролиты крови, Potassium/Sodium/Chloride, электролитный профиль)', 'Биохимия', 'Электролиты и минералы', 'Определение основных электролитов крови для оценки водно-солевого баланса, работы сердца и почек.', 'Утром натощак, 8–12 ч голодания; можно пить воду. Накануне исключить алкоголь и интенсивные нагрузки.', 83);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('kaltsiy-obschiy', 'Кальций общий (Ca, Calcium total, общий кальций крови)', 'Биохимия', 'Электролиты и минералы', 'Определение общего кальция в крови для оценки кальциевого обмена, состояния костей и функции паращитовидных желёз.', 'Утром натощак, 8–12 ч голодания; можно пить воду. Накануне исключить алкоголь.', 84);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('magniy', 'Магний (Mg, Magnesium, магний крови)', 'Биохимия', 'Электролиты и минералы', 'Определение магния в крови для оценки нервно-мышечной проводимости, работы сердца и обмена веществ.', 'Утром натощак, 8–12 ч голодания; можно пить воду. За несколько дней по согласованию с врачом отменить препараты магния.', 85);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('med', 'Медь (Cu, Copper, медь крови)', 'Биохимия', 'Электролиты и минералы', 'Определение меди в крови для диагностики нарушений обмена меди, в том числе болезни Вильсона-Коновалова.', 'Утром натощак, 8–12 ч голодания; можно пить воду. Накануне исключить алкоголь.', 86);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('natriy', 'Натрий (Na+, Sodium, натрий крови)', 'Биохимия', 'Электролиты и минералы', 'Определение натрия в крови для оценки водно-солевого баланса, осмолярности и функции почек.', 'Утром натощак, 8–12 ч голодания; можно пить воду. Накануне исключить алкоголь.', 87);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('fosfor-neorganicheskiy', 'Фосфор неорганический (P, Phosphorus, фосфаты крови)', 'Биохимия', 'Электролиты и минералы', 'Определение неорганического фосфора в крови для оценки фосфорно-кальциевого обмена и функции почек.', 'Утром натощак, 8–12 ч голодания; можно пить воду. Накануне исключить алкоголь.', 88);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('hlor', 'Хлор (Cl-, Chloride, хлориды крови)', 'Биохимия', 'Электролиты и минералы', 'Определение хлора в крови для оценки водно-электролитного и кислотно-щелочного баланса.', 'Утром натощак, 8–12 ч голодания; можно пить воду. Накануне исключить алкоголь.', 89);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('tsink', 'Цинк (Zn, Zinc, цинк крови)', 'Биохимия', 'Электролиты и минералы', 'Определение цинка в крови для оценки обеспеченности организма цинком, состояния иммунитета и кожи.', 'Утром натощак, 8–12 ч голодания; можно пить воду. За несколько дней исключить БАД и препараты цинка.', 90);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('kaltsiy-ionizirovannyy', 'Кальций ионизированный (Ca2+, ионизированный кальций, свободный кальций, ionized calcium)', 'Биохимия', 'Электролиты и минералы', 'Определение активной (ионизированной) формы кальция для точной оценки кальциевого обмена.', 'Утром натощак, 8–12 ч голодания; можно пить воду. Накануне исключить алкоголь и интенсивные нагрузки.', 91);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('selen', 'Селен (Se, Selenium, селен крови)', 'Биохимия', 'Электролиты и минералы', 'Определение селена в крови для оценки обеспеченности организма селеном и антиоксидантного статуса.', 'Утром натощак, 8–12 ч голодания; можно пить воду. За несколько дней исключить БАД с селеном.', 92);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('marganets', 'Марганец (Mn, Manganese, марганец крови)', 'Биохимия', 'Электролиты и минералы', 'Определение марганца в крови для оценки микроэлементного статуса и выявления профессиональной интоксикации.', 'Утром натощак, 8–12 ч голодания; можно пить воду. Накануне исключить алкоголь.', 93);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('svinets', 'Свинец (Pb, Lead, свинец крови)', 'Биохимия', 'Электролиты и минералы', 'Определение свинца в крови для диагностики отравления свинцом и контроля профессиональных вредностей.', 'Утром натощак, 8–12 ч голодания; можно пить воду. Накануне исключить алкоголь.', 94);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('rtut', 'Ртуть (Hg, Mercury, ртуть крови)', 'Биохимия', 'Электролиты и минералы', 'Определение ртути в крови для диагностики отравления ртутью и контроля профессиональных вредностей.', 'Утром натощак, 8–12 ч голодания; можно пить воду. За несколько дней ограничить употребление рыбы и морепродуктов.', 95);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('kadmiy', 'Кадмий (Cd, Cadmium, кадмий крови)', 'Биохимия', 'Электролиты и минералы', 'Определение кадмия в крови для диагностики хронической интоксикации и контроля вредных производств.', 'Утром натощак, 8–12 ч голодания; можно пить воду. Накануне исключить алкоголь и курение.', 96);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('alyuminiy', 'Алюминий (Al, Aluminium, алюминий крови)', 'Биохимия', 'Электролиты и минералы', 'Определение алюминия в крови для диагностики интоксикации, в том числе у пациентов на диализе.', 'Утром натощак, 8–12 ч голодания; можно пить воду. Накануне исключить алкоголь.', 97);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('myshyak', 'Мышьяк (As, Arsenic, мышьяк крови)', 'Биохимия', 'Электролиты и минералы', 'Определение мышьяка в крови для диагностики острого и хронического отравления мышьяком.', 'Утром натощак, 8–12 ч голодания; можно пить воду. За несколько дней исключить рыбу и морепродукты.', 98);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('kobalt', 'Кобальт (Co, Cobalt, кобальт крови)', 'Биохимия', 'Электролиты и минералы', 'Определение кобальта в крови для оценки микроэлементного статуса и выявления интоксикации, в том числе от металлических имплантов.', 'Утром натощак, 8–12 ч голодания; можно пить воду. Накануне исключить алкоголь.', 99);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('nikel', 'Никель (Ni, Nickel, никель крови)', 'Биохимия', 'Электролиты и минералы', 'Определение никеля в крови для диагностики интоксикации и контроля профессионального контакта с металлом.', 'Утром натощак, 8–12 ч голодания; можно пить воду. Накануне снять металлические украшения, исключить контакт с никелем.', 100);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('zhelezo', 'Железо (Fe, сывороточное железо, iron, железо крови)', 'Биохимия', 'Обмен железа и меди', 'Определение уровня железа в сыворотке для диагностики железодефицита, анемий и перегрузки железом.', 'Утром натощак, 8–12 ч голодания; можно пить воду. За 5–7 дней отменить препараты железа (по согласованию с врачом).', 101);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('zhelezosvyazyvayuschaya-sposobnost-syvorotki-obschaya-vklyuc', 'Общая железосвязывающая способность сыворотки (ОЖСС, TIBC, включая Fe, total iron-binding capacity)', 'Биохимия', 'Обмен железа и меди', 'Оценка способности крови связывать железо; используется в диагностике железодефицита и анемий.', 'Утром натощак, 8–12 ч голодания; можно пить воду. За 5–7 дней отменить препараты железа (по согласованию с врачом).', 102);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('transferrin', 'Трансферрин (transferrin, сидерофилин, белок-переносчик железа)', 'Биохимия', 'Обмен железа и меди', 'Определение трансферрина — основного белка-переносчика железа; применяется для диагностики нарушений обмена железа.', 'Утром натощак, 8–12 ч голодания; можно пить воду. За 5–7 дней отменить препараты железа (по согласованию с врачом).', 103);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('ferritin', 'Ферритин (ferritin, депо железа, запасы железа)', 'Биохимия', 'Обмен железа и меди', 'Определение ферритина для оценки запасов железа в организме; ключевой маркер железодефицита и перегрузки железом.', 'Утром натощак, 8–12 ч голодания; можно пить воду. За 5–7 дней отменить препараты железа (по согласованию с врачом).', 104);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('tseruloplazmin', 'Церулоплазмин (ceruloplasmin, медьсодержащий белок, обмен меди)', 'Биохимия', 'Обмен железа и меди', 'Определение церулоплазмина для оценки обмена меди и диагностики болезни Вильсона-Коновалова.', 'Утром натощак, 8–12 ч голодания; можно пить воду. Накануне исключить алкоголь.', 105);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('latentnaya-zhelezosvyazyvayuschaya-sposobnost', 'Латентная железосвязывающая способность (ЛЖСС, UIBC, ненасыщенная железосвязывающая способность, unsaturated iron-binding capacity)', 'Биохимия', 'Обмен железа и меди', 'Оценка резерва связывания железа сывороткой; применяется в диагностике железодефицита и анемий.', 'Утром натощак, 8–12 ч голодания; можно пить воду. За 5–7 дней отменить препараты железа (по согласованию с врачом).', 106);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('koeffitsient-nasyscheniya-transferrina-zhelezom', 'Коэффициент насыщения трансферрина железом (НТЖ, TSAT, процент насыщения трансферрина, transferrin saturation)', 'Биохимия', 'Обмен железа и меди', 'Расчётный показатель насыщения трансферрина железом для диагностики железодефицита и перегрузки железом.', 'Утром натощак, 8–12 ч голодания; можно пить воду. За 5–7 дней отменить препараты железа (по согласованию с врачом).', 107);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('rastvorimye-retseptory-transferrina', 'Растворимые рецепторы трансферрина (sTfR, растворимый рецептор трансферрина, soluble transferrin receptor)', 'Биохимия', 'Обмен железа и меди', 'Определение sTfR для диагностики железодефицита, в том числе при сопутствующем воспалении.', 'Утром натощак, 8–12 ч голодания; можно пить воду. За 5–7 дней отменить препараты железа (по согласованию с врачом).', 108);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('gepsidin', 'Гепсидин (hepcidin, регулятор обмена железа)', 'Биохимия', 'Обмен железа и меди', 'Определение гепсидина — ключевого регулятора обмена железа; помогает уточнить причину нарушений метаболизма железа.', 'Утром натощак, 8–12 ч голодания; можно пить воду. За 5–7 дней отменить препараты железа (по согласованию с врачом).', 109);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('albumin', 'Альбумин (albumin, альбумин сыворотки, ALB)', 'Биохимия', 'белковый обмен', 'Определение альбумина в крови для оценки состояния печени, почек, питания и белкового обмена.', 'Утром натощак, 8–12 ч голодания; можно пить воду. Накануне исключить алкоголь и интенсивные нагрузки.', 110);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('obschiy-belok-2', 'Общий белок (TP, total protein, общий белок сыворотки)', 'Биохимия', 'белковый обмен', 'Определение общего белка в крови для оценки белкового обмена, функции печени и почек.', 'Утром натощак, 8–12 ч голодания; можно пить воду. Накануне исключить алкоголь.', 111);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('belkovye-fraktsii', 'Белковые фракции, электрофорез (протеинограмма, электрофорез белков сыворотки, SPEP, protein electrophoresis)', 'Биохимия', 'белковый обмен', 'Разделение белков крови на фракции для диагностики воспаления, болезней печени, почек и парапротеинемий.', 'Утром натощак, 8–12 ч голодания; можно пить воду. Накануне исключить алкоголь.', 112);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('prealbumin', 'Преальбумин (prealbumin, транстиретин, transthyretin)', 'Биохимия', 'белковый обмен', 'Определение преальбумина как чувствительного маркера белкового питания и функции печени.', 'Утром натощак, 8–12 ч голодания; можно пить воду. Накануне исключить алкоголь.', 113);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('globuliny-i-sootnoshenie-a-g', 'Глобулины и соотношение А/Г (глобулины, альбумин-глобулиновый коэффициент, A/G ratio)', 'Биохимия', 'белковый обмен', 'Определение глобулинов и соотношения альбумин/глобулины для оценки белкового баланса, воспаления и болезней печени.', 'Утром натощак, 8–12 ч голодания; можно пить воду. Накануне исключить алкоголь.', 114);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('immunofiksatsiya-belkov-syvorotki', 'Иммунофиксация белков сыворотки (иммунофиксация, IFE, immunofixation, типирование парапротеина)', 'Биохимия', 'белковый обмен', 'Выявление и типирование моноклональных белков (парапротеинов) при подозрении на миелому и парапротеинемии.', 'Утром натощак, 8–12 ч голодания; можно пить воду. Накануне исключить алкоголь.', 115);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('svobodnye-legkie-tsepi-kappa-i-lyambda', 'Свободные лёгкие цепи каппа и лямбда (свободные лёгкие цепи, FLC, kappa/lambda, каппа/лямбда соотношение)', 'Биохимия', 'белковый обмен', 'Определение свободных лёгких цепей каппа и лямбда для диагностики и мониторинга миеломы и парапротеинемий.', 'Утром натощак, 8–12 ч голодания; можно пить воду. Накануне исключить алкоголь.', 116);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('krioglobuliny', 'Криоглобулины (cryoglobulins, криоглобулинемия, холодовые белки)', 'Биохимия', 'белковый обмен', 'Выявление криоглобулинов в крови при васкулитах, инфекциях и аутоиммунных заболеваниях.', 'Утром натощак. Важно: пробу берут и доставляют в тепле (37 °C) — уточните условия взятия в лаборатории заранее.', 117);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('bilirubin-obschiy', 'Билирубин общий (общий билирубин, total bilirubin, TBIL)', 'Биохимия', 'Обмен пигментов', 'Определение общего билирубина в крови для диагностики желтух, болезней печени и жёлчевыводящих путей.', 'Утром натощак, 8–12 ч голодания; можно пить воду. Накануне исключить алкоголь и жирную пищу.', 118);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('bilirubin-pryamoy', 'Билирубин прямой (связанный билирубин, конъюгированный билирубин, direct bilirubin, DBIL)', 'Биохимия', 'Обмен пигментов', 'Определение прямого (связанного) билирубина для диагностики холестаза и болезней печени и жёлчных путей.', 'Утром натощак, 8–12 ч голодания; можно пить воду. Накануне исключить алкоголь и жирную пищу.', 119);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('bilirubin-nepryamoy', 'Билирубин непрямой (несвязанный билирубин, свободный билирубин, indirect bilirubin, IBIL)', 'Биохимия', 'Обмен пигментов', 'Определение непрямого (несвязанного) билирубина для диагностики гемолиза и наследственных желтух.', 'Утром натощак, 8–12 ч голодания; можно пить воду. Накануне исключить алкоголь и жирную пищу.', 120);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('zhelchnye-kisloty', 'Жёлчные кислоты (желчные кислоты, bile acids, общие жёлчные кислоты)', 'Биохимия', 'Обмен пигментов', 'Определение жёлчных кислот в крови для оценки функции печени и диагностики холестаза, в том числе при беременности.', 'Утром строго натощак, 8–12 ч голодания; можно пить воду. Накануне исключить алкоголь и жирную пищу.', 121);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('b-crosslaps', 'B-CrossLaps (β-CrossLaps, С-концевые телопептиды коллагена I типа, CTx, бета-кросслапс)', 'Биохимия', 'Костный метаболизм', 'Маркер резорбции костной ткани для диагностики остеопороза и контроля антирезорбтивной терапии.', 'Утром строго натощак, 8–12 ч голодания; можно пить воду. Сдавать в утренние часы из-за суточных колебаний показателя.', 122);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('kaltsitonin', 'Кальцитонин (calcitonin, тиреокальцитонин, онкомаркер медуллярного рака)', 'Биохимия', 'Костный метаболизм', 'Определение кальцитонина для диагностики медуллярного рака щитовидной железы и оценки кальциевого обмена.', 'Утром строго натощак, 8–12 ч голодания; можно пить воду. Накануне исключить алкоголь и интенсивные нагрузки.', 123);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('osteokaltsin', 'Остеокальцин (osteocalcin, костный Gla-белок, BGP, маркер костеобразования)', 'Биохимия', 'Костный метаболизм', 'Маркер формирования костной ткани для оценки метаболизма кости и диагностики остеопороза.', 'Утром строго натощак, 8–12 ч голодания; можно пить воду. Сдавать в утренние часы из-за суточных колебаний показателя.', 124);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('p1np', 'P1NP (N-концевой пропептид проколлагена I типа, total P1NP, маркер костеобразования)', 'Биохимия', 'Костный метаболизм', 'Маркер формирования костной ткани для диагностики остеопороза и контроля терапии.', 'Утром натощак, 8–12 ч голодания; можно пить воду. Сдавать в утренние часы из-за суточных колебаний показателя.', 125);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('kostnaya-schelochnaya-fosfataza', 'Костная щелочная фосфатаза (костный изофермент ЩФ, bone ALP, BALP, остаза)', 'Биохимия', 'Костный метаболизм', 'Определение костной фракции щелочной фосфатазы как маркера активности костеобразования при болезнях костей.', 'Утром натощак, 8–12 ч голодания; можно пить воду. Накануне исключить алкоголь.', 126);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('dezoksipiridinolin-v-moche', 'Дезоксипиридинолин в моче (ДПИД, DPD, deoxypyridinoline, маркер резорбции кости)', 'Биохимия', 'Костный метаболизм', 'Маркер резорбции костной ткани в моче для диагностики остеопороза и контроля лечения.', 'Собрать вторую утреннюю порцию мочи в чистый контейнер. Женщинам не сдавать во время менструации.', 127);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('ntx', 'NTx (N-телопептид коллагена I типа, cross-linked N-telopeptide, маркер резорбции кости)', 'Биохимия', 'Костный метаболизм', 'Маркер резорбции костной ткани для диагностики остеопороза и оценки эффективности терапии.', 'Утром натощак, 8–12 ч голодания; можно пить воду. При сдаче в моче — вторая утренняя порция; сдавать в утренние часы.', 128);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('alfa-1-antitripsin', 'Альфа-1-антитрипсин (α1-антитрипсин, alpha-1 antitrypsin, A1AT, ингибитор протеаз)', 'Биохимия', 'специфические белки', 'Определение альфа-1-антитрипсина для диагностики его дефицита при болезнях лёгких и печени и оценки воспаления.', 'Утром натощак, 8–12 ч голодания; можно пить воду. Накануне исключить алкоголь и интенсивные нагрузки.', 129);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('alfa-2-makroglobulin', 'Альфа-2-макроглобулин (α2-макроглобулин, alpha-2 macroglobulin, A2M, маркер фиброза)', 'Биохимия', 'специфические белки', 'Определение альфа-2-макроглобулина для оценки воспаления, функции почек и как компонента оценки фиброза печени.', 'Утром натощак, 8–12 ч голодания; можно пить воду. Накануне исключить алкоголь.', 130);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('gaptoglobin', 'Гаптоглобин (haptoglobin, HP, маркер гемолиза)', 'Биохимия', 'специфические белки', 'Определение гаптоглобина для диагностики гемолиза эритроцитов и оценки воспалительных процессов.', 'Утром натощак, 8–12 ч голодания; можно пить воду. Накануне исключить алкоголь.', 131);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('prokaltsitonin', 'Прокальцитонин (ПКТ, PCT, procalcitonin, маркер бактериальной инфекции и сепсиса)', 'Биохимия', 'специфические белки', 'Определение прокальцитонина для диагностики бактериальных инфекций, сепсиса и оценки тяжести состояния.', 'Утром натощак, 8–12 ч голодания; можно пить воду. При неотложных показаниях сдаётся в любое время.', 132);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('s-reaktivnyy-belok', 'С-реактивный белок (СРБ, CRP, C-reactive protein, маркер воспаления)', 'Биохимия', 'специфические белки', 'Определение С-реактивного белка — маркера острого воспаления, инфекций и повреждения тканей.', 'Утром натощак, 8–12 ч голодания; можно пить воду. Накануне исключить алкоголь и интенсивные нагрузки.', 133);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('vysokochuvstvitelnyy-s-reaktivnyy-belok', 'Высокочувствительный С-реактивный белок (hs-СРБ, hs-CRP, high-sensitivity CRP, кардиориск)', 'Биохимия', 'специфические белки', 'Высокочувствительное определение СРБ для оценки сердечно-сосудистого риска и вялотекущего воспаления.', 'Утром натощак, 8–12 ч голодания; можно пить воду. Накануне исключить алкоголь и интенсивные нагрузки; не сдавать при остром заболевании.', 134);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('mioglobin', 'Миоглобин (myoglobin, MYO, ранний маркер повреждения миокарда и мышц)', 'Биохимия', 'специфические белки', 'Определение миоглобина как раннего маркера повреждения сердечной и скелетных мышц, в том числе при инфаркте.', 'Утром натощак, 8–12 ч голодания; можно пить воду. Накануне исключить интенсивные физические нагрузки.', 135);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('presepsin', 'Пресепсин (presepsin, sCD14-ST, маркер сепсиса)', 'Биохимия', 'специфические белки', 'Определение пресепсина для ранней диагностики сепсиса и оценки тяжести бактериальной инфекции.', 'Специальной подготовки не требуется; при неотложных показаниях сдаётся в любое время. Желательно натощак.', 136);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('n-peptid-kollagena-iii-tipa', 'N-пептид проколлагена III типа (P3NP, PIIINP, N-пептид коллагена III типа, маркер фиброза)', 'Биохимия', 'специфические белки', 'Определение P3NP как маркера фиброза печени и активности процессов образования соединительной ткани.', 'Утром натощак, 8–12 ч голодания; можно пить воду. Накануне исключить алкоголь и интенсивные нагрузки.', 137);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('mxa-crp', 'MxA и СРБ, дифференцировка вирусной и бактериальной инфекции (MxA/CRP, MxA, FebriDx, вирус или бактерия)', 'Биохимия', 'специфические белки', 'Совместное определение MxA и СРБ для различения вирусной и бактериальной природы инфекции.', 'Специальной подготовки не требуется. Желательно сдавать в острый период заболевания.', 138);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('alaninaminotransferaza', 'Аланинаминотрансфераза (АЛТ, АлАТ, ALT, аланинтрансаминаза)', 'Биохимия', 'ферменты', 'Определение АЛТ — ключевого фермента-маркера повреждения печени; используется в диагностике гепатитов.', 'Утром натощак, 8–12 ч голодания; можно пить воду. Накануне исключить алкоголь и интенсивные физические нагрузки.', 139);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('alfa-amilaza-3', 'Альфа-амилаза (диастаза, амилаза крови, alpha-amylase, амилаза сыворотки)', 'Биохимия', 'ферменты', 'Определение амилазы в крови для диагностики панкреатита и болезней поджелудочной и слюнных желёз.', 'Утром натощак, 8–12 ч голодания; можно пить воду. Накануне исключить алкоголь и жирную пищу.', 140);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('aspartataminotransferaza', 'Аспартатаминотрансфераза (АСТ, АсАТ, AST, аспартаттрансаминаза)', 'Биохимия', 'ферменты', 'Определение АСТ — фермента-маркера повреждения печени и миокарда; применяется в диагностике гепатитов и инфаркта.', 'Утром натощак, 8–12 ч голодания; можно пить воду. Накануне исключить алкоголь и интенсивные физические нагрузки.', 141);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('gamma-glutamiltranspeptidaza', 'Гамма-глутамилтранспептидаза (ГГТ, ГГТП, GGT, гамма-ГТ)', 'Биохимия', 'ферменты', 'Определение ГГТ — чувствительного маркера холестаза, болезней печени и алкогольного повреждения.', 'Утром натощак, 8–12 ч голодания; можно пить воду. Накануне обязательно исключить алкоголь.', 142);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('kreatinkinaza', 'Креатинкиназа (КФК, КК, CK, creatine kinase, креатинфосфокиназа)', 'Биохимия', 'ферменты', 'Определение креатинкиназы — маркера повреждения сердечной и скелетных мышц, в том числе при инфаркте.', 'Утром натощак, 8–12 ч голодания; можно пить воду. За 2–3 дня исключить интенсивные физические нагрузки и внутримышечные инъекции.', 143);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('laktatdegidrogenaza', 'Лактатдегидрогеназа (ЛДГ, LDH, lactate dehydrogenase)', 'Биохимия', 'ферменты', 'Определение ЛДГ — маркера повреждения тканей при болезнях сердца, печени, крови и мышц.', 'Утром натощак, 8–12 ч голодания; можно пить воду. Накануне исключить интенсивные физические нагрузки.', 144);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('lipaza', 'Липаза (lipase, липаза крови, панкреатическая липаза)', 'Биохимия', 'ферменты', 'Определение липазы — специфичного фермента-маркера острого и хронического панкреатита.', 'Утром натощак, 8–12 ч голодания; можно пить воду. Накануне исключить алкоголь и жирную пищу.', 145);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('fosfataza-kislaya-obschaya', 'Кислая фосфатаза общая (КФ, ACP, acid phosphatase, кислая фосфатаза)', 'Биохимия', 'ферменты', 'Определение общей кислой фосфатазы; используется при болезнях костей и предстательной железы.', 'Утром натощак, 8–12 ч голодания; можно пить воду. Мужчинам за 2–3 дня исключить массаж простаты и езду на велосипеде.', 146);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('fosfataza-schelochnaya', 'Щелочная фосфатаза (ЩФ, ALP, alkaline phosphatase, фосфатаза щелочная)', 'Биохимия', 'ферменты', 'Определение щелочной фосфатазы — маркера болезней печени, жёлчных путей и костной ткани.', 'Утром натощак, 8–12 ч голодания; можно пить воду. Накануне исключить алкоголь и жирную пищу.', 147);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('holinesteraza', 'Холинэстераза (ХЭ, ChE, cholinesterase, псевдохолинэстераза, бутирилхолинэстераза)', 'Биохимия', 'ферменты', 'Определение холинэстеразы для оценки функции печени и диагностики отравления фосфорорганическими веществами.', 'Утром натощак, 8–12 ч голодания; можно пить воду. Накануне исключить алкоголь.', 148);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('alfa-gbdg', 'Альфа-гидроксибутиратдегидрогеназа (α-ГБДГ, HBDH, альфа-ГБДГ, гидроксибутиратдегидрогеназа)', 'Биохимия', 'ферменты', 'Определение α-ГБДГ (изофермента ЛДГ) как маркера повреждения миокарда, в том числе при инфаркте.', 'Утром натощак, 8–12 ч голодания; можно пить воду. Накануне исключить интенсивные физические нагрузки.', 149);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('amilaza-pankreaticheskaya', 'Амилаза панкреатическая, P-изофермент (панкреатическая амилаза, P-амилаза, pancreatic amylase, P-тип)', 'Биохимия', 'ферменты', 'Определение панкреатической фракции амилазы — более специфичного маркера болезней поджелудочной железы.', 'Утром натощак, 8–12 ч голодания; можно пить воду. Накануне исключить алкоголь и жирную пищу.', 150);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('angiotenzinprevraschayuschiy-ferment', 'Ангиотензинпревращающий фермент (АПФ, ACE, angiotensin-converting enzyme, маркер саркоидоза)', 'Биохимия', 'ферменты', 'Определение АПФ; применяется преимущественно в диагностике и мониторинге саркоидоза.', 'Утром натощак, 8–12 ч голодания; можно пить воду. По согласованию с врачом заранее обсудить приём ингибиторов АПФ.', 151);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('5-nukleotidaza', '5-нуклеотидаза (5-НТ, 5''-nucleotidase, 5-NT, маркер холестаза)', 'Биохимия', 'ферменты', 'Определение 5-нуклеотидазы — специфичного маркера холестаза и болезней печени и жёлчных путей.', 'Утром натощак, 8–12 ч голодания; можно пить воду. Накануне исключить алкоголь.', 152);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('izofermenty-ldg', 'Изоферменты ЛДГ, ЛДГ 1-5 (фракции ЛДГ, LDH isoenzymes, изоферменты лактатдегидрогеназы)', 'Биохимия', 'ферменты', 'Разделение ЛДГ на фракции 1-5 для уточнения источника повреждения тканей (сердце, печень, мышцы, кровь).', 'Утром натощак, 8–12 ч голодания; можно пить воду. Накануне исключить интенсивные физические нагрузки.', 153);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('kreatinkinaza-mv', 'Креатинкиназа-МВ (КФК-МВ, CK-MB, MB-фракция креатинкиназы, кардиальная КФК)', 'Биохимия', 'кардиомаркеры', 'Определение МВ-фракции креатинкиназы — маркера повреждения миокарда, в том числе при инфаркте.', 'Специальной подготовки не требуется; при неотложных показаниях сдаётся в любое время. Желательно натощак, накануне исключить интенсивные нагрузки.', 154);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('laktatdegidrogenaza-1-aya-fraktsiya', 'Лактатдегидрогеназа, 1-я фракция (ЛДГ-1, LDH-1, кардиальная фракция ЛДГ)', 'Биохимия', 'кардиомаркеры', 'Определение первой фракции ЛДГ как маркера повреждения миокарда при инфаркте и болезнях сердца.', 'Утром натощак, 8–12 ч голодания; можно пить воду. Накануне исключить интенсивные физические нагрузки.', 155);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('peptid-n-kontsevoy-natriyureticheskiy-b-tipa', 'N-концевой натрийуретический пептид B-типа (NT-proBNP, мозговой натрийуретический пептид, маркер сердечной недостаточности)', 'Биохимия', 'кардиомаркеры', 'Определение NT-proBNP для диагностики и оценки тяжести сердечной недостаточности.', 'Специальной подготовки не требуется, сдаётся в любое время. Перед сдачей отдохнуть 15–30 минут в покое.', 156);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('troponin-i', 'Тропонин I (cTnI, troponin I, кардиальный тропонин I)', 'Биохимия', 'кардиомаркеры', 'Определение тропонина I — специфичного маркера повреждения миокарда для диагностики инфаркта.', 'Специальной подготовки не требуется; при неотложных показаниях сдаётся в любое время.', 157);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('troponin-t', 'Тропонин T (cTnT, troponin T, кардиальный тропонин T)', 'Биохимия', 'кардиомаркеры', 'Определение тропонина T — специфичного маркера повреждения сердечной мышцы при инфаркте миокарда.', 'Специальной подготовки не требуется; при неотложных показаниях сдаётся в любое время.', 158);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('troponin-i-vysokochuvstvitelnyy', 'Тропонин I высокочувствительный (hs-cTnI, high-sensitivity troponin I, высокочувствительный тропонин)', 'Биохимия', 'кардиомаркеры', 'Высокочувствительное определение тропонина I для ранней диагностики инфаркта миокарда.', 'Специальной подготовки не требуется; при неотложных показаниях сдаётся в любое время.', 159);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('mioglobin-2', 'Миоглобин кардиальный (myoglobin, MYO, ранний маркер инфаркта миокарда)', 'Биохимия', 'кардиомаркеры', 'Определение миоглобина — раннего маркера повреждения миокарда в первые часы инфаркта.', 'Специальной подготовки не требуется; при неотложных показаниях сдаётся в любое время. Накануне исключить интенсивные нагрузки.', 160);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('bnp', 'BNP (мозговой натрийуретический пептид, brain natriuretic peptide, маркер сердечной недостаточности)', 'Биохимия', 'кардиомаркеры', 'Определение BNP для диагностики и оценки тяжести сердечной недостаточности.', 'Специальной подготовки не требуется, сдаётся в любое время. Перед сдачей отдохнуть 15–30 минут в покое.', 161);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('st2', 'ST2 (растворимый ST2, sST2, маркер риска сердечной недостаточности)', 'Биохимия', 'кардиомаркеры', 'Определение ST2 для оценки риска и прогноза при сердечной недостаточности.', 'Специальной подготовки не требуется. Желательно сдавать в покое, накануне исключить интенсивные нагрузки.', 162);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('holesterol-lpvp', 'Холестерин ЛПВП (ЛПВП, HDL, HDL-C, «хороший» холестерин, липопротеины высокой плотности)', 'Биохимия', 'Липидный обмен', 'Определение холестерина ЛПВП («хорошего») для оценки риска атеросклероза и сердечно-сосудистых заболеваний.', 'Утром натощак, 12–14 ч голодания; можно пить воду. Накануне исключить алкоголь и жирную пищу.', 163);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('holesterol-lpnp', 'Холестерин ЛПНП (ЛПНП, LDL, LDL-C, «плохой» холестерин, липопротеины низкой плотности)', 'Биохимия', 'Липидный обмен', 'Определение холестерина ЛПНП («плохого») — ключевого показателя риска атеросклероза и болезней сердца.', 'Утром натощак, 12–14 ч голодания; можно пить воду. Накануне исключить алкоголь и жирную пищу.', 164);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('holesterol-obschiy', 'Холестерин общий (общий холестерин, холестерол, total cholesterol, TC)', 'Биохимия', 'Липидный обмен', 'Определение общего холестерина для оценки липидного обмена и риска сердечно-сосудистых заболеваний.', 'Утром натощак, 12–14 ч голодания; можно пить воду. Накануне исключить алкоголь и жирную пищу.', 165);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('triglitseridy', 'Триглицериды (ТГ, triglycerides, TG, нейтральные жиры)', 'Биохимия', 'Липидный обмен', 'Определение триглицеридов для оценки липидного обмена и риска атеросклероза и панкреатита.', 'Утром строго натощак, 12–14 ч голодания; можно пить воду. Накануне обязательно исключить алкоголь и жирную пищу.', 166);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('lipoprotein', 'Липопротеин (а) (ЛП(а), Lp(a), lipoprotein a)', 'Биохимия', 'Липидный обмен', 'Определение липопротеина (а) — независимого наследственного фактора риска атеросклероза и тромбозов.', 'Утром натощак, 12–14 ч голодания; можно пить воду. Накануне исключить алкоголь и жирную пищу.', 167);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('lipidogramma', 'Липидограмма (липидный профиль, липидный спектр, lipid panel: индекс атерогенности, ТГ, общий ХС, ЛПВП, ЛПНП, ЛПОНП)', 'Биохимия', 'Липидный обмен', 'Комплексная оценка липидного обмена для расчёта риска атеросклероза и сердечно-сосудистых заболеваний.', 'Утром строго натощак, 12–14 ч голодания; можно пить воду. Накануне исключить алкоголь и жирную пищу.', 168);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('indeks-aterogennosti', 'Индекс атерогенности (коэффициент атерогенности, КА, atherogenic index, включая холестерин и ЛПВП)', 'Биохимия', 'Липидный обмен', 'Расчётный показатель соотношения атерогенных и защитных липидов для оценки риска атеросклероза.', 'Утром натощак, 12–14 ч голодания; можно пить воду. Накануне исключить алкоголь и жирную пищу.', 169);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('gomotsistein', 'Гомоцистеин (homocysteine, HCY, гомоцистеин крови)', 'Биохимия', 'Липидный обмен', 'Определение гомоцистеина — фактора риска атеросклероза, тромбозов и осложнений беременности.', 'Утром натощак, 8–12 ч голодания; можно пить воду. Накануне исключить алкоголь; по согласованию с врачом обсудить приём витаминов группы B.', 170);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('apolipoprotein-a1', 'Аполипопротеин А1 (АпоА1, ApoA1, apolipoprotein A1)', 'Биохимия', 'Липидный обмен', 'Определение аполипопротеина А1 — основного белка ЛПВП; используется для уточнённой оценки риска атеросклероза.', 'Утром натощак, 12–14 ч голодания; можно пить воду. Накануне исключить алкоголь и жирную пищу.', 171);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('apolipoprotein-b', 'Аполипопротеин B (АпоB, ApoB, apolipoprotein B)', 'Биохимия', 'Липидный обмен', 'Определение аполипопротеина B — основного белка атерогенных липопротеинов; маркер риска атеросклероза.', 'Утром натощак, 12–14 ч голодания; можно пить воду. Накануне исключить алкоголь и жирную пищу.', 172);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('holesterol-lponp', 'Холестерин ЛПОНП (ЛПОНП, VLDL, VLDL-C, липопротеины очень низкой плотности)', 'Биохимия', 'Липидный обмен', 'Определение холестерина ЛПОНП как компонента липидного профиля и оценки риска атеросклероза.', 'Утром натощак, 12–14 ч голодания; можно пить воду. Накануне исключить алкоголь и жирную пищу.', 173);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('lipoprotein-assotsiirovannaya-fosfolipaza-a2', 'Липопротеин-ассоциированная фосфолипаза A2 (Lp-PLA2, ЛП-ФЛА2, маркер нестабильности атеросклеротической бляшки)', 'Биохимия', 'Липидный обмен', 'Определение Lp-PLA2 для оценки риска инфаркта и инсульта, связанного с воспалением сосудистой стенки.', 'Утром натощак, 12–14 ч голодания; можно пить воду. Накануне исключить алкоголь и жирную пищу.', 174);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('sootnoshenie-apolipoproteinov-b-a1', 'Соотношение аполипопротеинов B/A1 (АпоB/АпоA1, ApoB/ApoA1 ratio, апо-соотношение)', 'Биохимия', 'Липидный обмен', 'Расчёт соотношения аполипопротеинов B/A1 для точной оценки сердечно-сосудистого риска.', 'Утром натощак, 12–14 ч голодания; можно пить воду. Накануне исключить алкоголь и жирную пищу.', 175);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('kschs-bazovyy', 'Кислотно-щелочное состояние, базовое (КЩС, КОС, газы крови, pH, pCO₂, pO₂, HCO₃, BE, blood gas)', 'Биохимия', 'Газы и КЩС', 'Определение газов и кислотно-щелочного баланса крови для оценки дыхания, обмена и тяжести состояния.', 'Специальной подготовки не требуется; выполняется по показаниям, часто экстренно. Перед забором находиться в покое, не задерживать дыхание.', 176);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('kschs-rasshirennyy', 'Кислотно-щелочное состояние, расширенное (КЩС расширенный, КОС + электролиты, лактат, глюкоза, Ht, blood gas extended)', 'Биохимия', 'Газы и КЩС', 'Расширенная оценка газов крови с электролитами, лактатом, глюкозой и гематокритом для полной картины метаболизма.', 'Специальной подготовки не требуется; выполняется по показаниям, часто экстренно. Перед забором находиться в покое.', 177);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('laktat', 'Лактат (молочная кислота, lactate, lactic acid, лактат крови)', 'Биохимия', 'Газы и КЩС', 'Определение лактата в крови для оценки тканевой гипоксии, тяжести состояния и метаболических нарушений.', 'Утром натощак, в покое. Перед забором не сжимать кулак и не нагружаться; исключить физическую нагрузку и стресс накануне.', 178);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('ammiak', 'Аммиак (ammonia, NH₃, аммиак крови)', 'Биохимия', 'Газы и КЩС', 'Определение аммиака в крови для диагностики печёночной энцефалопатии и нарушений обмена белка.', 'Утром строго натощак, в покое. Накануне исключить алкоголь и курение; не курить утром перед сдачей.', 179);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('osmolyalnost-krovi', 'Осмоляльность крови (осмолярность плазмы, osmolality, осмоляльность сыворотки)', 'Биохимия', 'Газы и КЩС', 'Определение осмоляльности крови для оценки водно-солевого баланса и диагностики нарушений гидратации.', 'Утром натощак, 8–12 ч голодания; можно пить воду в обычном режиме. Накануне исключить алкоголь.', 180);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('kreatinin-2', 'Креатинин (creatinine, креатинин крови, CREA)', 'Биохимия', 'почечные показатели', 'Определение креатинина в крови — основного показателя функции почек и расчёта СКФ.', 'Утром натощак, 8–12 ч голодания; можно пить воду. Накануне исключить интенсивные нагрузки и избыток мясной пищи.', 181);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('mochevaya-kislota-2', 'Мочевая кислота (uric acid, UA, мочевая кислота крови, маркер подагры)', 'Биохимия', 'почечные показатели', 'Определение мочевой кислоты в крови для диагностики подагры и оценки обмена пуринов и функции почек.', 'Утром натощак, 8–12 ч голодания; можно пить воду. Накануне исключить алкоголь, мясной избыток и интенсивные нагрузки.', 182);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('mochevina-2', 'Мочевина (urea, BUN, мочевина крови)', 'Биохимия', 'почечные показатели', 'Определение мочевины в крови для оценки функции почек и белкового обмена.', 'Утром натощак, 8–12 ч голодания; можно пить воду. Накануне исключить избыток мясной пищи и интенсивные нагрузки.', 183);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('tsistatin-s', 'Цистатин С (cystatin C, CST3, цистатин Ц, маркер СКФ)', 'Биохимия', 'почечные показатели', 'Определение цистатина С — чувствительного маркера функции почек, точнее креатинина на ранних стадиях.', 'Утром натощак, 8–12 ч голодания; можно пить воду. Накануне исключить алкоголь.', 184);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('proba-reberga', 'Проба Реберга (клиренс креатинина, проба Реберга-Тареева, creatinine clearance)', 'Биохимия', 'почечные показатели', 'Оценка клиренса креатинина по крови и суточной моче для точного измерения фильтрационной функции почек.', 'Собрать суточную мочу (первую утреннюю порцию слить, указать объём) и утром сдать кровь натощак. Накануне исключить мясной избыток, чай, кофе и нагрузки.', 185);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('skf-raschetnaya', 'СКФ расчётная, CKD-EPI (расчётная скорость клубочковой фильтрации, eGFR, СКФ по CKD-EPI)', 'Биохимия', 'почечные показатели', 'Расчёт скорости клубочковой фильтрации по креатинину для оценки и стадирования функции почек.', 'Утром натощак, 8–12 ч голодания; можно пить воду. Накануне исключить избыток мясной пищи и интенсивные нагрузки.', 186);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('gastrin-17', 'Гастрин-17 (G-17, гастрин 17, gastrin-17, базальный гастрин)', 'Биохимия', 'гастропанель (ЖКТ)', 'Определение гастрина-17 для оценки состояния слизистой антрального отдела желудка в составе гастропанели.', 'Утром строго натощак, 10–12 ч голодания; можно пить воду. За 7 дней (по согласованию с врачом) отменить ингибиторы протонной помпы, за 1 день — антациды.', 187);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('pepsinogen-i', 'Пепсиноген I (ПГ I, PGI, pepsinogen I, пепсиноген 1)', 'Биохимия', 'гастропанель (ЖКТ)', 'Определение пепсиногена I для оценки состояния слизистой тела желудка и диагностики атрофического гастрита.', 'Утром строго натощак, 10–12 ч голодания; можно пить воду. За 7 дней (по согласованию с врачом) отменить ингибиторы протонной помпы, за 1 день — антациды.', 188);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('pepsinogen-ii', 'Пепсиноген II (ПГ II, PGII, pepsinogen II, пепсиноген 2)', 'Биохимия', 'гастропанель (ЖКТ)', 'Определение пепсиногена II для оценки состояния слизистой желудка и выявления воспаления в составе гастропанели.', 'Утром строго натощак, 10–12 ч голодания; можно пить воду. За 7 дней (по согласованию с врачом) отменить ингибиторы протонной помпы, за 1 день — антациды.', 189);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('pepsinogen-i-i-ii-s-sootnosheniem', 'Пепсиноген I и II с соотношением (ПГ I/ПГ II, соотношение пепсиногенов, pepsinogen I/II ratio)', 'Биохимия', 'гастропанель (ЖКТ)', 'Определение пепсиногенов I и II с расчётом соотношения для диагностики атрофического гастрита и риска рака желудка.', 'Утром строго натощак, 10–12 ч голодания; можно пить воду. За 7 дней (по согласованию с врачом) отменить ингибиторы протонной помпы, за 1 день — антациды.', 190);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('organicheskie-kisloty-v-moche-skrining-novorozhdennyh-i-dete', 'Органические кислоты в моче, скрининг новорождённых и детей до 2 лет, 40 показателей (органические ацидурии, профиль органических кислот, неонатальный скрининг, organic acids urine, метаболический скрининг)', 'Биохимия', 'наследственные болезни обмена', 'Определение органических кислот в моче для раннего выявления наследственных болезней обмена у детей до 2 лет.', 'Собрать порцию мочи в чистый контейнер. Сохранять обычный режим кормления; за 1–2 дня по согласованию с врачом уточнить отмену карнитина и лекарств.', 191);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('organicheskie-kisloty-v-moche-funktsionalnye-metabolicheskie', 'Органические кислоты в моче, 60 показателей (органические ацидурии, профиль органических кислот, organic acids urine, метаболический скрининг)', 'Биохимия', 'наследственные болезни обмена', 'Определение спектра органических кислот в моче для диагностики наследственных болезней обмена (органических ацидурий).', 'Собрать утреннюю порцию мочи в чистый контейнер. За 1–2 дня по согласованию с врачом не менять резко рацион; уточнить отмену карнитина и лекарств.', 192);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('aminokisloty-i-atsilkarnitiny-krovi', 'Аминокислоты и ацилкарнитины крови, тандемная масс-спектрометрия (ТМС, MS/MS, аминоацидопатии, пятно крови, tandem mass spectrometry)', 'Биохимия', 'наследственные болезни обмена', 'Определение аминокислот и ацилкарнитинов методом масс-спектрометрии для скрининга наследственных болезней обмена.', 'Кровь берут натощак или до кормления (у детей). За несколько дней по согласованию с врачом уточнить отмену карнитина и особенности диеты.', 193);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('tireotropnyy-gormon', 'Тиреотропный гормон (ТТГ, TSH, тиротропин, тиреотропин)', 'Гормоны', 'Щитовидная железа', 'Определение ТТГ — основного показателя функции щитовидной железы для диагностики гипо- и гипертиреоза.', 'Утром натощак; можно пить воду. За 2–3 дня отменить биотин; приём препаратов для щитовидной железы согласовать с врачом. Накануне исключить стресс и нагрузки.', 194);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('t4-svobodnyy', 'Т4 свободный (свободный тироксин, FT4, free T4, св. Т4)', 'Гормоны', 'Щитовидная железа', 'Определение свободного тироксина для оценки функции щитовидной железы и диагностики её нарушений.', 'Утром натощак; можно пить воду. За 2–3 дня отменить биотин; тироксин принять после забора крови (согласовать с врачом).', 195);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('t4-obschiy', 'Т4 общий (общий тироксин, TT4, total T4, общ. Т4)', 'Гормоны', 'Щитовидная железа', 'Определение общего тироксина для оценки функции щитовидной железы.', 'Утром натощак; можно пить воду. За 2–3 дня отменить биотин; приём тиреоидных препаратов согласовать с врачом.', 196);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('t3-svobodnyy', 'Т3 свободный (свободный трийодтиронин, FT3, free T3, св. Т3)', 'Гормоны', 'Щитовидная железа', 'Определение свободного трийодтиронина для оценки функции щитовидной железы, особенно при тиреотоксикозе.', 'Утром натощак; можно пить воду. За 2–3 дня отменить биотин; приём тиреоидных препаратов согласовать с врачом.', 197);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('t3-obschiy', 'Т3 общий (общий трийодтиронин, TT3, total T3, общ. Т3)', 'Гормоны', 'Щитовидная железа', 'Определение общего трийодтиронина для оценки функции щитовидной железы.', 'Утром натощак; можно пить воду. За 2–3 дня отменить биотин; приём тиреоидных препаратов согласовать с врачом.', 198);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('paratireoidnyy-gormon', 'Паратиреоидный гормон (ПТГ, PTH, паратгормон, паратирин)', 'Гормоны', 'Щитовидная железа', 'Определение паратгормона для оценки обмена кальция и диагностики болезней паращитовидных желёз.', 'Утром натощак; можно пить воду. За 2–3 дня отменить биотин. Желательно сдавать в утренние часы из-за суточных колебаний.', 199);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('t3-obratnyy', 'Т3 обратный (реверсивный Т3, rT3, reverse T3, обратный трийодтиронин)', 'Гормоны', 'Щитовидная железа', 'Определение обратного (реверсивного) Т3 для уточнённой оценки метаболизма тиреоидных гормонов.', 'Утром натощак; можно пить воду. За 2–3 дня отменить биотин; приём тиреоидных препаратов согласовать с врачом.', 200);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('tiroksinsvyazyvayuschiy-globulin', 'Тироксинсвязывающий глобулин (ТСГ, TBG, thyroxine-binding globulin)', 'Гормоны', 'Щитовидная железа', 'Определение тироксинсвязывающего глобулина — основного транспортного белка тиреоидных гормонов.', 'Утром натощак; можно пить воду. За 2–3 дня отменить биотин. Сообщить врачу о приёме эстрогенов и контрацептивов.', 201);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('tireoglobulin', 'Тиреоглобулин (ТГ, Tg, thyroglobulin, функция щитовидной железы)', 'Гормоны', 'Щитовидная железа', 'Определение тиреоглобулина для оценки функции щитовидной железы и контроля после лечения рака ЩЖ.', 'Утром натощак; можно пить воду. За 2–3 дня отменить биотин. Сдавать до или спустя время после пункции/операции ЩЖ (согласовать с врачом).', 202);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('androstendion', 'Андростендион (androstenedione, А4, андростендион крови)', 'Гормоны', 'Половые гормоны', 'Определение андростендиона для оценки синтеза половых гормонов и диагностики гиперандрогении.', 'Утром натощак; можно пить воду. Женщинам — в день цикла по назначению врача. За 2–3 дня отменить биотин, накануне исключить нагрузки и стресс.', 203);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('estradiol', 'Эстрадиол (Е2, estradiol, эстрадиол крови)', 'Гормоны', 'Половые гормоны', 'Определение эстрадиола для оценки функции яичников, менструального цикла и репродуктивного здоровья.', 'Утром натощак; можно пить воду. Женщинам — в день цикла по назначению врача. За 2–3 дня отменить биотин.', 204);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('follikulostimuliruyuschiy-gormon', 'Фолликулостимулирующий гормон (ФСГ, FSH, фоллитропин)', 'Гормоны', 'Половые гормоны', 'Определение ФСГ для оценки функции яичников и яичек, диагностики бесплодия и нарушений цикла.', 'Утром натощак; можно пить воду. Женщинам — в день цикла по назначению врача (обычно 2–5 день). За 2–3 дня отменить биотин.', 205);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('testosteron-svobodnyy', 'Тестостерон свободный (свободный тестостерон, free testosterone, св. тестостерон)', 'Гормоны', 'Половые гормоны', 'Определение свободной (активной) фракции тестостерона для оценки андрогенного статуса.', 'Утром натощак (до 11:00); можно пить воду. За 2–3 дня отменить биотин, накануне исключить нагрузки. Женщинам — в день цикла по назначению врача.', 206);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('testosteron-obschiy', 'Тестостерон общий (общий тестостерон, total testosterone, тестостерон крови)', 'Гормоны', 'Половые гормоны', 'Определение общего тестостерона для оценки андрогенного статуса, диагностики гипогонадизма и гиперандрогении.', 'Утром натощак (до 11:00); можно пить воду. За 2–3 дня отменить биотин, накануне исключить нагрузки. Женщинам — в день цикла по назначению врача.', 207);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('prolaktin', 'Пролактин (prolactin, PRL, лактотропный гормон)', 'Гормоны', 'Половые гормоны', 'Определение пролактина для диагностики нарушений цикла, бесплодия, галактореи и болезней гипофиза.', 'Утром натощак, через 2–3 ч после пробуждения; можно пить воду. За сутки исключить секс, стресс, баню и нагрузки. Перед забором отдохнуть 20–30 минут.', 208);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('progesteron', 'Прогестерон (progesterone, PRG, прогестерон крови)', 'Гормоны', 'Половые гормоны', 'Определение прогестерона для оценки овуляции, лютеиновой фазы и ведения беременности.', 'Утром натощак; можно пить воду. Женщинам — обычно на 19–23 день цикла или по назначению врача. За 2–3 дня отменить биотин.', 209);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('lyuteiniziruyuschiy-gormon', 'Лютеинизирующий гормон (ЛГ, LH, лютропин)', 'Гормоны', 'Половые гормоны', 'Определение ЛГ для оценки овуляции, функции яичников и яичек, диагностики бесплодия.', 'Утром натощак; можно пить воду. Женщинам — в день цикла по назначению врача (обычно 2–5 день). За 2–3 дня отменить биотин.', 210);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('ingibin-v', 'Ингибин В (inhibin B, ингибин Б)', 'Гормоны', 'Половые гормоны', 'Определение ингибина В для оценки овариального резерва у женщин и сперматогенеза у мужчин.', 'Утром натощак; можно пить воду. Женщинам — в день цикла по назначению врача (обычно 3–5 день). За 2–3 дня отменить биотин.', 211);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('globulin-svyazyvayuschiy-polovye-gormony', 'Глобулин, связывающий половые гормоны (ГСПГ, SHBG, ССГ, секс-стероид-связывающий глобулин)', 'Гормоны', 'Половые гормоны', 'Определение ГСПГ — транспортного белка половых гормонов; нужен для расчёта свободного тестостерона.', 'Утром натощак; можно пить воду. За 2–3 дня отменить биотин. Сообщить врачу о приёме гормонов и контрацептивов.', 212);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('gidroksiprogesteron', '17-ОН-прогестерон (17-OHP, гидроксипрогестерон, 17-гидроксипрогестерон)', 'Гормоны', 'Половые гормоны', 'Определение 17-ОН-прогестерона для диагностики врождённой дисфункции коры надпочечников и гиперандрогении.', 'Утром натощак; можно пить воду. Женщинам — в день цикла по назначению врача (обычно 2–5 день). За 2–3 дня отменить биотин.', 213);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('anti-myullerov-gormon', 'Антимюллеров гормон (АМГ, AMH, anti-Müllerian hormone, МИС)', 'Гормоны', 'Половые гормоны', 'Определение АМГ для оценки овариального резерва, планирования беременности и ЭКО.', 'Утром натощак; можно пить воду. Сдаётся в любой день цикла (или по назначению врача). За 2–3 дня отменить биотин, не сдавать при остром заболевании.', 214);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('digidrotestosteron', 'Дигидротестостерон (ДГТ, DHT, dihydrotestosterone)', 'Гормоны', 'Половые гормоны', 'Определение дигидротестостерона — активного андрогена; применяется при облысении, гирсутизме и болезнях простаты.', 'Утром натощак (до 11:00); можно пить воду. За 2–3 дня отменить биотин, накануне исключить нагрузки. Женщинам — в день цикла по назначению врача.', 215);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('indeks-svobodnogo-testosterona', 'Индекс свободного тестостерона (ИСТ, FTI, free testosterone index, расчёт по тестостерону и ГСПГ)', 'Гормоны', 'Половые гормоны', 'Расчётный показатель свободного тестостерона по общему тестостерону и ГСПГ для оценки андрогенного статуса.', 'Утром натощак (до 11:00); можно пить воду. За 2–3 дня отменить биотин. Женщинам — в день цикла по назначению врача.', 216);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('estron', 'Эстрон (Е1, estrone, эстрон крови)', 'Гормоны', 'Половые гормоны', 'Определение эстрона (Е1) для оценки эстрогенного статуса, в том числе в менопаузе.', 'Утром натощак; можно пить воду. Женщинам — в день цикла по назначению врача. За 2–3 дня отменить биотин.', 217);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('makroprolaktin', 'Макропролактин (пролактин с ПЭГ-преципитацией, macroprolactin, мономерный пролактин)', 'Гормоны', 'Половые гормоны', 'Определение макропролактина для уточнения истинной гиперпролактинемии при повышенном пролактине.', 'Утром натощак, через 2–3 ч после пробуждения; можно пить воду. За сутки исключить секс, стресс и нагрузки. Перед забором отдохнуть 20–30 минут.', 218);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('adrenokortikotropnyy-gormon', 'Адренокортикотропный гормон (АКТГ, ACTH, кортикотропин, адренокортикотропин)', 'Гормоны', 'Гормоны надпочечников', 'Определение АКТГ для диагностики болезней надпочечников и гипофиза (синдром Иценко-Кушинга, недостаточность).', 'Утром натощак, забор около 8:00 из-за суточного ритма; можно пить воду. Накануне исключить стресс, нагрузки и алкоголь. Проба доставляется в лабораторию на льду.', 219);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('aldosteron', 'Альдостерон (aldosterone, альдостерон крови)', 'Гормоны', 'Гормоны надпочечников', 'Определение альдостерона для диагностики артериальной гипертензии, связанной с надпочечниками, и нарушений калия.', 'Утром натощак; можно пить воду. За 2 недели по согласованию с врачом отменить влияющие препараты, за 3 дня — ограничить соль по указанию. Указать положение тела при заборе.', 220);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('degidroepiandrosteron-sulfat', 'Дегидроэпиандростерон-сульфат (ДЭА-С, ДГЭА-С, DHEA-S, дегидроэпиандростерона сульфат)', 'Гормоны', 'Гормоны надпочечников', 'Определение ДЭА-С — маркера андрогенной функции надпочечников; применяется при гиперандрогении.', 'Утром натощак; можно пить воду. За 2–3 дня отменить биотин, накануне исключить стресс и интенсивные нагрузки.', 221);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('renin', 'Ренин (renin, активность ренина плазмы, АРП, прямой ренин)', 'Гормоны', 'Гормоны надпочечников', 'Определение ренина для диагностики гипертензии, болезней надпочечников и оценки ренин-альдостероновой системы.', 'Утром натощак; можно пить воду. За 2 недели по согласованию с врачом отменить влияющие препараты. Указать положение тела; накануне не ограничивать резко соль.', 222);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('normetanefrin', 'Норметанефрин (normetanephrine, норметанефрин крови/мочи, метаболит норадреналина)', 'Гормоны', 'Гормоны надпочечников', 'Определение норметанефрина для диагностики феохромоцитомы и опухолей, продуцирующих катехоламины.', 'За 3 дня исключить кофе, чай, шоколад, цитрусы, ваниль, бананы; избегать стресса и нагрузок. Ряд препаратов отменить по согласованию с врачом.', 223);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('metanefrin', 'Метанефрин (metanephrine, метанефрин крови/мочи, метаболит адреналина)', 'Гормоны', 'Гормоны надпочечников', 'Определение метанефрина для диагностики феохромоцитомы и опухолей, продуцирующих катехоламины.', 'За 3 дня исключить кофе, чай, шоколад, цитрусы, ваниль, бананы; избегать стресса и нагрузок. Ряд препаратов отменить по согласованию с врачом.', 224);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('kortizol', 'Кортизол (cortisol, кортизол крови, гидрокортизон, гормон стресса)', 'Гормоны', 'Гормоны надпочечников', 'Определение кортизола для диагностики болезней надпочечников (синдром Иценко-Кушинга, надпочечниковая недостаточность).', 'Утром натощак, забор около 8:00 из-за суточного ритма; можно пить воду. Накануне исключить стресс, нагрузки и алкоголь.', 225);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('kortizol-v-slyune', 'Кортизол в слюне, ночной (ночной кортизол слюны, late-night salivary cortisol, свободный кортизол слюны)', 'Гормоны', 'Гормоны надпочечников', 'Определение ночного кортизола в слюне для диагностики синдрома Иценко-Кушинга.', 'Собрать слюну поздно вечером (около 23:00) в специальную пробирку. За 30–60 мин не есть, не пить, не курить и не чистить зубы.', 226);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('11-dezoksikortizol', '11-дезоксикортизол (11-deoxycortisol, соединение S, кортодоксон)', 'Гормоны', 'Гормоны надпочечников', 'Определение 11-дезоксикортизола для диагностики врождённой дисфункции коры надпочечников и оценки стероидогенеза.', 'Утром натощак, забор в утренние часы; можно пить воду. За 2–3 дня отменить биотин, накануне исключить стресс и нагрузки.', 227);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('androstendiola-glyukuronid', 'Андростандиола глюкуронид (3α-андростандиол глюкуронид, 3α-diol G, androstanediol glucuronide, маркер активности андрогенов)', 'Гормоны', 'Гормоны надпочечников', 'Определение андростандиола глюкуронида для оценки периферической активности андрогенов при гирсутизме.', 'Утром натощак; можно пить воду. Женщинам — в день цикла по назначению врача. За 2–3 дня отменить биотин.', 228);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('indeks-homa', 'Индекс HOMA (HOMA-IR, инсулинорезистентность, инсулин + глюкоза натощак, homeostasis model assessment)', 'Гормоны', 'Гормоны поджелудочной железы', 'Расчётный индекс по глюкозе и инсулину натощак для оценки инсулинорезистентности и риска диабета.', 'Утром строго натощак, 8–12 ч голодания; можно пить воду. Накануне исключить алкоголь, переедание и интенсивные нагрузки.', 229);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('insulin', 'Инсулин (insulin, инсулин крови, ИРИ, иммунореактивный инсулин)', 'Гормоны', 'Гормоны поджелудочной железы', 'Определение инсулина для диагностики инсулинорезистентности, гипогликемий и нарушений углеводного обмена.', 'Утром строго натощак, 8–12 ч голодания; можно пить воду. Накануне исключить алкоголь и интенсивные нагрузки. Приём сахароснижающих препаратов согласовать с врачом.', 230);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('s-peptid', 'С-пептид (C-peptide, соединительный пептид, connecting peptide)', 'Гормоны', 'Гормоны поджелудочной железы', 'Определение С-пептида для оценки собственной секреции инсулина поджелудочной железой при диабете.', 'Утром строго натощак, 8–12 ч голодания; можно пить воду. Накануне исключить алкоголь. Приём сахароснижающих препаратов согласовать с врачом.', 231);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('glyukagon', 'Глюкагон (glucagon, глюкагон крови)', 'Гормоны', 'Гормоны поджелудочной железы', 'Определение глюкагона для диагностики глюкагономы и оценки нарушений углеводного обмена.', 'Утром строго натощак, 10–12 ч голодания; можно пить воду. Накануне исключить алкоголь и интенсивные нагрузки; перед забором отдохнуть в покое.', 232);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('proinsulin', 'Проинсулин (proinsulin, интактный проинсулин, предшественник инсулина)', 'Гормоны', 'Гормоны поджелудочной железы', 'Определение проинсулина для диагностики инсулином, дисфункции бета-клеток и нарушений секреции инсулина.', 'Утром строго натощак, 8–12 ч голодания; можно пить воду. Накануне исключить алкоголь. Приём сахароснижающих препаратов согласовать с врачом.', 233);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('somatotropnyy-gormon', 'Соматотропный гормон (СТГ, STH, GH, гормон роста, соматотропин, growth hormone)', 'Гормоны', 'Гормоны роста', 'Определение гормона роста для диагностики его дефицита, избытка (акромегалия, гигантизм) и болезней гипофиза.', 'Утром строго натощак, 10–12 ч голодания; можно пить воду. За сутки исключить физические нагрузки и стресс, за 3 дня отменить биотин. Перед забором отдохнуть 20–30 минут.', 234);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('somatomedin-s', 'Соматомедин-С (ИФР-1, IGF-1, инсулиноподобный фактор роста 1, insulin-like growth factor 1, somatomedin C)', 'Гормоны', 'Гормоны роста', 'Определение ИФР-1 — стабильного маркера продукции гормона роста; основной тест для диагностики акромегалии и дефицита СТГ.', 'Утром натощак, 8–12 ч голодания; можно пить воду. За 3 дня отменить биотин, накануне исключить интенсивные нагрузки.', 235);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('ifr-svyazyvayuschiy-belok-3', 'ИФР-связывающий белок 3 (IGFBP-3, инсулиноподобного фактора роста связывающий белок 3, insulin-like growth factor binding protein 3)', 'Гормоны', 'Гормоны роста', 'Определение IGFBP-3 — основного белка-переносчика ИФР-1; используется вместе с ИФР-1 при диагностике болезней роста.', 'Утром натощак, 8–12 ч голодания; можно пить воду. За 3 дня отменить биотин, накануне исключить интенсивные нагрузки.', 236);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('stg-s-nagruzochnoy-proboy', 'СТГ с нагрузочной пробой (стимуляционная/супрессивная проба СТГ, нагрузочный тест гормона роста, GH stimulation test)', 'Гормоны', 'Гормоны роста', 'Исследование гормона роста с нагрузкой для диагностики его дефицита или избытка при неоднозначных базовых значениях.', 'Утром строго натощак, 10–12 ч голодания. Проба проводится в клинике с несколькими заборами крови по времени. Накануне исключить нагрузки и стресс, обеспечить полноценный сон.', 237);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('prenatalnyy-skrining-preaccu-i-trimestra-beremennosti', 'Пренатальный скрининг I триместра, PRISCA/Preaccu (двойной тест, PAPP-A + свободный бета-ХГЧ, скрининг 1 триместра, first trimester screening)', 'Гормоны', 'Гормоны беременности', 'Комбинированный скрининг 1 триместра для оценки риска хромосомных аномалий плода (синдром Дауна и др.).', 'Комбинированный скрининг 1 триместра для оценки риска хромосомных аномалий плода (синдром Дауна и др.).', 238);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('prenatalnyy-skrining-preaccu-ii-trimestra-beremennosti', 'Пренатальный скрининг II триместра, PRISCA/Preaccu (тройной тест: АФП, свободный бета-ХГЧ, эстриол Е3, скрининг 2 триместра, second trimester screening)', 'Гормоны', 'Гормоны беременности', 'Комбинированный скрининг 2 триместра для оценки риска хромосомных аномалий и дефектов нервной трубки плода.', 'Утром натощак, 8–12 ч голодания; можно пить воду. Оптимальный срок — 15–20 недель. При себе иметь данные УЗИ и точный срок беременности.', 239);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('horionicheskiy-gonadotropin', 'Хорионический гонадотропин (ХГЧ, бета-ХГЧ, hCG, общий ХГЧ, гормон беременности)', 'Гормоны', 'Гормоны беременности', 'Определение ХГЧ для ранней диагностики беременности, контроля её течения и в онкологической диагностике.', 'Утром натощак, 8–12 ч голодания; можно пить воду. Для ранней диагностики беременности сдавать не ранее 3–5 дней задержки.', 240);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('svobodnyy-beta-hgch', 'Свободный бета-ХГЧ (св. бета-ХГЧ, free beta-hCG, свободная бета-субъединица ХГЧ)', 'Гормоны', 'Гормоны беременности', 'Определение свободного бета-ХГЧ в составе пренатального скрининга и онкомаркерной диагностики.', 'Утром натощак, 8–12 ч голодания; можно пить воду. При скрининге указать точный срок беременности и данные УЗИ.', 241);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('papp-a', 'PAPP-A (ПАПП-А, ассоциированный с беременностью протеин А плазмы, pregnancy-associated plasma protein A)', 'Гормоны', 'Гормоны беременности', 'Определение PAPP-A в составе скрининга 1 триместра для оценки риска хромосомных аномалий плода.', 'Утром натощак, 8–12 ч голодания; можно пить воду. Оптимальный срок — 11–13 недель. При себе иметь данные УЗИ (КТР).', 242);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('estriol-svobodnyy', 'Эстриол свободный (свободный эстриол, Е3, free estriol, uE3, неконъюгированный эстриол)', 'Гормоны', 'Гормоны беременности', 'Определение свободного эстриола для оценки состояния плода и плаценты в составе скрининга 2 триместра.', 'Утром натощак, 8–12 ч голодания; можно пить воду. Указать точный срок беременности.', 243);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('platsentarnyy-laktogen', 'Плацентарный лактоген (ПЛ, hPL, human placental lactogen, плацентарный соматомаммотропин)', 'Гормоны', 'Гормоны беременности', 'Определение плацентарного лактогена для оценки функции плаценты и состояния плода во время беременности.', 'Утром натощак, 8–12 ч голодания; можно пить воду. Указать срок беременности.', 244);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('ingibin-a', 'Ингибин А (inhibin A, ингибин А сыворотки)', 'Гормоны', 'Гормоны беременности', 'Определение ингибина А в составе расширенного пренатального скрининга для оценки риска хромосомных аномалий.', 'Утром натощак, 8–12 ч голодания; можно пить воду. Указать точный срок беременности и данные УЗИ.', 245);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('troynoy-test-ii-trimestra', 'Тройной тест II триместра (АФП + ХГЧ + эстриол, triple test, биохимический скрининг 2 триместра)', 'Гормоны', 'Гормоны беременности', 'Комбинированный биохимический скрининг 2 триместра для оценки риска хромосомных аномалий и пороков плода.', 'Утром натощак, 8–12 ч голодания; можно пить воду. Оптимальный срок — 15–20 недель. При себе иметь данные УЗИ и точный срок беременности.', 246);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('ekskretsiya-kortizola', 'Экскреция кортизола за сутки (свободный кортизол в суточной моче, суточный кортизол мочи, urinary free cortisol, UFC)', 'Гормоны', 'гормоны мочи', 'Определение свободного кортизола в суточной моче для диагностики синдрома Иценко-Кушинга.', 'Собрать мочу за 24 часа (первую утреннюю порцию слить, указать объём). Накануне и в день сбора исключить стресс, интенсивные нагрузки и алкоголь.', 247);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('metanefriny-v-sutochnoy-moche', 'Метанефрины в суточной моче (метанефрин мочи, суточные метанефрины, urine metanephrines, метаболиты адреналина)', 'Гормоны', 'гормоны мочи', 'Определение метанефринов в суточной моче для диагностики феохромоцитомы и опухолей из хромаффинной ткани.', 'За 3 дня исключить кофе, чай, шоколад, цитрусы, ваниль, бананы; избегать стресса и нагрузок. Собрать суточную мочу в контейнер с консервантом (уточнить в лаборатории).', 248);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('normetanefriny-v-sutochnoy-moche', 'Норметанефрины в суточной моче (норметанефрин мочи, суточные норметанефрины, urine normetanephrines, метаболиты норадреналина)', 'Гормоны', 'гормоны мочи', 'Определение норметанефринов в суточной моче для диагностики феохромоцитомы и катехоламин-продуцирующих опухолей.', 'За 3 дня исключить кофе, чай, шоколад, цитрусы, ваниль, бананы; избегать стресса и нагрузок. Собрать суточную мочу в контейнер с консервантом.', 249);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('vanililmindalnaya-kislota-v-sutochnoy-moche', 'Ванилилминдальная кислота в суточной моче (ВМК, VMA, vanillylmandelic acid, метаболит катехоламинов)', 'Гормоны', 'гормоны мочи', 'Определение ванилилминдальной кислоты в суточной моче для диагностики феохромоцитомы и нейробластомы.', 'За 3 дня исключить кофе, чай, шоколад, цитрусы, ваниль, бананы, орехи; избегать стресса. Собрать суточную мочу в контейнер с консервантом.', 250);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('5-oksiindoluksusnaya-kislota-v-sutochnoy-moche', '5-оксииндолуксусная кислота в суточной моче (5-ОИУК, 5-HIAA, 5-hydroxyindoleacetic acid, метаболит серотонина)', 'Гормоны', 'гормоны мочи', 'Определение 5-ОИУК в суточной моче для диагностики карциноидных опухолей, продуцирующих серотонин.', 'За 3 дня исключить бананы, ананасы, киви, авокадо, сливы, орехи, шоколад, чай, кофе, ваниль. Собрать суточную мочу в контейнер с консервантом.', 251);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('17-ketosteroidy-v-sutochnoy-moche', '17-кетостероиды в суточной моче (17-КС, 17-KS, 17-ketosteroids, метаболиты андрогенов)', 'Гормоны', 'гормоны мочи', 'Определение 17-кетостероидов в суточной моче для оценки продукции андрогенов надпочечниками.', 'За 3 дня исключить окрашивающие мочу продукты (свёкла, морковь) и по согласованию с врачом ряд препаратов. Собрать суточную мочу, избегать стресса и нагрузок.', 252);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('aldosteron-v-sutochnoy-moche', 'Альдостерон в суточной моче (альдостерон мочи, суточный альдостерон, urine aldosterone)', 'Гормоны', 'гормоны мочи', 'Определение альдостерона в суточной моче для диагностики гиперальдостеронизма и болезней надпочечников.', 'Собрать суточную мочу в контейнер с консервантом. По согласованию с врачом за 2 недели отменить влияющие препараты, не ограничивать резко соль.', 253);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('eritropoetin', 'Эритропоэтин (ЭПО, EPO, erythropoietin, эритропоэтин крови)', 'Гормоны', 'другие гормоны', 'Определение эритропоэтина для диагностики анемий, эритроцитозов и оценки почечной продукции гормона.', 'Утром натощак, 8–12 ч голодания; можно пить воду. Желательно сдавать в утренние часы; накануне исключить интенсивные нагрузки.', 254);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('leptin', 'Лептин (leptin, лептин крови, гормон насыщения)', 'Гормоны', 'другие гормоны', 'Определение лептина для оценки жирового обмена, регуляции аппетита и при ожирении.', 'Утром строго натощак, 10–12 ч голодания; можно пить воду. Накануне исключить переедание, алкоголь и интенсивные нагрузки.', 255);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('adiponektin', 'Адипонектин (adiponectin, адипонектин крови)', 'Гормоны', 'другие гормоны', 'Определение адипонектина для оценки риска метаболического синдрома, диабета 2 типа и жирового обмена.', 'Утром строго натощак, 10–12 ч голодания; можно пить воду. Накануне исключить переедание и алкоголь.', 256);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('serotonin', 'Серотонин (serotonin, 5-HT, серотонин крови, гормон настроения)', 'Гормоны', 'другие гормоны', 'Определение серотонина в крови, преимущественно для диагностики карциноидных опухолей.', 'За 3 дня исключить бананы, ананасы, киви, авокадо, орехи, шоколад, чай, кофе, ваниль. Утром натощак, в покое, избегать стресса.', 257);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('gistamin', 'Гистамин (histamine, гистамин крови)', 'Гормоны', 'другие гормоны', 'Определение гистамина для диагностики аллергических реакций, мастоцитоза и псевдоаллергии.', 'За 3 дня исключить продукты, богатые гистамином (сыр, рыба, копчёности, алкоголь, шоколад). Утром натощак, в покое, избегать стресса.', 258);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('melatonin', 'Мелатонин, 6-сульфатоксимелатонин (6-СОМТ, melatonin, 6-sulfatoxymelatonin, гормон сна)', 'Гормоны', 'другие гормоны', 'Определение мелатонина (или его метаболита в моче) для оценки циркадных ритмов и нарушений сна.', 'Забор строго по времени (обычно ночь/раннее утро) по назначению. Избегать яркого света ночью перед сбором; уточнить схему в лаборатории.', 259);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('antidiureticheskiy-gormon', 'Антидиуретический гормон (АДГ, вазопрессин, ADH, vasopressin, аргинин-вазопрессин)', 'Гормоны', 'другие гормоны', 'Определение вазопрессина (АДГ) для диагностики несахарного диабета и нарушений водно-солевого баланса.', 'Утром натощак; можно пить воду в обычном режиме (без водной нагрузки/ограничения, если не указано). Накануне исключить стресс, нагрузки, алкоголь и курение.', 260);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('interleykin-1', 'Интерлейкин-1 (ИЛ-1, IL-1, интерлейкин 1, провоспалительный цитокин)', 'Иммунология и аллергология', 'Цитокины и комплемент', 'Определение интерлейкина-1 — провоспалительного цитокина; используется в оценке воспаления и иммунного ответа.', 'Утром натощак, 8–12 ч голодания; можно пить воду. Накануне исключить нагрузки и стресс, не сдавать при остром заболевании (если не назначено иначе).', 261);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('interleykin-10', 'Интерлейкин-10 (ИЛ-10, IL-10, интерлейкин 10, противовоспалительный цитокин)', 'Иммунология и аллергология', 'Цитокины и комплемент', 'Определение интерлейкина-10 — противовоспалительного цитокина; применяется в оценке иммунной регуляции.', 'Утром натощак, 8–12 ч голодания; можно пить воду. Накануне исключить нагрузки и стресс.', 262);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('interleykin-2', 'Интерлейкин-2 (ИЛ-2, IL-2, интерлейкин 2, фактор роста Т-лимфоцитов)', 'Иммунология и аллергология', 'Цитокины и комплемент', 'Определение интерлейкина-2 — цитокина активации Т-лимфоцитов; используется в оценке иммунного статуса.', 'Утром натощак, 8–12 ч голодания; можно пить воду. Накануне исключить нагрузки и стресс.', 263);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('interleykin-4', 'Интерлейкин-4 (ИЛ-4, IL-4, интерлейкин 4, цитокин Th2-ответа)', 'Иммунология и аллергология', 'Цитокины и комплемент', 'Определение интерлейкина-4 — цитокина аллергического и Th2-иммунного ответа.', 'Утром натощак, 8–12 ч голодания; можно пить воду. Накануне исключить нагрузки и стресс.', 264);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('interleykin-6', 'Интерлейкин-6 (ИЛ-6, IL-6, интерлейкин 6, провоспалительный цитокин)', 'Иммунология и аллергология', 'Цитокины и комплемент', 'Определение интерлейкина-6 — ключевого маркера воспаления и тяжести инфекций, в том числе при сепсисе.', 'Утром натощак, 8–12 ч голодания; можно пить воду. Накануне исключить нагрузки и стресс; при острых состояниях сдаётся по показаниям.', 265);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('interleykin-8', 'Интерлейкин-8 (ИЛ-8, IL-8, интерлейкин 8, хемокин)', 'Иммунология и аллергология', 'Цитокины и комплемент', 'Определение интерлейкина-8 — провоспалительного хемокина; применяется в оценке воспалительного ответа.', 'Утром натощак, 8–12 ч голодания; можно пить воду. Накануне исключить нагрузки и стресс.', 266);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('c3-komponent-komplementa', 'C3 компонент комплемента (С3, C3, комплемент C3)', 'Иммунология и аллергология', 'Цитокины и комплемент', 'Определение C3 компонента комплемента для диагностики аутоиммунных, воспалительных и почечных заболеваний.', 'Утром натощак, 8–12 ч голодания; можно пить воду. Накануне исключить алкоголь.', 267);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('c4-komponent-komplementa', 'C4 компонент комплемента (С4, C4, комплемент C4)', 'Иммунология и аллергология', 'Цитокины и комплемент', 'Определение C4 компонента комплемента для диагностики аутоиммунных болезней и наследственного ангиоотёка.', 'Утром натощак, 8–12 ч голодания; можно пить воду. Накануне исключить алкоголь.', 268);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('faktor-nekroza-opuholi', 'Фактор некроза опухоли альфа (ФНО-альфа, TNF-α, TNF-alpha, tumor necrosis factor)', 'Иммунология и аллергология', 'Цитокины и комплемент', 'Определение ФНО-альфа — провоспалительного цитокина; применяется в оценке воспаления и аутоиммунных болезней.', 'Утром натощак, 8–12 ч голодания; можно пить воду. Накануне исключить нагрузки и стресс.', 269);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('interferon-gamma', 'Интерферон-гамма (ИФН-гамма, IFN-γ, IFN-gamma, interferon gamma)', 'Иммунология и аллергология', 'Цитокины и комплемент', 'Определение интерферона-гамма — цитокина клеточного иммунитета; используется в оценке иммунного ответа.', 'Утром натощак, 8–12 ч голодания; можно пить воду. Накануне исключить нагрузки и стресс.', 270);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('tsirkuliruyuschie-immunnye-kompleksy', 'Циркулирующие иммунные комплексы (ЦИК, CIC, circulating immune complexes)', 'Иммунология и аллергология', 'Цитокины и комплемент', 'Определение циркулирующих иммунных комплексов для диагностики аутоиммунных и хронических воспалительных болезней.', 'Утром натощак, 8–12 ч голодания; можно пить воду. Накануне исключить алкоголь и интенсивные нагрузки.', 271);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('komplement-ch50', 'Комплемент CH50 (CH50, общая гемолитическая активность комплемента, total complement activity)', 'Иммунология и аллергология', 'Цитокины и комплемент', 'Определение общей активности системы комплемента (CH50) для диагностики её дефицитов и аутоиммунных болезней.', 'Утром натощак, 8–12 ч голодания; можно пить воду. Проба чувствительна к хранению — уточнить условия сдачи в лаборатории.', 272);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('interleykin-17', 'Интерлейкин-17 (ИЛ-17, IL-17, интерлейкин 17, цитокин Th17-ответа)', 'Иммунология и аллергология', 'Цитокины и комплемент', 'Определение интерлейкина-17 — цитокина, участвующего в аутоиммунном и противомикробном воспалении.', 'Утром натощак, 8–12 ч голодания; можно пить воду. Накануне исключить нагрузки и стресс.', 273);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('interferon-alfa', 'Интерферон-альфа (ИФН-альфа, IFN-α, IFN-alpha, interferon alpha)', 'Иммунология и аллергология', 'Цитокины и комплемент', 'Определение интерферона-альфа — противовирусного цитокина; применяется в оценке иммунного ответа и аутоиммунных болезней.', 'Утром натощак, 8–12 ч голодания; можно пить воду. Накануне исключить нагрузки и стресс.', 274);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('c1-ingibitor', 'C1-ингибитор (С1-ингибитор, C1-INH, ингибитор C1-эстеразы, наследственный ангиоотёк)', 'Иммунология и аллергология', 'Цитокины и комплемент', 'Определение уровня C1-ингибитора для диагностики наследственного и приобретённого ангиоотёка.', 'Утром натощак, 8–12 ч голодания; можно пить воду. Желательно сдавать вне острого приступа отёка (если не назначено иначе).', 275);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('aktivnost-ingibitora-c1', 'Активность C1-ингибитора, функциональная (C1-INH функциональный, функция ингибитора C1-эстеразы, C1 esterase inhibitor activity)', 'Иммунология и аллергология', 'Цитокины и комплемент', 'Активность C1-ингибитора, функциональная (C1-INH функциональный, функция ингибитора C1-эстеразы, C1 esterase inhibitor activity)', 'Утром натощак, 8–12 ч голодания; можно пить воду. Желательно сдавать вне острого приступа отёка; проба чувствительна к хранению.', 276);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('allergen-d2-klescha-domashney-pyli', 'Аллерген D2, Клещ домашней пыли (Dermatophagoides farinae, house dust mite, IgE, специфический IgE)', 'Иммунология и аллергология', 'Специфические IgE (отдельные аллергены)', 'Определение специфических IgE к аллергену «клещ домашней пыли» для диагностики бытовой аллергии и выявления сенсибилизации.', 'Кровь натощак или через 3 ч после лёгкого приёма пищи; можно пить воду. Отмена антигистаминных препаратов перед анализом крови не требуется. Накануне исключить интенсивные нагрузки и алкоголь.', 277);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('allergen-d70-chesotochnyy-klesch', 'Аллерген D70, Мучной (амбарный) клещ (Acarus siro, storage mite, IgE, специфический IgE)', 'Иммунология и аллергология', 'Специфические IgE (отдельные аллергены)', 'Определение специфических IgE к аллергену «мучной (амбарный) клещ» для диагностики бытовой аллергии и выявления сенсибилизации.', 'Кровь натощак или через 3 ч после лёгкого приёма пищи; можно пить воду. Отмена антигистаминных препаратов перед анализом крови не требуется. Накануне исключить интенсивные нагрузки и алкоголь.', 278);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('allergen-d73-klesch', 'Аллерген D73, Клещ (Glycyphagus domesticus, storage mite, IgE, специфический IgE)', 'Иммунология и аллергология', 'Специфические IgE (отдельные аллергены)', 'Определение специфических IgE к аллергену «клещ» для диагностики бытовой аллергии и выявления сенсибилизации.', 'Кровь натощак или через 3 ч после лёгкого приёма пищи; можно пить воду. Отмена антигистаминных препаратов перед анализом крови не требуется. Накануне исключить интенсивные нагрузки и алкоголь.', 279);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('allergen-e1-koshachya-sherst-epiteliy', 'Аллерген E1, Эпителий кошки (Cat dander-epithelium, кошачья шерсть, IgE, специфический IgE)', 'Иммунология и аллергология', 'Специфические IgE (отдельные аллергены)', 'Определение специфических IgE к аллергену «эпителий кошки» для диагностики аллергии на животных и выявления сенсибилизации.', 'Кровь натощак или через 3 ч после лёгкого приёма пищи; можно пить воду. Отмена антигистаминных препаратов перед анализом крови не требуется. Накануне исключить интенсивные нагрузки и алкоголь.', 280);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('allergen-e2-epiteliy-sobak', 'Аллерген E2, Эпителий собаки (Dog epithelium, собачья шерсть, IgE, специфический IgE)', 'Иммунология и аллергология', 'Специфические IgE (отдельные аллергены)', 'Определение специфических IgE к аллергену «эпителий собаки» для диагностики аллергии на животных и выявления сенсибилизации.', 'Кровь натощак или через 3 ч после лёгкого приёма пищи; можно пить воду. Отмена антигистаминных препаратов перед анализом крови не требуется. Накануне исключить интенсивные нагрузки и алкоголь.', 281);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('allergen-e201-perya-kanareyki', 'Аллерген E201, Перья канарейки (Canary feathers, IgE, специфический IgE)', 'Иммунология и аллергология', 'Специфические IgE (отдельные аллергены)', 'Определение специфических IgE к аллергену «перья канарейки» для диагностики аллергии на животных и выявления сенсибилизации.', 'Кровь натощак или через 3 ч после лёгкого приёма пищи; можно пить воду. Отмена антигистаминных препаратов перед анализом крови не требуется. Накануне исключить интенсивные нагрузки и алкоголь.', 282);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('allergen-e3-epiteliy-loshadi', 'Аллерген E3, Эпителий лошади (Horse epithelium, IgE, специфический IgE)', 'Иммунология и аллергология', 'Специфические IgE (отдельные аллергены)', 'Определение специфических IgE к аллергену «эпителий лошади» для диагностики аллергии на животных и выявления сенсибилизации.', 'Кровь натощак или через 3 ч после лёгкого приёма пищи; можно пить воду. Отмена антигистаминных препаратов перед анализом крови не требуется. Накануне исключить интенсивные нагрузки и алкоголь.', 283);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('allergen-e4-epiteliy-korovy', 'Аллерген E4, Эпителий коровы (Cow dander, IgE, специфический IgE)', 'Иммунология и аллергология', 'Специфические IgE (отдельные аллергены)', 'Определение специфических IgE к аллергену «эпителий коровы» для диагностики аллергии на животных и выявления сенсибилизации.', 'Кровь натощак или через 3 ч после лёгкого приёма пищи; можно пить воду. Отмена антигистаминных препаратов перед анализом крови не требуется. Накануне исключить интенсивные нагрузки и алкоголь.', 284);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('allergen-e70-gusinye-perya', 'Аллерген E70, Гусиные перья (Goose feathers, IgE, специфический IgE)', 'Иммунология и аллергология', 'Специфические IgE (отдельные аллергены)', 'Определение специфических IgE к аллергену «гусиные перья» для диагностики аллергии на животных и выявления сенсибилизации.', 'Кровь натощак или через 3 ч после лёгкого приёма пищи; можно пить воду. Отмена антигистаминных препаратов перед анализом крови не требуется. Накануне исключить интенсивные нагрузки и алкоголь.', 285);
