INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('raygras-ige', 'Райграс (французский райграс) (Arrhenatherum elatius, IgE, специфический IgE)', 'Иммунология и аллергология', 'Специфические IgE (отдельные аллергены)', 'Определение специфических IgE к аллергену «райграс (французский райграс)» для диагностики поллиноза и выявления сенсибилизации.', 'Кровь натощак или через 3 ч после лёгкого приёма пищи; можно пить воду. Отмена антигистаминных препаратов перед анализом крови не требуется. Накануне исключить интенсивные нагрузки и алкоголь.', 392);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('rozh-posevnaya-ige', 'Рожь посевная (Secale cereale, IgE, специфический IgE)', 'Иммунология и аллергология', 'Специфические IgE (отдельные аллергены)', 'Определение специфических IgE к аллергену «рожь посевная» для диагностики поллиноза и выявления сенсибилизации.', 'Кровь натощак или через 3 ч после лёгкого приёма пищи; можно пить воду. Отмена антигистаминных препаратов перед анализом крови не требуется. Накануне исключить интенсивные нагрузки и алкоголь.', 393);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('selderey-ige', 'Сельдерей (Apium graveolens, celery, IgE, специфический IgE)', 'Иммунология и аллергология', 'Специфические IgE (отдельные аллергены)', 'Определение специфических IgE к аллергену «сельдерей» для диагностики пищевой аллергии и выявления сенсибилизации.', 'Кровь натощак или через 3 ч после лёгкого приёма пищи; можно пить воду. Отмена антигистаминных препаратов перед анализом крови не требуется. Накануне исключить интенсивные нагрузки и алкоголь.', 394);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('allergopanel-protia-allergy-q-96m', 'Аллергопанель PROTIA Allergy-Q 96М (Allergy-Q, аллергочип на 96 аллергенов, комплексная аллергопанель, специфический IgE)', 'Иммунология и аллергология', 'Аллергопанели', 'Одновременное определение IgE к 96 аллергенам для комплексной диагностики аллергии и сенсибилизации.', 'Кровь натощак или через 3 ч после лёгкого приёма пищи; можно пить воду. Отмена антигистаминных препаратов перед анализом крови не требуется. Накануне исключить нагрузки и алкоголь.', 395);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('rida-screen-ingalyatsionnaya-panel', 'RIDA-screen ингаляционная панель (RIDA-screen, респираторная аллергопанель, ингаляционные аллергены, специфический IgE)', 'Иммунология и аллергология', 'Аллергопанели', 'Определение IgE к основным ингаляционным аллергенам для диагностики респираторной аллергии, астмы и ринита.', 'Кровь натощак или через 3 ч после лёгкого приёма пищи; можно пить воду. Отмена антигистаминных препаратов перед анализом крови не требуется.', 396);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('rida-screen-pischevaya-panel', 'RIDA-screen пищевая панель (RIDA-screen, пищевая аллергопанель, пищевые аллергены, специфический IgE)', 'Иммунология и аллергология', 'Аллергопанели', 'Определение IgE к основным пищевым аллергенам для диагностики пищевой аллергии.', 'Кровь натощак или через 3 ч после лёгкого приёма пищи; можно пить воду. Отмена антигистаминных препаратов перед анализом крови не требуется.', 397);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('rida-screen-pediatricheskaya-panel', 'RIDA-screen педиатрическая панель (RIDA-screen, детская аллергопанель, педиатрический скрининг аллергенов, специфический IgE)', 'Иммунология и аллергология', 'Аллергопанели', 'Определение IgE к аллергенам, значимым в детском возрасте, для диагностики аллергии у детей.', 'Кровь натощак или через 3 ч после лёгкого приёма пищи; можно пить воду. Отмена антигистаминных препаратов перед анализом крови не требуется.', 398);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('immunocap-phadiatop', 'ImmunoCAP Phadiatop, скрининг ингаляционных аллергенов (Phadiatop, ImmunoCAP, скрининг респираторной аллергии, специфический IgE)', 'Иммунология и аллергология', 'Аллергопанели', 'Скрининговый тест на сенсибилизацию к ингаляционным аллергенам для подтверждения или исключения респираторной аллергии.', 'Кровь натощак или через 3 ч после лёгкого приёма пищи; можно пить воду. Отмена антигистаминных препаратов перед анализом крови не требуется.', 399);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('molekulyarnaya-allergodiagnostika', 'Молекулярная аллергодиагностика ALEX/ISAC, компонентная (ALEX, ISAC, компонентная аллергодиагностика, аллергокомпоненты, молекулярный аллергочип)', 'Иммунология и аллергология', 'Аллергопанели', 'Компонентное определение IgE к молекулам аллергенов для точной диагностики сенсибилизации и оценки рисков реакций.', 'Кровь натощак или через 3 ч после лёгкого приёма пищи; можно пить воду. Отмена антигистаминных препаратов перед анализом крови не требуется.', 400);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('allergopanel-astma-rinit-1', 'Аллергопанель «Астма/Ринит» 1 (панель астма и ринит 1, ингаляционные аллергены, специфический IgE)', 'Иммунология и аллергология', 'Аллергопанели', 'Определение IgE к группе ингаляционных аллергенов для диагностики бронхиальной астмы и аллергического ринита.', 'Кровь натощак или через 3 ч после лёгкого приёма пищи; можно пить воду. Отмена антигистаминных препаратов перед анализом крови не требуется.', 401);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('allergopanel-astma-rinit-2', 'Аллергопанель «Астма/Ринит» 2 (панель астма и ринит 2, ингаляционные аллергены, специфический IgE)', 'Иммунология и аллергология', 'Аллергопанели', 'Определение IgE к расширенной группе ингаляционных аллергенов для диагностики астмы и аллергического ринита.', 'Кровь натощак или через 3 ч после лёгкого приёма пищи; можно пить воду. Отмена антигистаминных препаратов перед анализом крови не требуется.', 402);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('allergopanel-pischevaya-1', 'Аллергопанель «Пищевая 1» (пищевая панель 1, пищевые аллергены, специфический IgE)', 'Иммунология и аллергология', 'Аллергопанели', 'Определение IgE к группе пищевых аллергенов для диагностики пищевой аллергии.', 'Кровь натощак или через 3 ч после лёгкого приёма пищи; можно пить воду. Отмена антигистаминных препаратов перед анализом крови не требуется.', 403);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('allergopanel-pischevaya-2', 'Аллергопанель «Пищевая 2» (пищевая панель 2, пищевые аллергены, специфический IgE)', 'Иммунология и аллергология', 'Аллергопанели', 'Определение IgE к группе пищевых аллергенов для диагностики пищевой аллергии.', 'Кровь натощак или через 3 ч после лёгкого приёма пищи; можно пить воду. Отмена антигистаминных препаратов перед анализом крови не требуется.', 404);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('allergopanel-pischevaya-3', 'Аллергопанель «Пищевая 3» (пищевая панель 3, пищевые аллергены, специфический IgE)', 'Иммунология и аллергология', 'Аллергопанели', 'Определение IgE к группе пищевых аллергенов для диагностики пищевой аллергии.', 'Кровь натощак или через 3 ч после лёгкого приёма пищи; можно пить воду. Отмена антигистаминных препаратов перед анализом крови не требуется.', 405);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('allergopanel-pischevaya-4', 'Аллергопанель «Пищевая 4» (пищевая панель 4, пищевые аллергены, специфический IgE)', 'Иммунология и аллергология', 'Аллергопанели', 'Определение IgE к группе пищевых аллергенов для диагностики пищевой аллергии.', 'Кровь натощак или через 3 ч после лёгкого приёма пищи; можно пить воду. Отмена антигистаминных препаратов перед анализом крови не требуется.', 406);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('allergopanel-derevya', 'Аллергопанель «Деревья» (панель пыльцы деревьев, древесная пыльца, поллиноз, специфический IgE)', 'Иммунология и аллергология', 'Аллергопанели', 'Определение IgE к пыльце деревьев для диагностики поллиноза и сезонной аллергии.', 'Кровь натощак или через 3 ч после лёгкого приёма пищи; можно пить воду. Отмена антигистаминных препаратов перед анализом крови не требуется.', 407);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('allergopanel-pyltsevye-allergeny-lugovye-travy', 'Аллергопанель «Луговые травы» (панель пыльцы луговых трав, злаковые травы, поллиноз, специфический IgE)', 'Иммунология и аллергология', 'Аллергопанели', 'Определение IgE к пыльце луговых (злаковых) трав для диагностики поллиноза и сезонной аллергии.', 'Кровь натощак или через 3 ч после лёгкого приёма пищи; можно пить воду. Отмена антигистаминных препаратов перед анализом крови не требуется.', 408);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('allergopanel-orehi', 'Аллергопанель «Орехи» (ореховая панель, аллергены орехов, специфический IgE)', 'Иммунология и аллергология', 'Аллергопанели', 'Определение IgE к различным орехам для диагностики пищевой аллергии на орехи.', 'Кровь натощак или через 3 ч после лёгкого приёма пищи; можно пить воду. Отмена антигистаминных препаратов перед анализом крови не требуется.', 409);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('allergopanel-frukty', 'Аллергопанель «Фрукты» (фруктовая панель, аллергены фруктов, специфический IgE)', 'Иммунология и аллергология', 'Аллергопанели', 'Определение IgE к различным фруктам для диагностики пищевой аллергии на фрукты.', 'Кровь натощак или через 3 ч после лёгкого приёма пищи; можно пить воду. Отмена антигистаминных препаратов перед анализом крови не требуется.', 410);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('allergopanel-moreprodukty', 'Аллергопанель «Морепродукты» (панель морепродуктов, рыба и морепродукты, специфический IgE)', 'Иммунология и аллергология', 'Аллергопанели', 'Определение IgE к рыбе и морепродуктам для диагностики пищевой аллергии.', 'Кровь натощак или через 3 ч после лёгкого приёма пищи; можно пить воду. Отмена антигистаминных препаратов перед анализом крови не требуется.', 411);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('allergopanel-allergiya-na-moloko', 'Аллергопанель «Аллергия на молоко» (молочная панель, аллергены молока, белки коровьего молока, специфический IgE)', 'Иммунология и аллергология', 'Аллергопанели', 'Определение IgE к белкам молока (казеин, лактальбумин, лактоглобулин) для диагностики аллергии на молоко.', 'Кровь натощак или через 3 ч после лёгкого приёма пищи; можно пить воду. Отмена антигистаминных препаратов перед анализом крови не требуется.', 412);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('allergopanel-gribkovaya-allergiya', 'Аллергопанель «Грибковая аллергия» (панель плесневых грибов, грибковые аллергены, микогенная аллергия, специфический IgE)', 'Иммунология и аллергология', 'Аллергопанели', 'Определение IgE к плесневым грибам для диагностики грибковой (микогенной) аллергии.', 'Кровь натощак или через 3 ч после лёгкого приёма пищи; можно пить воду. Отмена антигистаминных препаратов перед анализом крови не требуется.', 413);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('allergopanel-insektnaya-allergiya', 'Аллергопанель «Инсектная аллергия» (панель ядов насекомых, инсектные аллергены, укусы насекомых, специфический IgE)', 'Иммунология и аллергология', 'Аллергопанели', 'Определение IgE к аллергенам насекомых для диагностики инсектной аллергии на укусы и ужаления.', 'Кровь натощак или через 3 ч после лёгкого приёма пищи; можно пить воду. Отмена антигистаминных препаратов перед анализом крови не требуется.', 414);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('allergopanel-gistaminoliberatory', 'Аллергопанель «Гистаминолибераторы» (панель гистаминолибераторов, псевдоаллергия, продукты-либераторы гистамина, специфический IgE)', 'Иммунология и аллергология', 'Аллергопанели', 'Определение IgE к продуктам-гистаминолибераторам для оценки пищевой непереносимости и псевдоаллергических реакций.', 'Кровь натощак или через 3 ч после лёгкого приёма пищи; можно пить воду. Отмена антигистаминных препаратов перед анализом крови не требуется.', 415);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('allergopanel-ekzema', 'Аллергопанель «Экзема» (панель при экземе, аллергены при атопическом дерматите, специфический IgE)', 'Иммунология и аллергология', 'Аллергопанели', 'Определение IgE к аллергенам, связанным с экземой и атопическим дерматитом, для выявления триггеров.', 'Кровь натощак или через 3 ч после лёгкого приёма пищи; можно пить воду. Отмена антигистаминных препаратов перед анализом крови не требуется.', 416);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('panel-pischevyh-allergenov', 'Панель пищевых аллергенов (пищевая аллергопанель, пищевые аллергены, специфический IgE)', 'Иммунология и аллергология', 'Аллергопанели', 'Определение IgE к основным пищевым аллергенам для диагностики пищевой аллергии.', 'Кровь натощак или через 3 ч после лёгкого приёма пищи; можно пить воду. Отмена антигистаминных препаратов перед анализом крови не требуется.', 417);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('phadiatop-infant', 'Phadiatop Infant, детский скрининг сенсибилизации (Phadiatop Infant, ImmunoCAP, детский скрининг аллергии, пищевые и ингаляционные аллергены, специфический IgE)', 'Иммунология и аллергология', 'Аллергопанели', 'Скрининговый тест на сенсибилизацию к пищевым и ингаляционным аллергенам у детей раннего возраста.', 'Кровь натощак или через 3 ч после лёгкого приёма пищи (у детей — до кормления); можно пить воду. Отмена антигистаминных препаратов не требуется.', 418);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('immunohels-panel-90', 'Иммунохелс-панель 90, пищевая непереносимость IgG (ImmunoHealth, панель на 90 продуктов, специфический IgG, пищевая непереносимость)', 'Иммунология и аллергология', 'Аллергопанели', 'Определение специфических IgG к 90 пищевым продуктам для оценки пищевой непереносимости.', 'Кровь натощак или через 3 ч после лёгкого приёма пищи; можно пить воду. Заранее продукты из рациона не исключать. Накануне исключить алкоголь.', 419);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('immunohels-panel-111', 'Иммунохелс-панель 111, пищевая непереносимость IgG (ImmunoHealth, панель на 111 продуктов, специфический IgG, пищевая непереносимость)', 'Иммунология и аллергология', 'Аллергопанели', 'Определение специфических IgG к 111 пищевым продуктам для оценки пищевой непереносимости.', 'Кровь натощак или через 3 ч после лёгкого приёма пищи; можно пить воду. Заранее продукты из рациона не исключать. Накануне исключить алкоголь.', 420);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('immunohels-panel-180', 'Иммунохелс-панель 180, пищевая непереносимость IgG (ImmunoHealth, панель на 180 продуктов, специфический IgG, пищевая непереносимость)', 'Иммунология и аллергология', 'Аллергопанели', 'Определение специфических IgG к 180 пищевым продуктам для оценки пищевой непереносимости.', 'Кровь натощак или через 3 ч после лёгкого приёма пищи; можно пить воду. Заранее продукты из рациона не исключать. Накануне исключить алкоголь.', 421);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('vitamin-b12', 'Витамин B12 (цианокобаламин, кобаламин, vitamin B12, B-12)', 'Иммунология и аллергология', 'Витамины', 'Определение витамина B12 для диагностики анемий, дефицита витамина и неврологических нарушений.', 'Утром натощак, 8–12 ч голодания; можно пить воду. За 3 дня не принимать препараты B12 и поливитамины; за 2–3 дня отменить биотин.', 422);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('vitamin-b9', 'Витамин B9 (фолиевая кислота, фолаты, folate, vitamin B9)', 'Иммунология и аллергология', 'Витамины', 'Определение фолиевой кислоты для диагностики анемий, дефицита фолатов и при планировании беременности.', 'Утром натощак, 8–12 ч голодания; можно пить воду. За 3 дня не принимать препараты фолиевой кислоты и поливитамины.', 423);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('vitamin-d-25-oh', 'Витамин D 25-OH (25-гидроксивитамин D, кальциферол, 25(OH)D, vitamin D)', 'Иммунология и аллергология', 'Витамины', 'Определение 25-OH витамина D для оценки обеспеченности организма витамином D и диагностики его дефицита.', 'Утром натощак, 8–12 ч голодания; можно пить воду. В день сдачи не принимать препараты витамина D.', 424);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('vitamin-a', 'Витамин A (ретинол, retinol, vitamin A)', 'Иммунология и аллергология', 'Витамины', 'Определение витамина A (ретинола) для оценки его обеспеченности, диагностики дефицита и избытка.', 'Утром натощак, 8–12 ч голодания; можно пить воду. За 3 дня не принимать препараты витамина A и поливитамины; накануне исключить жирную пищу.', 425);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('vitamin-e', 'Витамин E (токоферол, tocopherol, vitamin E)', 'Иммунология и аллергология', 'Витамины', 'Определение витамина E (токоферола) для оценки антиоксидантного статуса и диагностики дефицита.', 'Утром натощак, 8–12 ч голодания; можно пить воду. За 3 дня не принимать препараты витамина E; накануне исключить жирную пищу.', 426);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('vitamin-c', 'Витамин C (аскорбиновая кислота, ascorbic acid, vitamin C)', 'Иммунология и аллергология', 'Витамины', 'Определение витамина C (аскорбиновой кислоты) для оценки его обеспеченности и диагностики дефицита.', 'Утром натощак, 8–12 ч голодания; можно пить воду. За 24 часа не принимать витамин C и поливитамины.', 427);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('vitamin-b1', 'Витамин B1 (тиамин, thiamine, vitamin B1)', 'Иммунология и аллергология', 'Витамины', 'Определение витамина B1 (тиамина) для диагностики дефицита и связанных неврологических нарушений.', 'Утром натощак, 8–12 ч голодания; можно пить воду. За 3 дня не принимать препараты витаминов группы B и поливитамины.', 428);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('vitamin-b6', 'Витамин B6 (пиридоксин, pyridoxine, vitamin B6)', 'Иммунология и аллергология', 'Витамины', 'Определение витамина B6 (пиридоксина) для диагностики дефицита и оценки витаминного статуса.', 'Утром натощак, 8–12 ч голодания; можно пить воду. За 3 дня не принимать препараты витаминов группы B и поливитамины.', 429);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('vitamin-k', 'Витамин K (филлохинон, phylloquinone, vitamin K)', 'Иммунология и аллергология', 'Витамины', 'Определение витамина K для оценки его обеспеченности; участвует в свёртывании крови и обмене костей.', 'Утром натощак, 8–12 ч голодания; можно пить воду. За 3 дня не принимать препараты витамина K; приём антикоагулянтов согласовать с врачом.', 430);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('vitamin-b2', 'Витамин B2 (рибофлавин, riboflavin, vitamin B2)', 'Иммунология и аллергология', 'Витамины', 'Определение витамина B2 (рибофлавина) для диагностики дефицита и оценки витаминного статуса.', 'Утром натощак, 8–12 ч голодания; можно пить воду. За 3 дня не принимать препараты витаминов группы B и поливитамины.', 431);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('vitamin-b3', 'Витамин B3 (ниацин, никотиновая кислота, niacin, vitamin B3, PP)', 'Иммунология и аллергология', 'Витамины', 'Определение витамина B3 (ниацина) для диагностики дефицита и оценки витаминного статуса.', 'Утром натощак, 8–12 ч голодания; можно пить воду. За 3 дня не принимать препараты витаминов группы B и поливитамины.', 432);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('vitamin-b5', 'Витамин B5 (пантотеновая кислота, pantothenic acid, vitamin B5)', 'Иммунология и аллергология', 'Витамины', 'Определение витамина B5 (пантотеновой кислоты) для оценки витаминного статуса и диагностики дефицита.', 'Утром натощак, 8–12 ч голодания; можно пить воду. За 3 дня не принимать препараты витаминов группы B и поливитамины.', 433);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('beta-karotin', 'Бета-каротин (beta-carotene, провитамин A, каротин)', 'Иммунология и аллергология', 'Витамины', 'Определение бета-каротина (предшественника витамина A) для оценки обеспеченности и особенностей питания.', 'Утром натощак, 8–12 ч голодания; можно пить воду. За 3 дня не принимать БАД с каротином; накануне исключить жирную пищу.', 434);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('koenzim-q10', 'Коэнзим Q10 (убихинон, coenzyme Q10, CoQ10, убидекаренон)', 'Иммунология и аллергология', 'Витамины', 'Определение коэнзима Q10 для оценки антиоксидантного статуса и энергетического обмена клеток.', 'Утром натощак, 8–12 ч голодания; можно пить воду. За 3 дня не принимать БАД с коэнзимом Q10; накануне исключить жирную пищу.', 435);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('omega-3-indeks', 'Омега-3 индекс (omega-3 index, индекс жирных кислот омега-3, ЭПК+ДГК в мембранах эритроцитов)', 'Иммунология и аллергология', 'Витамины', 'Определение омега-3 индекса для оценки обеспеченности жирными кислотами и сердечно-сосудистого риска.', 'Утром натощак, 8–12 ч голодания; можно пить воду. За 3 дня не принимать БАД с омега-3 и рыбий жир; накануне исключить жирную рыбу.', 436);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('metabolizm-vitamina-d', 'Метаболизм витамина D, комплекс (комплексная оценка витамина D, 25-OH витамин D, паратгормон, кальций, фосфор)', 'Иммунология и аллергология', 'Витамины', 'Комплексная оценка обмена витамина D с кальцием, фосфором и паратгормоном для диагностики нарушений минерального обмена.', 'Утром натощак, 8–12 ч голодания; можно пить воду. В день сдачи не принимать препараты витамина D, кальция и биотин (за 2–3 дня).', 437);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('immunoglobulin-g', 'Иммуноглобулин G общий (IgG, immunoglobulin G, общий иммуноглобулин G, гамма-глобулин)', 'Иммунология и аллергология', 'Иммуноглобулины', 'Определение общего IgG для оценки гуморального иммунитета, диагностики иммунодефицитов и хронических инфекций.', 'Утром натощак, 8–12 ч голодания; можно пить воду. Накануне исключить алкоголь и интенсивные нагрузки.', 438);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('immunoglobulin-a', 'Иммуноглобулин A общий (IgA, immunoglobulin A, общий иммуноглобулин A)', 'Иммунология и аллергология', 'Иммуноглобулины', 'Определение общего IgA для оценки иммунитета слизистых, диагностики иммунодефицитов и инфекций.', 'Утром натощак, 8–12 ч голодания; можно пить воду. Накануне исключить алкоголь и интенсивные нагрузки.', 439);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('immunoglobulin-m', 'Иммуноглобулин M общий (IgM, immunoglobulin M, общий иммуноглобулин M)', 'Иммунология и аллергология', 'Иммуноглобулины', 'Определение общего IgM для оценки гуморального иммунитета и диагностики острых инфекций и иммунодефицитов.', 'Утром натощак, 8–12 ч голодания; можно пить воду. Накануне исключить алкоголь и интенсивные нагрузки.', 440);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('immunoglobulin-e', 'Иммуноглобулин E общий (IgE, immunoglobulin E, общий иммуноглобулин E, total IgE)', 'Иммунология и аллергология', 'Иммуноглобулины', 'Определение общего IgE для оценки склонности к аллергии и диагностики аллергических и паразитарных заболеваний.', 'Утром натощак или через 3 ч после лёгкого приёма пищи; можно пить воду. Отмена антигистаминных препаратов не требуется.', 441);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('chuvstvitelnost-k-immunotropnym-preparatam', 'Чувствительность к иммунотропным препаратам (индивидуальная чувствительность к иммуномодуляторам, подбор иммунотропной терапии)', 'Иммунология и аллергология', 'Иммуноглобулины', 'Оценка индивидуальной чувствительности иммунных клеток к иммунотропным препаратам для подбора терапии.', 'Утром натощак, 8–12 ч голодания; можно пить воду. Приём иммунотропных препаратов заранее согласовать с врачом.', 442);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('immunoglobulin-d', 'Иммуноглобулин D общий (IgD, immunoglobulin D, общий иммуноглобулин D)', 'Иммунология и аллергология', 'Иммуноглобулины', 'Определение общего IgD; применяется при диагностике периодических лихорадок и отдельных иммунных нарушений.', 'Утром натощак, 8–12 ч голодания; можно пить воду. Накануне исключить алкоголь и интенсивные нагрузки.', 443);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('podklassy-igg', 'Подклассы IgG 1, 2, 3, 4 (субклассы IgG, IgG1/IgG2/IgG3/IgG4, IgG subclasses)', 'Иммунология и аллергология', 'Иммуноглобулины', 'Определение подклассов IgG для углублённой диагностики иммунодефицитов и IgG4-ассоциированных заболеваний.', 'Утром натощак, 8–12 ч голодания; можно пить воду. Накануне исключить алкоголь и интенсивные нагрузки.', 444);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('triptaza', 'Триптаза (tryptase, мастоцитарная триптаза, маркер анафилаксии и мастоцитоза)', 'Иммунология и аллергология', 'Иммуноглобулины', 'Определение триптазы — маркера активации тучных клеток; используется при анафилаксии и мастоцитозе.', 'Утром натощак; можно пить воду. При анафилаксии кровь берут в первые часы реакции и повторно после (по назначению врача).', 445);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('eozinofilnyy-kationnyy-belok', 'Эозинофильный катионный белок (ECP, ЭКБ, eosinophil cationic protein, маркер аллергического воспаления)', 'Иммунология и аллергология', 'Иммуноглобулины', 'Определение ECP — маркера активности эозинофильного воспаления при астме и аллергии.', 'Утром натощак, 8–12 ч голодания; можно пить воду. Отмена антигистаминных препаратов не требуется; уточнить в лаборатории условия взятия.', 446);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('immunofiksatsiya-s-opredeleniem-paraproteina', 'Иммунофиксация с определением парапротеина (иммунофиксация, IFE, типирование парапротеина, моноклональный белок, immunofixation)', 'Иммунология и аллергология', 'Иммуноглобулины', 'Выявление и типирование парапротеина (моноклонального белка) при подозрении на миелому и парапротеинемии.', 'Утром натощак, 8–12 ч голодания; можно пить воду. Накануне исключить алкоголь.', 447);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('immunofenotipirovanie-limfotsitov', 'Иммунофенотипирование лимфоцитов (субпопуляции лимфоцитов, CD3/CD4/CD8/CD19/CD16+56, проточная цитометрия, лимфоцитарный профиль)', 'Иммунология и аллергология', 'клеточный иммунитет', 'Определение субпопуляций лимфоцитов (T, B, NK) методом проточной цитометрии для оценки иммунного статуса.', 'Утром натощак или через 3 ч после лёгкого приёма пищи; можно пить воду. Сдавать вне острой инфекции; приём иммунных препаратов согласовать с врачом.', 448);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('sootnoshenie-cd4-cd8', 'Соотношение CD4/CD8 (иммунорегуляторный индекс, CD4/CD8 ratio, хелперы/супрессоры)', 'Иммунология и аллергология', 'клеточный иммунитет', 'Расчёт соотношения CD4/CD8 (иммунорегуляторного индекса) для оценки баланса Т-лимфоцитов и иммунного статуса.', 'Утром натощак или через 3 ч после лёгкого приёма пищи; можно пить воду. Сдавать вне острой инфекции; приём иммунных препаратов согласовать с врачом.', 449);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('nk-kletki', 'NK-клетки (натуральные киллеры, CD16+CD56, natural killer cells, естественные киллеры)', 'Иммунология и аллергология', 'клеточный иммунитет', 'Определение количества NK-клеток (натуральных киллеров) для оценки противовирусного и противоопухолевого иммунитета.', 'Утром натощак или через 3 ч после лёгкого приёма пищи; можно пить воду. Сдавать вне острой инфекции; приём иммунных препаратов согласовать с врачом.', 450);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('fagotsitarnaya-aktivnost-neytrofilov', 'Фагоцитарная активность нейтрофилов (фагоцитоз, фагоцитарный индекс, NBT-тест, оценка фагоцитоза)', 'Иммунология и аллергология', 'клеточный иммунитет', 'Оценка способности нейтрофилов поглощать и уничтожать микробы для диагностики нарушений фагоцитоза.', 'Утром натощак или через 3 ч после лёгкого приёма пищи; можно пить воду. Сдавать вне острой инфекции; проба исследуется быстро — уточнить условия в лаборатории.', 451);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('immunogramma-razvernutaya', 'Иммунограмма развёрнутая (расширенный иммунный статус, комплексная оценка иммунитета, клеточный и гуморальный иммунитет)', 'Иммунология и аллергология', 'клеточный иммунитет', 'Комплексная оценка клеточного и гуморального иммунитета для диагностики иммунодефицитов и иммунных нарушений.', 'Утром натощак, 8–12 ч голодания; можно пить воду. Сдавать вне острой инфекции; приём иммунотропных препаратов согласовать с врачом.', 452);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('kvantiferonovyy-test', 'Квантифероновый тест QuantiFERON-TB Gold (QFT, IGRA, интерфероновый тест на туберкулёз, гамма-интерфероновый тест, латентный туберкулёз)', 'Иммунология и аллергология', 'туберкулёз (IGRA)', 'Определение специфического ответа на антигены микобактерий туберкулёза для диагностики латентной и активной инфекции.', 'Специальной подготовки не требуется, кровь можно сдавать в течение дня. Кровь берут в специальные пробирки и быстро доставляют в лабораторию.', 453);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('t-spot-tb', 'T-SPOT.TB (T-SPOT, IGRA, интерфероновый тест на туберкулёз, ELISPOT, латентный туберкулёз)', 'Иммунология и аллергология', 'туберкулёз (IGRA)', 'Определение Т-клеточного ответа на антигены микобактерий туберкулёза для диагностики туберкулёзной инфекции.', 'Специальной подготовки не требуется, кровь можно сдавать в течение дня. Кровь берут в специальные пробирки и быстро доставляют в лабораторию.', 454);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('allergen-c1-penitsillinovoe-soedinenie', 'Аллерген C1, пенициллоил G (Penicilloyl G, пенициллин G, бензилпенициллин, IgE, специфический IgE)', 'Иммунология и аллергология', 'аллергия на лекарства и анестетики', 'Определение специфических IgE к пенициллину G для диагностики лекарственной аллергии на пенициллины.', 'Кровь натощак или через 3 ч после лёгкого приёма пищи; можно пить воду. Отмена антигистаминных препаратов перед анализом крови не требуется.', 455);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('allergen-c2-penitsillinovoe-soedinenie-v', 'Аллерген C2, пенициллоил V (Penicilloyl V, пенициллин V, феноксиметилпенициллин, IgE, специфический IgE)', 'Иммунология и аллергология', 'аллергия на лекарства и анестетики', 'Определение специфических IgE к пенициллину V для диагностики лекарственной аллергии на пенициллины.', 'Кровь натощак или через 3 ч после лёгкого приёма пищи; можно пить воду. Отмена антигистаминных препаратов перед анализом крови не требуется.', 456);
