INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('moloko-kazein-nbos-d-8', 'Молоко, бета-лактоглобулин nBos d 5 (Bos domesticus, beta-lactoglobulin, белок коровьего молока, IgE, специфический IgE)', 'Иммунология и аллергология', 'молекулярная аллергодиагностика (компоненты)', 'Определение IgE к бета-лактоглобулину nBos d 5 для уточнённой диагностики аллергии на коровье молоко.', 'Кровь натощак или через 3 ч после лёгкого приёма пищи; можно пить воду. Отмена антигистаминных препаратов перед анализом крови не требуется.', 511);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('gliadin-f98', 'Глиадин f98 (gliadin, глиадин пшеницы, компонент глютена, IgE, специфический IgE)', 'Иммунология и аллергология', 'молекулярная аллергодиагностика (компоненты)', 'Определение IgE к глиадину (f98) для уточнённой диагностики аллергии на пшеницу.', 'Кровь натощак или через 3 ч после лёгкого приёма пищи; можно пить воду. Отмена антигистаминных препаратов перед анализом крови не требуется.', 512);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('alfa-gal-o215', 'Альфа-Gal, говядина o215 (alpha-Gal, галактоза-альфа-1,3-галактоза, синдром альфа-гал, замедленная реакция на мясо, IgE, специфический IgE)', 'Иммунология и аллергология', 'молекулярная аллергодиагностика (компоненты)', 'Определение IgE к альфа-Gal (o215) для диагностики синдрома альфа-гал — замедленной аллергии на красное мясо.', 'Кровь натощак или через 3 ч после лёгкого приёма пищи; можно пить воду. Отмена антигистаминных препаратов перед анализом крови не требуется.', 513);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('polyn-obyknovennaya-nart-v-3', 'Полынь обыкновенная, nArt v 3 (Artemisia vulgaris, LTP, липид-переносящий белок, маркёр перекрёстной реактивности, IgE, специфический IgE)', 'Иммунология и аллергология', 'молекулярная аллергодиагностика (компоненты)', 'Определение IgE к nArt v 3 (LTP) — маркёру сенсибилизации к полыни и перекрёстных пищевых реакций.', 'Кровь натощак или через 3 ч после лёгкого приёма пищи; можно пить воду. Отмена антигистаминных препаратов перед анализом крови не требуется.', 514);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('timofeevka-lugovaya-rphl-p-1-i-rphl-p-5b', 'Тимофеевка луговая, rPhl p 1 и rPhl p 5b (Phleum pratense, мажорные маркёры пыльцы злаков, поллиноз, IgE, специфический IgE)', 'Иммунология и аллергология', 'молекулярная аллергодиагностика (компоненты)', 'Определение IgE к rPhl p 1 и rPhl p 5b — мажорным маркёрам истинной сенсибилизации к пыльце злаковых трав.', 'Кровь натощак или через 3 ч после лёгкого приёма пищи; можно пить воду. Отмена антигистаминных препаратов перед анализом крови не требуется.', 515);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('timofeevka-lugovaya-rphl-p-7-i-rphl-p-12', 'Тимофеевка луговая, rPhl p 7 и rPhl p 12 (Phleum pratense, полькальцин и профилин, маркёры перекрёстной реактивности, IgE, специфический IgE)', 'Иммунология и аллергология', 'молекулярная аллергодиагностика (компоненты)', 'Определение IgE к rPhl p 7 и rPhl p 12 — минорным маркёрам перекрёстной реактивности пыльцы (полькальцин, профилин).', 'Кровь натощак или через 3 ч после лёгкого приёма пищи; можно пить воду. Отмена антигистаминных препаратов перед анализом крови не требуется.', 516);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('dnk-gonokokka', 'ПЦР на гонококк (Neisseria gonorrhoeae, нейссерия, возбудитель гонореи, ДНК гонококка, гонорея), качественный', 'ПЦР-диагностика', 'Урогенитальные исследования', 'Определение ДНК гонококка методом ПЦР для диагностики гонореи и контроля лечения ИППП.', 'Соскоб: за 2 недели отменить антибиотики, за 3 часа не мочиться. Женщинам — не сдавать во время менструации.', 517);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('dnk-hlamidii', 'ПЦР на хламидию (Chlamydia trachomatis, хламидия трахоматис, ДНК хламидии, хламидиоз), качественный', 'ПЦР-диагностика', 'Урогенитальные исследования', 'Определение ДНК хламидии методом ПЦР для диагностики урогенитального хламидиоза.', 'Соскоб: за 2 недели отменить антибиотики, за 3 часа не мочиться. Женщинам — не сдавать во время менструации.', 518);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('dnk-trihomonady', 'ПЦР на трихомонаду (Trichomonas vaginalis, трихомонада, ДНК трихомонады, трихомониаз), качественный', 'ПЦР-диагностика', 'Урогенитальные исследования', 'Определение ДНК трихомонады методом ПЦР для диагностики трихомониаза.', 'Соскоб: за 2 недели отменить антибиотики, за 3 часа не мочиться. Женщинам — не сдавать во время менструации.', 519);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('dnk-mikoplazmy', 'ПЦР на микоплазму гениталиум (Mycoplasma genitalium, микоплазма, ДНК микоплазмы, микоплазмоз), качественный', 'ПЦР-диагностика', 'Урогенитальные исследования', 'Определение ДНК Mycoplasma genitalium методом ПЦР для диагностики микоплазменной инфекции.', 'Соскоб: за 2 недели отменить антибиотики, за 3 часа не мочиться. Женщинам — не сдавать во время менструации.', 520);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('dnk-mikoplazmy-2', 'ПЦР на микоплазму хоминис (Mycoplasma hominis, микоплазма, ДНК микоплазмы, микоплазмоз), качественный', 'ПЦР-диагностика', 'Урогенитальные исследования', 'Определение ДНК Mycoplasma hominis методом ПЦР для диагностики микоплазменной инфекции.', 'Соскоб: за 2 недели отменить антибиотики, за 3 часа не мочиться. Женщинам — не сдавать во время менструации.', 521);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('dnk-kandidy', 'ПЦР на кандиду (Candida albicans, кандида, ДНК кандиды, кандидоз, молочница), качественный', 'ПЦР-диагностика', 'Урогенитальные исследования', 'Определение ДНК Candida albicans методом ПЦР для диагностики кандидоза (молочницы).', 'Соскоб: за 2 недели отменить противогрибковые препараты и антибиотики, за 3 часа не мочиться. Женщинам — не сдавать во время менструации.', 522);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('dnk-gardnerelly', 'ПЦР на гарднереллу (Gardnerella vaginalis, гарднерелла, ДНК гарднереллы, бактериальный вагиноз), качественный', 'ПЦР-диагностика', 'Урогенитальные исследования', 'Определение ДНК гарднереллы методом ПЦР для диагностики бактериального вагиноза.', 'Соскоб: за 2 недели отменить антибиотики, за 3 часа не мочиться. Не сдавать во время менструации; накануне исключить спринцевания и свечи.', 523);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('dnk-ureaplazmy', 'ПЦР на уреаплазму уреалитикум (Ureaplasma urealyticum, уреаплазма, ДНК уреаплазмы, уреаплазмоз), качественный', 'ПЦР-диагностика', 'Урогенитальные исследования', 'Определение ДНК Ureaplasma urealyticum методом ПЦР для диагностики уреаплазменной инфекции.', 'Соскоб: за 2 недели отменить антибиотики, за 3 часа не мочиться. Женщинам — не сдавать во время менструации.', 524);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('dnk-ureaplazmy-2', 'ПЦР на уреаплазму парвум (Ureaplasma parvum, уреаплазма, ДНК уреаплазмы, уреаплазмоз), качественный', 'ПЦР-диагностика', 'Урогенитальные исследования', 'Определение ДНК Ureaplasma parvum методом ПЦР для диагностики уреаплазменной инфекции.', 'Соскоб: за 2 недели отменить антибиотики, за 3 часа не мочиться. Женщинам — не сдавать во время менструации.', 525);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('dnk-ureaplazmy-3', 'ПЦР на уреаплазму (Ureaplasma urealyticum + parvum, уреаплазма, ДНК уреаплазмы, уреаплазмоз, оба вида), качественный', 'ПЦР-диагностика', 'Урогенитальные исследования', 'Определение ДНК двух видов уреаплазмы (urealyticum и parvum) методом ПЦР для диагностики уреаплазмоза.', 'Соскоб: за 2 недели отменить антибиотики, за 3 часа не мочиться. Женщинам — не сдавать во время менструации.', 526);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('kompleks-hlamidiya-mikoplazma-ureaplazma', 'Комплекс ПЦР: хламидия + микоплазма + уреаплазма (Chlamydia trachomatis, Mycoplasma genitalium, Ureaplasma, ИППП, комплекс ДНК), качественный', 'ПЦР-диагностика', 'Урогенитальные исследования', 'Комплексное определение ДНК хламидии, микоплазмы и уреаплазмы методом ПЦР для диагностики ИППП.', 'Соскоб: за 2 недели отменить антибиотики, за 3 часа не мочиться. Женщинам — не сдавать во время менструации.', 527);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('streptokokk-gruppy-b-ptsr', 'ПЦР на стрептококк группы B (Streptococcus agalactiae, стрептококк агалактия, СГВ, GBS, ДНК стрептококка), качественный', 'ПЦР-диагностика', 'Урогенитальные исследования', 'Определение ДНК стрептококка группы B методом ПЦР, в том числе для скрининга беременных.', 'Соскоб/мазок: за 2 недели отменить антибиотики. Женщинам — не сдавать во время менструации; накануне исключить спринцевания и свечи.', 528);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('femoflor-16', 'Фемофлор 16 (Femoflor 16, расширенный биоценоз урогенитального тракта, микрофлора влагалища, ДНК, количественный)', 'ПЦР-диагностика', 'Урогенитальные исследования', 'Количественная оценка 16 показателей микрофлоры урогенитального тракта у женщин методом ПЦР.', 'Соскоб: за 2 недели отменить антибиотики и пробиотики, за 3 часа не мочиться. Не сдавать во время менструации; накануне исключить спринцевания, свечи и половой контакт.', 529);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('femoflor-8', 'Фемофлор 8 (Femoflor 8, биоценоз урогенитального тракта, микрофлора влагалища, ДНК, количественный)', 'ПЦР-диагностика', 'Урогенитальные исследования', 'Количественная оценка 8 показателей микрофлоры урогенитального тракта у женщин методом ПЦР.', 'Соскоб: за 2 недели отменить антибиотики и пробиотики, за 3 часа не мочиться. Не сдавать во время менструации; накануне исключить спринцевания, свечи и половой контакт.', 530);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('androflor', 'Андрофлор расширенный (Androflor, биоценоз урогенитального тракта у мужчин, мужская микрофлора, ДНК, количественный)', 'ПЦР-диагностика', 'Урогенитальные исследования', 'Количественная оценка микрофлоры урогенитального тракта у мужчин методом ПЦР.', 'Соскоб из уретры: за 2 недели отменить антибиотики, за 3 часа не мочиться. Накануне исключить половой контакт.', 531);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('dnk-mycoplasma-genitalium-kolichestvenno', 'ПЦР на микоплазму гениталиум, количественно (Mycoplasma genitalium, микоплазма, ДНК микоплазмы, вирусная нагрузка), количественный', 'ПЦР-диагностика', 'Урогенитальные исследования', 'Количественное определение ДНК Mycoplasma genitalium методом ПЦР для диагностики и контроля лечения.', 'Соскоб: за 2 недели отменить антибиотики, за 3 часа не мочиться. Женщинам — не сдавать во время менструации.', 532);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('dnk-treponema-pallidum', 'ПЦР на бледную трепонему (Treponema pallidum, трепонема, ДНК трепонемы, возбудитель сифилиса, сифилис), качественный', 'ПЦР-диагностика', 'Урогенитальные исследования', 'Определение ДНК бледной трепонемы методом ПЦР для диагностики сифилиса, в том числе из очага поражения.', 'Соскоб/отделяемое из очага: за 2 недели отменить антибиотики. Не обрабатывать элемент антисептиками перед взятием материала.', 533);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('dnk-virusa-epshteyna-barr', 'ПЦР на вирус Эпштейна-Барр (Epstein-Barr virus, ВЭБ, EBV, ДНК ВЭБ, инфекционный мононуклеоз), качественный', 'ПЦР-диагностика', 'системные и торч инфекции', 'Определение ДНК вируса Эпштейна-Барр методом ПЦР для диагностики ВЭБ-инфекции и инфекционного мононуклеоза.', 'Кровь — утром натощак или через 3 ч после еды; соскоб — за 3 часа не мочиться. За 2 недели отменить противовирусные препараты (по согласованию с врачом).', 534);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('dnk-virusa-prostogo-gerpesa-i-i-ii-tipov', 'ПЦР на вирус простого герпеса I и II типов (Herpes simplex virus 1/2, ВПГ-1/2, HSV, ДНК герпеса, генитальный герпес), качественный', 'ПЦР-диагностика', 'системные и торч инфекции', 'Определение ДНК вируса простого герпеса I и II типов методом ПЦР для диагностики герпетической инфекции.', 'Соскоб из очага — не обрабатывать антисептиками; за 3 часа не мочиться. За 2 недели отменить противовирусные препараты (по согласованию с врачом).', 535);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('dnk-virusa-prostogo-gerpesa-i-tsitomegalovirusa', 'ПЦР на вирус простого герпеса и цитомегаловирус (HSV + CMV, ВПГ + ЦМВ, ДНК герпеса и цитомегаловируса), качественный', 'ПЦР-диагностика', 'системные и торч инфекции', 'Совместное определение ДНК вируса простого герпеса и цитомегаловируса методом ПЦР.', 'Кровь — утром натощак или через 3 ч после еды; соскоб — за 3 часа не мочиться. За 2 недели отменить противовирусные препараты (по согласованию с врачом).', 536);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('dnk-tsmv', 'ПЦР на цитомегаловирус (Cytomegalovirus, ЦМВ, CMV, ДНК ЦМВ, цитомегаловирусная инфекция), качественный', 'ПЦР-диагностика', 'системные и торч инфекции', 'Определение ДНК цитомегаловируса методом ПЦР для диагностики ЦМВ-инфекции.', 'Кровь — утром натощак или через 3 ч после еды; соскоб/слюна/моча по показанию. За 2 недели отменить противовирусные препараты (по согласованию с врачом).', 537);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('dnk-toksoplazmy', 'ПЦР на токсоплазму (Toxoplasma gondii, токсоплазма, ДНК токсоплазмы, токсоплазмоз), качественный', 'ПЦР-диагностика', 'системные и торч инфекции', 'Определение ДНК токсоплазмы методом ПЦР для диагностики токсоплазмоза, в том числе при беременности.', 'Кровь — утром натощак или через 3 ч после еды. Материал (кровь, ликвор, околоплодные воды) — по назначению врача.', 538);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('dnk-virusa-gerpesa-6-tipa', 'ПЦР на вирус герпеса 6 типа (Human herpesvirus 6, ВГЧ-6, HHV-6, ДНК герпеса 6 типа), качественный', 'ПЦР-диагностика', 'системные и торч инфекции', 'Определение ДНК вируса герпеса человека 6 типа методом ПЦР для диагностики инфекции.', 'Кровь — утром натощак или через 3 ч после еды; слюна/соскоб по показанию. За 2 недели отменить противовирусные препараты (по согласованию с врачом).', 539);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('dnk-virusa-gerpesa-7-tipa', 'ПЦР на вирус герпеса 7 типа (Human herpesvirus 7, ВГЧ-7, HHV-7, ДНК герпеса 7 типа), качественный', 'ПЦР-диагностика', 'системные и торч инфекции', 'Определение ДНК вируса герпеса человека 7 типа методом ПЦР для диагностики инфекции.', 'Кровь — утром натощак или через 3 ч после еды; слюна/соскоб по показанию. За 2 недели отменить противовирусные препараты (по согласованию с врачом).', 540);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('dnk-virusa-gerpesa-8-tipa', 'ПЦР на вирус герпеса 8 типа (Human herpesvirus 8, ВГЧ-8, HHV-8, ДНК герпеса 8 типа, саркома Капоши), качественный', 'ПЦР-диагностика', 'системные и торч инфекции', 'Определение ДНК вируса герпеса человека 8 типа методом ПЦР; связан с саркомой Капоши.', 'Кровь — утром натощак или через 3 ч после еды; материал по показанию. За 2 недели отменить противовирусные препараты (по согласованию с врачом).', 541);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('dnk-parvovirusa-b19', 'ПЦР на парвовирус B19 (Parvovirus B19, парвовирус, ДНК парвовируса, инфекционная эритема), качественный', 'ПЦР-диагностика', 'системные и торч инфекции', 'Определение ДНК парвовируса B19 методом ПЦР для диагностики инфекции, в том числе при беременности и анемии.', 'Кровь — утром натощак или через 3 ч после еды. Материал — по назначению врача.', 542);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('dnk-virusa-varicella-zoster', 'ПЦР на вирус Varicella zoster (Varicella zoster virus, ВВЗ, VZV, ДНК вируса, ветряная оспа, опоясывающий лишай), качественный', 'ПЦР-диагностика', 'системные и торч инфекции', 'Определение ДНК вируса Varicella zoster методом ПЦР для диагностики ветряной оспы и опоясывающего лишая.', 'Соскоб/содержимое везикул — не обрабатывать антисептиками. Кровь/ликвор по показанию. За 2 недели отменить противовирусные препараты (по согласованию с врачом).', 543);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('dnk-virusa-prostogo-gerpesa-s-differentsiatsiey-i-i-ii-tipov', 'ПЦР на вирус простого герпеса с типированием I и II, количественно (HSV-1/2, ВПГ-1/2, ДНК герпеса, дифференциация типов, вирусная нагрузка), количественный', 'ПЦР-диагностика', 'системные и торч инфекции', 'Количественное определение ДНК вируса простого герпеса с различением I и II типов методом ПЦР.', 'Соскоб из очага — не обрабатывать антисептиками; за 3 часа не мочиться. За 2 недели отменить противовирусные препараты (по согласованию с врачом).', 544);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('dnk-tsmv-kolichestvenno', 'ПЦР на цитомегаловирус, количественно (Cytomegalovirus, ЦМВ, CMV, ДНК ЦМВ, вирусная нагрузка), количественный', 'ПЦР-диагностика', 'системные и торч инфекции', 'Количественное определение ДНК цитомегаловируса методом ПЦР для оценки вирусной нагрузки и контроля лечения.', 'Кровь — утром натощак или через 3 ч после еды. За 2 недели отменить противовирусные препараты (по согласованию с врачом).', 545);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('dnk-virusa-epshteyna-barr-kolichestvenno', 'ПЦР на вирус Эпштейна-Барр, количественно (Epstein-Barr virus, ВЭБ, EBV, ДНК ВЭБ, вирусная нагрузка), количественный', 'ПЦР-диагностика', 'системные и торч инфекции', 'Количественное определение ДНК вируса Эпштейна-Барр методом ПЦР для оценки вирусной нагрузки и контроля лечения.', 'Кровь — утром натощак или через 3 ч после еды. За 2 недели отменить противовирусные препараты (по согласованию с врачом).', 546);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('kompleks-dnk-veb-tsmv-vgch-6-kolichestvenno', 'Комплекс ПЦР: ВЭБ + ЦМВ + ВГЧ-6, количественно (EBV + CMV + HHV-6, ДНК герпес-вирусов, вирусная нагрузка, комплекс), количественный', 'ПЦР-диагностика', 'системные и торч инфекции', 'Количественное определение ДНК вирусов Эпштейна-Барр, цитомегаловируса и герпеса 6 типа методом ПЦР.', 'Кровь — утром натощак или через 3 ч после еды. За 2 недели отменить противовирусные препараты (по согласованию с врачом).', 547);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('ptsr-covid-19', 'ПЦР на SARS-CoV-2 (COVID-19, коронавирус, РНК SARS-CoV-2, ДНК ковид, ковид), качественный', 'ПЦР-диагностика', 'респираторные инфекции', 'Определение РНК вируса SARS-CoV-2 методом ПЦР для диагностики COVID-19.', 'Мазок из носо-/ротоглотки. За 3 часа не есть, не пить, не курить, не чистить зубы и не полоскать рот, не использовать капли и спреи для носа.', 548);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('diagnostika-orvi', 'ПЦР-диагностика ОРВИ, метапневмовирус + 6 возбудителей (респираторная панель ОРВИ, грипп, РСВ, аденовирус, парагрипп, метапневмовирус, риновирус, РНК/ДНК), качественный', 'ПЦР-диагностика', 'респираторные инфекции', 'Комплексное определение основных возбудителей ОРВИ методом ПЦР для установления причины респираторной инфекции.', 'Мазок из носо-/ротоглотки. За 3 часа не есть, не пить, не курить, не чистить зубы и не полоскать рот, не использовать капли и спреи для носа.', 549);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('opredelenie-antigena-sars-cov-2', 'Антиген SARS-CoV-2 (АГ, COVID-19, коронавирус, экспресс-тест на антиген, ковид, antigen), качественный', 'ПЦР-диагностика', 'респираторные инфекции', 'Выявление антигена вируса SARS-CoV-2 для быстрой диагностики COVID-19.', 'Мазок из носо-/ротоглотки. За 3 часа не есть, не пить, не курить, не полоскать рот, не использовать капли и спреи для носа.', 550);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('gripp-a-b', 'ПЦР на грипп A/B (Influenza A/B, вирус гриппа, РНК гриппа, ДНК грипп, грипп типа A и B), качественный', 'ПЦР-диагностика', 'респираторные инфекции', 'Определение РНК вирусов гриппа A и B методом ПЦР для диагностики гриппа.', 'Мазок из носо-/ротоглотки. За 3 часа не есть, не пить, не курить, не чистить зубы и не полоскать рот, не использовать капли и спреи для носа.', 551);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('respiratorno-sintsitialnyy-virus-ptsr', 'ПЦР на респираторно-синцитиальный вирус (Respiratory syncytial virus, РСВ, RSV, РНК РСВ, ДНК РСВ), качественный', 'ПЦР-диагностика', 'респираторные инфекции', 'Определение РНК респираторно-синцитиального вируса методом ПЦР для диагностики РСВ-инфекции, особенно у детей.', 'Мазок из носо-/ротоглотки. За 3 часа не есть, не пить, не курить, не чистить зубы и не полоскать рот, не использовать капли и спреи для носа.', 552);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('dnk-mycoplasma-pneumoniae', 'ПЦР на микоплазму пневмонии (Mycoplasma pneumoniae, микоплазма пневмония, ДНК микоплазмы, микоплазменная пневмония), качественный', 'ПЦР-диагностика', 'респираторные инфекции', 'Определение ДНК Mycoplasma pneumoniae методом ПЦР для диагностики микоплазменной респираторной инфекции и пневмонии.', 'Мазок из носо-/ротоглотки (или мокрота). За 3 часа не есть, не пить, не курить, не полоскать рот, не использовать капли и спреи для носа.', 553);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('dnk-chlamydophila-pneumoniae', 'ПЦР на хламидофилу пневмонии (Chlamydophila pneumoniae, Chlamydia pneumoniae, хламидофила, ДНК хламидофилы, хламидийная пневмония), качественный', 'ПЦР-диагностика', 'респираторные инфекции', 'Определение ДНК Chlamydophila pneumoniae методом ПЦР для диагностики хламидийной респираторной инфекции и пневмонии.', 'Мазок из носо-/ротоглотки (или мокрота). За 3 часа не есть, не пить, не курить, не полоскать рот, не использовать капли и спреи для носа.', 554);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('dnk-bordetella-pertussis-parapertussis', 'ПЦР на бордетеллу коклюша и паракоклюша (Bordetella pertussis / parapertussis, бордетелла, ДНК бордетеллы, коклюш, паракоклюш), качественный', 'ПЦР-диагностика', 'респираторные инфекции', 'Определение ДНК возбудителей коклюша и паракоклюша методом ПЦР для диагностики инфекции.', 'Мазок из носоглотки. За 3 часа не есть, не пить, не курить, не полоскать рот, не использовать капли и спреи для носа. За 2 недели отменить антибиотики (по согласованию с врачом).', 555);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('dnk-legionella-pneumophila', 'ПЦР на легионеллу (Legionella pneumophila, легионелла, ДНК легионеллы, легионеллёз, болезнь легионеров), качественный', 'ПЦР-диагностика', 'респираторные инфекции', 'Определение ДНК Legionella pneumophila методом ПЦР для диагностики легионеллёзной пневмонии.', 'Мокрота или мазок из носо-/ротоглотки. За 3 часа не есть, не пить, не курить, не полоскать рот. За 2 недели отменить антибиотики (по согласованию с врачом).', 556);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('dnk-pneumocystis-jirovecii', 'ПЦР на пневмоцисту (Pneumocystis jirovecii, пневмоциста, ДНК пневмоцисты, пневмоцистная пневмония, PCP), качественный', 'ПЦР-диагностика', 'респираторные инфекции', 'Определение ДНК Pneumocystis jirovecii методом ПЦР для диагностики пневмоцистной пневмонии, в том числе при иммунодефиците.', 'Мокрота, индуцированная мокрота или лаважная жидкость по назначению врача. За 3 часа не есть, не пить, не курить, не полоскать рот.', 557);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('rnk-virusa-gepatita-c', 'ПЦР на вирус гепатита C (HCV, гепатит С, РНК вируса гепатита С, ВГС, hepatitis C), качественный', 'ПЦР-диагностика', 'Вирусные гепатиты', 'Определение РНК вируса гепатита C методом ПЦР для подтверждения инфекции и активной репликации вируса.', 'Утром натощак или через 3 ч после лёгкого приёма пищи; можно пить воду. Схему противовирусной терапии не менять без назначения врача.', 558);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('rnk-virusa-gepatita-c-genotipirovanie', 'ПЦР на вирус гепатита C, генотипирование (HCV генотип, генотипы 1a/1b/2/3a/3b, тип вируса гепатита С, генотипирование ВГС), качественный', 'ПЦР-диагностика', 'Вирусные гепатиты', 'Определение генотипа вируса гепатита C методом ПЦР для выбора схемы и прогноза противовирусной терапии.', 'Утром натощак или через 3 ч после лёгкого приёма пищи; можно пить воду. Выполняется при подтверждённой РНК HCV.', 559);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('rnk-virusa-gepatita-c-kolichestvenno', 'ПЦР на вирус гепатита C, количественно (HCV вирусная нагрузка, РНК HCV количественно, viral load, гепатит С), количественный', 'ПЦР-диагностика', 'Вирусные гепатиты', 'Количественное определение РНК вируса гепатита C методом ПЦР для оценки вирусной нагрузки и контроля лечения.', 'Утром натощак или через 3 ч после лёгкого приёма пищи; можно пить воду. Схему противовирусной терапии не менять без назначения врача.', 560);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('rnk-virusa-gepatita-d-kachestvenno', 'ПЦР на вирус гепатита D (HDV, гепатит D, РНК вируса гепатита D, дельта-гепатит, ВГD), качественный', 'ПЦР-диагностика', 'Вирусные гепатиты', 'Определение РНК вируса гепатита D методом ПЦР для диагностики дельта-инфекции у носителей гепатита B.', 'Утром натощак или через 3 ч после лёгкого приёма пищи; можно пить воду. Схему противовирусной терапии не менять без назначения врача.', 561);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('rnk-virusa-gepatita-d-kolichestvenno', 'ПЦР на вирус гепатита D, количественно (HDV-RNA, гепатит D, РНК HDV количественно, дельта-гепатит, вирусная нагрузка), количественный', 'ПЦР-диагностика', 'Вирусные гепатиты', 'Количественное определение РНК вируса гепатита D методом ПЦР для оценки вирусной нагрузки и контроля лечения.', 'Утром натощак или через 3 ч после лёгкого приёма пищи; можно пить воду. Схему противовирусной терапии не менять без назначения врача.', 562);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('dnk-virusa-gepatita-b', 'ПЦР на вирус гепатита B (HBV, гепатит В, ДНК вируса гепатита B, ВГВ, hepatitis B), качественный', 'ПЦР-диагностика', 'Вирусные гепатиты', 'Определение ДНК вируса гепатита B методом ПЦР для подтверждения инфекции и активной репликации вируса.', 'Утром натощак или через 3 ч после лёгкого приёма пищи; можно пить воду. Схему противовирусной терапии не менять без назначения врача.', 563);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('dnk-virusa-gepatita-b-kolichestvenno', 'ПЦР на вирус гепатита B, количественно (HBV вирусная нагрузка, ДНК HBV количественно, viral load, гепатит В), количественный', 'ПЦР-диагностика', 'Вирусные гепатиты', 'Количественное определение ДНК вируса гепатита B методом ПЦР для оценки вирусной нагрузки и контроля лечения.', 'Утром натощак или через 3 ч после лёгкого приёма пищи; можно пить воду. Схему противовирусной терапии не менять без назначения врача.', 564);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('rnk-virusa-gepatita-a', 'ПЦР на вирус гепатита A (HAV, гепатит А, РНК вируса гепатита A, ВГА, hepatitis A), качественный', 'ПЦР-диагностика', 'Вирусные гепатиты', 'Определение РНК вируса гепатита A методом ПЦР для диагностики острой инфекции.', 'Утром натощак или через 3 ч после лёгкого приёма пищи; можно пить воду.', 565);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('dnk-virusa-gepatita-b-genotipirovanie', 'ПЦР на вирус гепатита B, генотипирование (HBV генотип, генотипы вируса гепатита B, тип вируса, генотипирование ВГВ), качественный', 'ПЦР-диагностика', 'Вирусные гепатиты', 'Определение генотипа вируса гепатита B методом ПЦР для прогноза течения и выбора терапии.', 'Утром натощак или через 3 ч после лёгкого приёма пищи; можно пить воду. Выполняется при подтверждённой ДНК HBV.', 566);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('dnk-hbv-mutatsii-lekarstvennoy-ustoychivosti', 'ПЦР на ДНК HBV, мутации лекарственной устойчивости (HBV резистентность, мутации устойчивости вируса гепатита B, drug resistance, гепатит В), качественный', 'ПЦР-диагностика', 'Вирусные гепатиты', 'Выявление мутаций лекарственной устойчивости вируса гепатита B методом ПЦР для коррекции противовирусной терапии.', 'Утром натощак или через 3 ч после лёгкого приёма пищи; можно пить воду. Выполняется на фоне терапии по назначению врача.', 567);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('dnk-helikobaktera', 'ПЦР на хеликобактер (Helicobacter pylori, хеликобактер пилори, H. pylori, ДНК хеликобактера, HP), качественный', 'ПЦР-диагностика', 'Желудочно кишечные инфекции', 'Определение ДНК Helicobacter pylori методом ПЦР для диагностики инфекции при гастрите и язвенной болезни.', 'Кал в чистый контейнер (или биоптат по назначению). За 2 недели отменить антибиотики и препараты висмута, за 7 дней — ингибиторы протонной помпы (по согласованию с врачом).', 568);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('rotavirus-norovirus-astrovirus', 'ПЦР на ротавирус, норовирус, астровирус (ротавирус, норовирус, астровирус, РНК вирусов, кишечная вирусная инфекция, ОКИ), качественный', 'ПЦР-диагностика', 'Желудочно кишечные инфекции', 'Определение основных кишечных вирусов методом ПЦР для диагностики острой кишечной инфекции.', 'Свежий кал в чистый контейнер, желательно собрать в острый период болезни. Без клизм и слабительных.', 569);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('clostridioides-difficile-toksiny-a-b', 'ПЦР на Clostridioides difficile, токсины A/B (C. difficile, клостридиум диффициле, токсины А и B, ДНК токсинов, псевдомембранозный колит), качественный', 'ПЦР-диагностика', 'Желудочно кишечные инфекции', 'Определение генов токсинов A/B Clostridioides difficile методом ПЦР для диагностики антибиотик-ассоциированного колита.', 'Свежий жидкий кал в чистый контейнер, доставить в лабораторию быстро. Без клизм и слабительных.', 570);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('salmonelly-i-shigelly', 'ПЦР на сальмонеллы и шигеллы (Salmonella, Shigella, сальмонелла, шигелла, ДНК возбудителей, сальмонеллёз, дизентерия), качественный', 'ПЦР-диагностика', 'Желудочно кишечные инфекции', 'Определение ДНК сальмонелл и шигелл методом ПЦР для диагностики сальмонеллёза и дизентерии.', 'Свежий кал в чистый контейнер без клизм и слабительных. За 2 недели отменить антибиотики (по согласованию с врачом).', 571);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('dnk-campylobacter-spp', 'ПЦР на кампилобактер (Campylobacter spp., кампилобактер, ДНК кампилобактера, кампилобактериоз), качественный', 'ПЦР-диагностика', 'Желудочно кишечные инфекции', 'Определение ДНК Campylobacter методом ПЦР для диагностики кампилобактериоза — частой причины кишечной инфекции.', 'Свежий кал в чистый контейнер без клизм и слабительных. За 2 недели отменить антибиотики (по согласованию с врачом).', 572);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('dnk-yersinia-enterocolitica', 'ПЦР на иерсинию (Yersinia enterocolitica, иерсиния, ДНК иерсинии, иерсиниоз), качественный', 'ПЦР-диагностика', 'Желудочно кишечные инфекции', 'Определение ДНК Yersinia enterocolitica методом ПЦР для диагностики кишечного иерсиниоза.', 'Свежий кал в чистый контейнер без клизм и слабительных. За 2 недели отменить антибиотики (по согласованию с врачом).', 573);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('adenovirus-i-enterovirus', 'ПЦР на аденовирус и энтеровирус (аденовирус, энтеровирус, ДНК/РНК вирусов, кишечная вирусная инфекция, ОКИ), качественный', 'ПЦР-диагностика', 'Желудочно кишечные инфекции', 'Определение аденовируса и энтеровируса методом ПЦР для диагностики кишечной вирусной инфекции.', 'Свежий кал в чистый контейнер, желательно собрать в острый период болезни. Без клизм и слабительных.', 574);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('dnk-giardia-lamblia', 'ПЦР на лямблии (Giardia lamblia, лямблия, ДНК лямблий, лямблиоз, жиардиаз), качественный', 'ПЦР-диагностика', 'Желудочно кишечные инфекции', 'Определение ДНК лямблий методом ПЦР для диагностики лямблиоза.', 'Свежий кал в чистый контейнер без клизм и слабительных. За 3 дня отменить сорбенты и противопаразитарные препараты (по согласованию с врачом).', 575);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('dnk-entamoeba-histolytica', 'ПЦР на дизентерийную амёбу (Entamoeba histolytica, амёба, ДНК амёбы, амёбиаз, амёбная дизентерия), качественный', 'ПЦР-диагностика', 'Желудочно кишечные инфекции', 'Определение ДНК Entamoeba histolytica методом ПЦР для диагностики амёбиаза.', 'Свежий кал в чистый контейнер без клизм и слабительных. За 3 дня отменить сорбенты и противопаразитарные препараты (по согласованию с врачом).', 576);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('dnk-helicobacter-pylori-s-opredeleniem-ustoychivosti-k-klari', 'ПЦР на хеликобактер с устойчивостью к кларитромицину (Helicobacter pylori, H. pylori, ДНК хеликобактера, резистентность к кларитромицину, мутации устойчивости), качественный', 'ПЦР-диагностика', 'Желудочно кишечные инфекции', 'Определение ДНК Helicobacter pylori и мутаций устойчивости к кларитромицину методом ПЦР для подбора терапии.', 'Кал в чистый контейнер (или биоптат по назначению). За 2 недели отменить антибиотики и препараты висмута, за 7 дней — ингибиторы протонной помпы (по согласованию с врачом).', 577);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('dnk-papillomavirusov-16-18-tipov-s-opredeleniem-tipa', 'ПЦР на ВПЧ 16 и 18 типов с типированием (Human Papillomavirus, HPV, ВПЧ, папилломавирус, вирус папилломы человека, высокий онкогенный риск, ВКР, определение типа), качественный', 'ПЦР-диагностика', 'VPCH и папилломавирус', 'Определение ДНК ВПЧ 16 и 18 типов высокого онкогенного риска с указанием типа для оценки риска рака шейки матки.', 'Соскоб урогенитальный: за 2 недели отменить антибиотики и противовирусные, за 3 часа не мочиться. Женщинам — не сдавать во время менструации; накануне исключить спринцевания, свечи и половой контакт.', 578);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('dnk-papillomavirusov-16-18-tipov-s-opredeleniem-tipa-koliche', 'ПЦР на ВПЧ 16 и 18 типов с типированием, количественно (Human Papillomavirus, HPV, ВПЧ, папилломавирус, высокий онкогенный риск, ВКР, вирусная нагрузка, определение типа), количественный', 'ПЦР-диагностика', 'VPCH и папилломавирус', 'Количественное определение ДНК ВПЧ 16 и 18 типов с типированием для оценки риска и контроля течения инфекции.', 'Соскоб урогенитальный: за 2 недели отменить антибиотики и противовирусные, за 3 часа не мочиться. Женщинам — не сдавать во время менструации; накануне исключить спринцевания, свечи и половой контакт.', 579);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('dnk-papillomavirusov-6-11-tipov-s-opredeleniem-tipa', 'ПЦР на ВПЧ 6 и 11 типов с типированием (Human Papillomavirus, HPV, ВПЧ, папилломавирус, низкий онкогенный риск, ВОР, кондиломы, определение типа), качественный', 'ПЦР-диагностика', 'VPCH и папилломавирус', 'Определение ДНК ВПЧ 6 и 11 типов низкого онкогенного риска с указанием типа; связаны с аногенитальными кондиломами.', 'Соскоб урогенитальный: за 2 недели отменить антибиотики и противовирусные, за 3 часа не мочиться. Женщинам — не сдавать во время менструации; накануне исключить спринцевания, свечи и половой контакт.', 580);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('dnk-papillomavirusov-6-11-tipov-s-opredeleniem-tipa-koliches', 'ПЦР на ВПЧ 6 и 11 типов с типированием, количественно (Human Papillomavirus, HPV, ВПЧ, папилломавирус, низкий онкогенный риск, ВОР, кондиломы, вирусная нагрузка, определение типа), количественный', 'ПЦР-диагностика', 'VPCH и папилломавирус', 'Количественное определение ДНК ВПЧ 6 и 11 типов с типированием для оценки инфекции и контроля лечения.', 'Соскоб урогенитальный: за 2 недели отменить антибиотики и противовирусные, за 3 часа не мочиться. Женщинам — не сдавать во время менструации; накануне исключить спринцевания, свечи и половой контакт.', 581);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('dnk-papillomavirusov-16-18-31-33-35-39-45-51-52-56-58-59-66', 'ПЦР на ВПЧ 14 типов высокого риска, суммарно, количественно (Human Papillomavirus, HPV, ВПЧ, папилломавирус, высокий онкогенный риск, ВКР, 16/18/31/33/35/39/45/51/52/56/58/59/66/68, суммарная вирусная нагрузка), количественный', 'ПЦР-диагностика', 'VPCH и папилломавирус', 'Количественное определение суммарной ДНК 14 типов ВПЧ высокого онкогенного риска для оценки риска рака шейки матки.', 'Соскоб урогенитальный: за 2 недели отменить антибиотики и противовирусные, за 3 часа не мочиться. Женщинам — не сдавать во время менструации; накануне исключить спринцевания, свечи и половой контакт.', 582);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('dnk-papillomavirusov-vkr-16-18-31-33-35-39-45-51-52-56-58-59', 'ПЦР-скрининг ВПЧ 14 типов высокого риска (Human Papillomavirus, HPV, ВПЧ, папилломавирус, высокий онкогенный риск, ВКР, скрининг, 16/18/31/33/35/39/45/51/52/56/58/59/66/68), качественный', 'ПЦР-диагностика', 'VPCH и папилломавирус', 'Скрининговое определение ДНК 14 типов ВПЧ высокого онкогенного риска для оценки риска предраковых изменений шейки матки.', 'Соскоб урогенитальный: за 2 недели отменить антибиотики и противовирусные, за 3 часа не мочиться. Женщинам — не сдавать во время менструации; накануне исключить спринцевания, свечи и половой контакт.', 583);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('dnk-vpch-rasshirennoe-genotipirovanie', 'ПЦР на ВПЧ, расширенное генотипирование 21 типа (Human Papillomavirus, HPV, ВПЧ, папилломавирус, генотипирование, 21 тип, высокий и низкий онкогенный риск, ВКР и ВОР), качественный', 'ПЦР-диагностика', 'VPCH и папилломавирус', 'Определение и типирование ДНК 21 типа ВПЧ высокого и низкого риска для детальной оценки папилломавирусной инфекции.', 'Соскоб урогенитальный: за 2 недели отменить антибиотики и противовирусные, за 3 часа не мочиться. Женщинам — не сдавать во время менструации; накануне исключить спринцевания, свечи и половой контакт.', 584);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('androflor-skrin', 'Андрофлор-скрин (Androflor Screen, скрининг биоценоза урогенитального тракта у мужчин, мужская микрофлора, условно-патогенная флора, ДНК, количественный)', 'ПЦР-диагностика', 'пцр скрининг и панели', 'Скрининговая количественная оценка микрофлоры урогенитального тракта у мужчин методом ПЦР.', 'Соскоб из уретры: за 2 недели отменить антибиотики, за 3 часа не мочиться. Накануне исключить половой контакт.', 585);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('femoflor-skrin', 'Фемофлор-скрин (Femoflor Screen, скрининг биоценоза урогенитального тракта у женщин, микрофлора влагалища, условно-патогенная флора, ДНК, количественный)', 'ПЦР-диагностика', 'пцр скрининг и панели', 'Скрининговая количественная оценка микрофлоры урогенитального тракта у женщин методом ПЦР.', 'Соскоб: за 2 недели отменить антибиотики и пробиотики, за 3 часа не мочиться. Не сдавать во время менструации; накануне исключить спринцевания, свечи и половой контакт.', 586);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('vyyavlenie-uslovno-patogennyh-mikroorganizmov-i-genov-rezist', 'ПЦР на условно-патогенную флору с генами резистентности к гликопептидам и бета-лактамам (условно-патогенные микроорганизмы, гены антибиотикорезистентности, устойчивость к антибиотикам, real-time ПЦР, ДНК), количественный', 'ПЦР-диагностика', 'пцр скрининг и панели', 'Определение условно-патогенных микроорганизмов и генов устойчивости к гликопептидным и бета-лактамным антибиотикам методом ПЦР.', 'Биоматериал по назначению врача (соскоб, мазок и др.). За 2 недели отменить антибиотики (по согласованию с врачом); соскоб — за 3 часа не мочиться.', 587);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('dnk-mikobakteriy-tuberkuleza-ptsr', 'ПЦР на микобактерии туберкулёза (Mycobacterium tuberculosis complex, МБТ, MTB, ДНК микобактерий, туберкулёз, палочка Коха), качественный', 'ПЦР-диагностика', 'туберкулёз', 'Определение ДНК микобактерий туберкулёза методом ПЦР для быстрой диагностики туберкулёза.', 'Утренняя мокрота при откашливании в стерильный контейнер (или другой материал по локализации). Перед сбором почистить зубы и прополоскать рот водой.', 588);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('dnk-mbt-s-opredeleniem-ustoychivosti-k-rifampitsinu', 'ПЦР на МБТ с устойчивостью к рифампицину, GeneXpert MTB/RIF (Mycobacterium tuberculosis, МБТ, MTB, GeneXpert, Xpert MTB/RIF, ДНК микобактерий, устойчивость к рифампицину, туберкулёз), качественный', 'ПЦР-диагностика', 'туберкулёз', 'Определение ДНК микобактерий туберкулёза и устойчивости к рифампицину методом GeneXpert для быстрой диагностики и выявления МЛУ-ТБ.', 'Утренняя мокрота при откашливании в стерильный контейнер (или другой материал по локализации). Перед сбором почистить зубы и прополоскать рот водой.', 589);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('dnk-mbt-s-opredeleniem-ustoychivosti-k-izoniazidu-i-rifampit', 'ПЦР на МБТ с устойчивостью к изониазиду и рифампицину (Mycobacterium tuberculosis, МБТ, MTB, ДНК микобактерий, устойчивость к изониазиду и рифампицину, МЛУ-ТБ, туберкулёз), качественный', 'ПЦР-диагностика', 'туберкулёз', 'Определение ДНК микобактерий туберкулёза и устойчивости к изониазиду и рифампицину методом ПЦР для выявления МЛУ-туберкулёза.', 'Утренняя мокрота при откашливании в стерильный контейнер (или другой материал по локализации). Перед сбором почистить зубы и прополоскать рот водой.', 590);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('ag-s-virusa-gepatita-b', 'HBsAg, поверхностный антиген вируса гепатита B (АГ, HBsAg, hepatitis B surface antigen, австралийский антиген, поверхностный антиген, гепатит В), качественный', 'Серология и инфекции', 'Вирусные гепатиты', 'Выявление поверхностного антигена вируса гепатита B — основного маркёра инфекции и носительства.', 'Утром натощак или через 3 ч после лёгкого приёма пищи; можно пить воду. Накануне исключить алкоголь и жирную пищу.', 591);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('ag-e-virusa-gepatita-v', 'HBeAg, антиген «e» вируса гепатита B (АГ, HBeAg, hepatitis B e antigen, антиген инфекционности, гепатит В), качественный', 'Серология и инфекции', 'Вирусные гепатиты', 'Выявление антигена «e» вируса гепатита B — маркёра активной репликации и высокой заразности.', 'Утром натощак или через 3 ч после лёгкого приёма пищи; можно пить воду. Накануне исключить алкоголь и жирную пищу.', 592);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('at-k-hbe-antigenu-virusa-gepatita-b', 'Anti-HBe, антитела к «e»-антигену вируса гепатита B (АТ, anti-HBe, antibody to hepatitis B e antigen, антитела к HBeAg, гепатит В), качественный', 'Серология и инфекции', 'Вирусные гепатиты', 'Выявление антител к «e»-антигену вируса гепатита B — маркёра снижения репликации вируса.', 'Утром натощак или через 3 ч после лёгкого приёма пищи; можно пить воду. Накануне исключить алкоголь и жирную пищу.', 593);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('at-k-yadernomu-ag-virusa-gepatita-v', 'Anti-HBcore суммарные, антитела к ядерному антигену вируса гепатита B (АТ, anti-HBc total, antibody to hepatitis B core antigen, суммарные антитела, IgG и IgM, гепатит В), качественный', 'Серология и инфекции', 'Вирусные гепатиты', 'Выявление суммарных антител к ядерному антигену вируса гепатита B — маркёра текущей или перенесённой инфекции.', 'Утром натощак или через 3 ч после лёгкого приёма пищи; можно пить воду. Накануне исключить алкоголь и жирную пищу.', 594);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('at-k-yadernomu-ag-virusa-gepatita-v-igm', 'Anti-HBcore IgM, антитела к ядерному антигену вируса гепатита B (АТ, anti-HBc IgM, antibody to hepatitis B core antigen IgM, острый гепатит В), качественный', 'Серология и инфекции', 'Вирусные гепатиты', 'Выявление антител класса IgM к ядерному антигену вируса гепатита B — маркёра острой инфекции.', 'Утром натощак или через 3 ч после лёгкого приёма пищи; можно пить воду. Накануне исключить алкоголь и жирную пищу.', 595);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('at-k-antigenu-s-virusa-gepatita-v', 'Anti-HBsAg, антитела к поверхностному антигену вируса гепатита B (АТ, anti-HBs, antibody to hepatitis B surface antigen, защитные антитела, поствакцинальный иммунитет, гепатит В), качественный', 'Серология и инфекции', 'Вирусные гепатиты', 'Выявление антител к поверхностному антигену вируса гепатита B — маркёра иммунитета после болезни или вакцинации.', 'Утром натощак или через 3 ч после лёгкого приёма пищи; можно пить воду. Накануне исключить алкоголь и жирную пищу.', 596);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('at-k-virusu-gepatita-a-igg', 'Anti-HAV IgG, антитела к вирусу гепатита A, экспресс (АТ, anti-HAV IgG, hepatitis A virus antibody IgG, иммунитет к гепатиту А, гепатит А), качественный', 'Серология и инфекции', 'Вирусные гепатиты', 'Выявление антител класса IgG к вирусу гепатита A — маркёра перенесённой инфекции или поствакцинального иммунитета.', 'Утром натощак или через 3 ч после лёгкого приёма пищи; можно пить воду. Накануне исключить алкоголь и жирную пищу.', 597);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('at-k-virusu-gepatita-d-summarno', 'Anti-HDV суммарные, антитела к вирусу гепатита D (АТ, anti-HDV total, hepatitis D virus antibody, дельта-гепатит, гепатит D), качественный', 'Серология и инфекции', 'Вирусные гепатиты', 'Выявление суммарных антител к вирусу гепатита D для диагностики дельта-инфекции у носителей гепатита B.', 'Утром натощак или через 3 ч после лёгкого приёма пищи; можно пить воду. Накануне исключить алкоголь и жирную пищу.', 598);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('at-k-virusu-gepatita-a-igm', 'Anti-HAV IgM, антитела к вирусу гепатита A, экспресс (АТ, anti-HAV IgM, hepatitis A virus antibody IgM, острый гепатит А), качественный', 'Серология и инфекции', 'Вирусные гепатиты', 'Выявление антител класса IgM к вирусу гепатита A — маркёра острой инфекции.', 'Утром натощак или через 3 ч после лёгкого приёма пищи; можно пить воду. Накануне исключить алкоголь и жирную пищу.', 599);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('at-k-virusu-gepatita-e-igg', 'Anti-HEV IgG, антитела к вирусу гепатита E (АТ, anti-HEV IgG, hepatitis E virus antibody IgG, гепатит Е), качественный', 'Серология и инфекции', 'Вирусные гепатиты', 'Выявление антител класса IgG к вирусу гепатита E — маркёра перенесённой инфекции.', 'Утром натощак или через 3 ч после лёгкого приёма пищи; можно пить воду. Накануне исключить алкоголь и жирную пищу.', 600);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('at-k-virusu-gepatita-e-igm', 'Anti-HEV IgM, антитела к вирусу гепатита E (АТ, anti-HEV IgM, hepatitis E virus antibody IgM, острый гепатит Е), качественный', 'Серология и инфекции', 'Вирусные гепатиты', 'Выявление антител класса IgM к вирусу гепатита E — маркёра острой инфекции.', 'Утром натощак или через 3 ч после лёгкого приёма пищи; можно пить воду. Накануне исключить алкоголь и жирную пищу.', 601);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('at-k-virusu-gepatita-s', 'Anti-HCV суммарные, антитела к вирусу гепатита C (АТ, anti-HCV total, hepatitis C virus antibody, антитела к гепатиту С, гепатит С), качественный', 'Серология и инфекции', 'Вирусные гепатиты', 'Выявление суммарных антител к вирусу гепатита C — основного скринингового маркёра инфекции.', 'Утром натощак или через 3 ч после лёгкого приёма пищи; можно пить воду. Накануне исключить алкоголь и жирную пищу.', 602);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('at-k-virusu-gepatita-a-summarno', 'Anti-HAV суммарные, антитела к вирусу гепатита A (АТ, anti-HAV total, hepatitis A virus antibody, IgG и IgM, гепатит А), качественный', 'Серология и инфекции', 'Вирусные гепатиты', 'Выявление суммарных антител к вирусу гепатита A для оценки текущей или перенесённой инфекции и иммунитета.', 'Утром натощак или через 3 ч после лёгкого приёма пищи; можно пить воду. Накануне исключить алкоголь и жирную пищу.', 603);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('at-k-antigenu-s-virusa-gepatita-b-kolichestvenno', 'Anti-HBs, антитела к поверхностному антигену вируса гепатита B, количественно (АТ, anti-HBs quantitative, antibody to hepatitis B surface antigen, титр защитных антител, поствакцинальный иммунитет, гепатит В), количественный', 'Серология и инфекции', 'Вирусные гепатиты', 'Количественное определение антител к поверхностному антигену вируса гепатита B для оценки напряжённости иммунитета после вакцинации.', 'Утром натощак или через 3 ч после лёгкого приёма пищи; можно пить воду. Накануне исключить алкоголь и жирную пищу.', 604);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('ag-s-virusa-gepatita-b-kolichestvenno-ultrachuvstvitelnyy', 'HBsAg, поверхностный антиген вируса гепатита B, количественно, ультрачувствительный (АГ, HBsAg quantitative, hepatitis B surface antigen, ультрачувствительный, подтверждающий, гепатит В), количественный', 'Серология и инфекции', 'Вирусные гепатиты', 'Ультрачувствительное количественное выявление поверхностного антигена вируса гепатита B для диагностики и мониторинга инфекции.', 'Утром натощак или через 3 ч после лёгкого приёма пищи; можно пить воду. Накануне исключить алкоголь и жирную пищу.', 605);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('ag-e-virusa-gepatita-b-ultrachuvstvitelnyy', 'HBeAg, антиген «e» вируса гепатита B, ультрачувствительный (АГ, HBeAg, hepatitis B e antigen, ультрачувствительный, гепатит В), качественный', 'Серология и инфекции', 'Вирусные гепатиты', 'Ультрачувствительное выявление антигена «e» вируса гепатита B — маркёра активной репликации вируса.', 'Утром натощак или через 3 ч после лёгкого приёма пищи; можно пить воду. Накануне исключить алкоголь и жирную пищу.', 606);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('at-k-yadernomu-ag-virusa-gepatita-b-ultrachuvstvitelnyy', 'Anti-HBcore, антитела к ядерному антигену вируса гепатита B, ультрачувствительный (АТ, anti-HBc, antibody to hepatitis B core antigen, ультрачувствительный, гепатит В), качественный', 'Серология и инфекции', 'Вирусные гепатиты', 'Ультрачувствительное выявление антител к ядерному антигену вируса гепатита B — маркёра контакта с вирусом.', 'Утром натощак или через 3 ч после лёгкого приёма пищи; можно пить воду. Накануне исключить алкоголь и жирную пищу.', 607);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('at-k-virusu-gepatita-c-kolichestvenno-ultrachuvstvitelnyy', 'Anti-HCV, антитела к вирусу гепатита C, количественно, ультрачувствительный (АТ, anti-HCV quantitative, hepatitis C virus antibody, ультрачувствительный, титр антител, гепатит С), количественный', 'Серология и инфекции', 'Вирусные гепатиты', 'Ультрачувствительное количественное определение антител к вирусу гепатита C для диагностики и мониторинга инфекции.', 'Утром натощак или через 3 ч после лёгкого приёма пищи; можно пить воду. Накануне исключить алкоголь и жирную пищу.', 608);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('sifilis', 'Сифилис RPR (RPR, реакция быстрых плазменных реагинов, нетрепонемный тест, антикардиолипиновый тест, сифилис), качественный', 'Серология и инфекции', 'ИППП', 'Нетрепонемный скрининговый тест на сифилис для выявления инфекции и контроля эффективности лечения.', 'Утром натощак или через 3 ч после лёгкого приёма пищи; можно пить воду. Накануне исключить алкоголь и жирную пищу.', 609);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('at-k-vozbuditelyu-sifilisa-summarno', 'Антитела к возбудителю сифилиса суммарно (АТ, Treponema pallidum, трепонема, anti-Treponema pallidum total, суммарные антитела, IgG и IgM, трепонемный тест, сифилис), качественный', 'Серология и инфекции', 'ИППП', 'Трепонемный тест на суммарные антитела к бледной трепонеме для диагностики сифилиса, в том числе перенесённого.', 'Утром натощак или через 3 ч после лёгкого приёма пищи; можно пить воду. Накануне исключить алкоголь и жирную пищу.', 610);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('at-k-virusu-immunodefitsita-cheloveka', 'Антитела к ВИЧ 1/2, экспресс (АТ, HIV 1/2, ВИЧ, вирус иммунодефицита человека, anti-HIV, скрининг ВИЧ, экспресс-тест), качественный', 'Серология и инфекции', 'ИППП', 'Скрининговое выявление антител к ВИЧ 1 и 2 типов; положительный результат требует подтверждающего теста.', 'Утром натощак или через 3 ч после лёгкого приёма пищи; можно пить воду. Накануне исключить алкоголь и жирную пищу.', 611);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('at-k-hlamidii-igm', 'Антитела к хламидии IgM (АТ, Chlamydia trachomatis, хламидия, anti-Chlamydia IgM, антитела IgM, хламидиоз), качественный', 'Серология и инфекции', 'ИППП', 'Выявление антител класса IgM к хламидии — маркёра острой или недавней хламидийной инфекции.', 'Утром натощак или через 3 ч после лёгкого приёма пищи; можно пить воду. Накануне исключить алкоголь и жирную пищу.', 612);
