INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('at-k-mikoplazme-igg', 'Антитела к микоплазме хоминис IgG (АТ, Mycoplasma hominis, микоплазма, anti-Mycoplasma IgG, антитела IgG, микоплазмоз), качественный', 'Серология и инфекции', 'ИППП', 'Выявление антител класса IgG к Mycoplasma hominis — маркёра текущей или перенесённой инфекции.', 'Утром натощак или через 3 ч после лёгкого приёма пищи; можно пить воду. Накануне исключить алкоголь и жирную пищу.', 614);
