INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('at-k-trihomonade-igg', 'Антитела к трихомонаде IgG (АТ, Trichomonas vaginalis, трихомонада, anti-Trichomonas IgG, антитела IgG, трихомониаз), качественный', 'Серология и инфекции', 'ИППП', 'Выявление антител класса IgG к трихомонаде — вспомогательный маркёр текущей или перенесённой инфекции.', 'Утром натощак или через 3 ч после лёгкого приёма пищи; можно пить воду. Накануне исключить алкоголь и жирную пищу.', 618);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('vich-1-2-antigen-p24-i-antitela', 'ВИЧ 1/2, антиген p24 и антитела, 4-е поколение (АГ/АТ, HIV 1/2 Ag/Ab combo, ВИЧ, антиген p24, антитела к ВИЧ, комбо-тест 4 поколения, скрининг ВИЧ), качественный', 'Серология и инфекции', 'ИППП', 'Комбинированное выявление антигена p24 и антител к ВИЧ 1/2 для раннего скрининга; положительный результат требует подтверждения.', 'Утром натощак или через 3 ч после лёгкого приёма пищи; можно пить воду. Накануне исключить алкоголь и жирную пищу.', 619);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('immunoblot-vich', 'Иммуноблот ВИЧ, подтверждающий тест (HIV immunoblot, Western blot, ВИЧ, подтверждающий тест, антитела к ВИЧ), качественный', 'Серология и инфекции', 'ИППП', 'Подтверждающий тест на антитела к ВИЧ методом иммуноблота при положительном или сомнительном скрининге.', 'Утром натощак или через 3 ч после лёгкого приёма пищи; можно пить воду. Накануне исключить алкоголь и жирную пищу.', 620);
