INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('at-k-treponema-pallidum-igg', 'Антитела к Treponema pallidum IgG (АТ, Treponema pallidum, трепонема, anti-Treponema IgG, антитела IgG, сифилис), качественный', 'Серология и инфекции', 'ИППП', 'Выявление антител класса IgG к бледной трепонеме — маркёра текущего или перенесённого сифилиса.', 'Утром натощак или через 3 ч после лёгкого приёма пищи; можно пить воду. Накануне исключить алкоголь и жирную пищу.', 623);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('at-k-hlamidii-iga', 'Антитела к хламидии IgA (АТ, Chlamydia trachomatis, хламидия, anti-Chlamydia IgA, антитела IgA, хламидиоз), качественный', 'Серология и инфекции', 'ИППП', 'Выявление антител класса IgA к хламидии — маркёра активности и течения хламидийной инфекции.', 'Утром натощак или через 3 ч после лёгкого приёма пищи; можно пить воду. Накануне исключить алкоголь и жирную пищу.', 624);
