INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('at-k-kandide-igg', 'Антитела к кандиде IgG (АТ, Candida albicans, кандида, anti-Candida IgG, антитела IgG, кандидоз), качественный', 'Серология и инфекции', 'Прочие бактериальные и грибковые', 'Выявление IgG к Candida albicans — маркёра текущей или перенесённой кандидозной инфекции.', 'Утром натощак или через 3 ч после лёгкого приёма пищи; можно пить воду. Накануне исключить алкоголь и жирную пищу.', 653);
