INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('at-k-virusu-kori-igg', 'Антитела к вирусу кори IgG, количественно (АТ, Morbilli, measles, корь, anti-Measles IgG, антитела IgG, иммунитет к кори, титр), количественный', 'Серология и инфекции', 'Прочие бактериальные и грибковые', 'Количественное определение IgG к вирусу кори для оценки иммунитета после болезни или вакцинации.', 'Утром натощак или через 3 ч после лёгкого приёма пищи; можно пить воду. Накануне исключить алкоголь и жирную пищу.', 655);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('at-k-virusu-vetryanoy-ospy-igg', 'Антитела к вирусу ветряной оспы IgG (АТ, Varicella zoster, ВВЗ, VZV, anti-VZV IgG, антитела IgG, ветряная оспа, опоясывающий лишай, иммунитет), качественный', 'Серология и инфекции', 'Прочие бактериальные и грибковые', 'Выявление IgG к вирусу Varicella zoster — маркёра перенесённой инфекции или поствакцинального иммунитета.', 'Утром натощак или через 3 ч после лёгкого приёма пищи; можно пить воду. Накануне исключить алкоголь и жирную пищу.', 656);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('at-k-virusu-vetryanoy-ospy-igm', 'Антитела к вирусу ветряной оспы IgM (АТ, Varicella zoster, ВВЗ, VZV, anti-VZV IgM, антитела IgM, острая ветряная оспа), качественный', 'Серология и инфекции', 'Прочие бактериальные и грибковые', 'Выявление IgM к вирусу Varicella zoster — маркёра острой или недавней инфекции.', 'Утром натощак или через 3 ч после лёгкого приёма пищи; можно пить воду. Накануне исключить алкоголь и жирную пищу.', 657);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('at-k-virusu-parotita-igg', 'Антитела к вирусу паротита IgG (АТ, Mumps, паротит, свинка, anti-Mumps IgG, антитела IgG, иммунитет к паротиту), качественный', 'Серология и инфекции', 'Прочие бактериальные и грибковые', 'Выявление IgG к вирусу паротита — маркёра перенесённой инфекции или поствакцинального иммунитета.', 'Утром натощак или через 3 ч после лёгкого приёма пищи; можно пить воду. Накануне исключить алкоголь и жирную пищу.', 658);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('at-k-virusu-kori-igm', 'Антитела к вирусу кори IgM (АТ, Morbilli, measles, корь, anti-Measles IgM, антитела IgM, острая корь), качественный', 'Серология и инфекции', 'Прочие бактериальные и грибковые', 'Выявление IgM к вирусу кори — маркёра острой или недавней инфекции.', 'Утром натощак или через 3 ч после лёгкого приёма пищи; можно пить воду. Накануне исключить алкоголь и жирную пищу.', 659);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('at-k-leptospiram-summarno', 'Антитела к лептоспирам суммарно (АТ, Leptospira, лептоспира, anti-Leptospira, суммарные антитела, IgG и IgM, лептоспироз), качественный', 'Серология и инфекции', 'Прочие бактериальные и грибковые', 'Выявление суммарных антител к лептоспирам для диагностики лептоспироза.', 'Утром натощак или через 3 ч после лёгкого приёма пищи; можно пить воду. Накануне исключить алкоголь и жирную пищу.', 660);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('at-k-difteriynomu-anatoksinu', 'Антитела к дифтерийному анатоксину, защитный титр (АТ, Corynebacterium diphtheriae, дифтерия, anti-diphtheria, антитоксические антитела, защитный титр, поствакцинальный иммунитет), количественный', 'Серология и инфекции', 'Прочие бактериальные и грибковые', 'Определение антител к дифтерийному анатоксину для оценки напряжённости противодифтерийного иммунитета.', 'Утром натощак или через 3 ч после лёгкого приёма пищи; можно пить воду. Накануне исключить алкоголь и жирную пищу.', 661);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('at-k-stolbnyachnomu-anatoksinu', 'Антитела к столбнячному анатоксину, защитный титр (АТ, Clostridium tetani, столбняк, anti-tetanus, антитоксические антитела, защитный титр, поствакцинальный иммунитет), количественный', 'Серология и инфекции', 'Прочие бактериальные и грибковые', 'Определение антител к столбнячному анатоксину для оценки напряжённости противостолбнячного иммунитета.', 'Утром натощак или через 3 ч после лёгкого приёма пищи; можно пить воду. Накануне исключить алкоголь и жирную пищу.', 662);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('at-k-yersinia-enterocolitica', 'Антитела к Yersinia enterocolitica (АТ, Yersinia enterocolitica, иерсиния, anti-Yersinia, антитела, иерсиниоз), качественный', 'Серология и инфекции', 'Прочие бактериальные и грибковые', 'Выявление антител к Yersinia enterocolitica для диагностики кишечного иерсиниоза и его осложнений.', 'Утром натощак или через 3 ч после лёгкого приёма пищи; можно пить воду. Накануне исключить алкоголь и жирную пищу.', 663);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('rpga-s-salmonelleznym-diagnostikumom', 'РПГА с сальмонеллёзным диагностикумом (РПГА, реакция пассивной гемагглютинации, Salmonella, сальмонелла, антитела к сальмонеллам, сальмонеллёз), качественный', 'Серология и инфекции', 'Прочие бактериальные и грибковые', 'Определение антител к сальмонеллам методом пассивной гемагглютинации для диагностики сальмонеллёза.', 'Утром натощак или через 3 ч после лёгкого приёма пищи; можно пить воду. Накануне исключить алкоголь и жирную пищу.', 664);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('galaktomannan', 'Галактоманнан, аспергиллёз (АГ, galactomannan, галактоманнановый антиген, Aspergillus, аспергилла, антиген аспергилл, инвазивный аспергиллёз), качественный', 'Серология и инфекции', 'Прочие бактериальные и грибковые', 'Выявление галактоманнанового антигена Aspergillus для диагностики инвазивного аспергиллёза, в том числе при иммунодефиците.', 'Утром натощак или через 3 ч после лёгкого приёма пищи; можно пить воду. Материал (кровь или лаваж) — по назначению врача.', 665);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('kriptokokkovyy-antigen', 'Криптококковый антиген (АГ, cryptococcal antigen, CrAg, Cryptococcus neoformans, криптококк, антиген криптококка, криптококкоз), качественный', 'Серология и инфекции', 'Прочие бактериальные и грибковые', 'Выявление антигена Cryptococcus для диагностики криптококкоза и криптококкового менингита, в том числе при иммунодефиците.', 'Утром натощак или через 3 ч после лёгкого приёма пищи; можно пить воду. Материал (кровь или ликвор) — по назначению врача.', 666);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('at-k-kapsidnomu-ag-virusa-epshteyna-barr-igg', 'Антитела к капсидному антигену ВЭБ IgG (АТ, Epstein-Barr virus, ВЭБ, EBV VCA IgG, anti-VCA IgG, капсидный антиген, антитела IgG, инфекционный мононуклеоз), качественный', 'Серология и инфекции', 'Вирус Эпштейна бар / мононуклеоз', 'Выявление IgG к капсидному антигену вируса Эпштейна-Барр — маркёра текущей или перенесённой ВЭБ-инфекции.', 'Утром натощак или через 3 ч после лёгкого приёма пищи; можно пить воду. Накануне исключить алкоголь и жирную пищу.', 667);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('at-k-kapsidnomu-ag-virusa-epshteyna-barr-igm', 'Антитела к капсидному антигену ВЭБ IgM (АТ, Epstein-Barr virus, ВЭБ, EBV VCA IgM, anti-VCA IgM, капсидный антиген, антитела IgM, острый мононуклеоз), качественный', 'Серология и инфекции', 'Вирус Эпштейна бар / мононуклеоз', 'Выявление IgM к капсидному антигену вируса Эпштейна-Барр — маркёра острой или недавней инфекции.', 'Утром натощак или через 3 ч после лёгкого приёма пищи; можно пить воду. Накануне исключить алкоголь и жирную пищу.', 668);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('at-k-nuklearnomu-ag-virusa-epshteyna-barr-igg', 'Антитела к нуклеарному антигену ВЭБ IgG (АТ, Epstein-Barr virus, ВЭБ, EBV EBNA IgG, anti-EBNA IgG, ядерный антиген, нуклеарный антиген, антитела IgG, перенесённая инфекция), качественный', 'Серология и инфекции', 'Вирус Эпштейна бар / мононуклеоз', 'Выявление IgG к ядерному антигену вируса Эпштейна-Барр — маркёра перенесённой (давней) ВЭБ-инфекции.', 'Утром натощак или через 3 ч после лёгкого приёма пищи; можно пить воду. Накануне исключить алкоголь и жирную пищу.', 669);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('avidnost-at-igg-k-virusu-epshteyna-barr', 'Авидность IgG к вирусу Эпштейна-Барр (АТ, Epstein-Barr virus, ВЭБ, EBV, авидность антител, IgG avidity, давность инфекции, мононуклеоз), качественный', 'Серология и инфекции', 'Вирус Эпштейна бар / мононуклеоз', 'Определение авидности IgG к вирусу Эпштейна-Барр для различения недавней и давней инфекции.', 'Утром натощак или через 3 ч после лёгкого приёма пищи; можно пить воду. Накануне исключить алкоголь и жирную пищу.', 670);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('at-k-rannemu-antigenu-virusa-epshteyna-barr-igg', 'Антитела к раннему антигену ВЭБ IgG (АТ, Epstein-Barr virus, ВЭБ, EBV EA IgG, anti-EA IgG, ранний антиген, антитела IgG, реактивация инфекции), качественный', 'Серология и инфекции', 'Вирус Эпштейна бар / мононуклеоз', 'Выявление IgG к раннему антигену вируса Эпштейна-Барр — маркёра активной или реактивированной ВЭБ-инфекции.', 'Утром натощак или через 3 ч после лёгкого приёма пищи; можно пить воду. Накануне исключить алкоголь и жирную пищу.', 671);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('at-k-ag-askarid-igg', 'Антитела к антигенам аскарид IgG (АТ, Ascaris lumbricoides, аскарида, anti-Ascaris IgG, антитела IgG, аскаридоз), качественный', 'Серология и инфекции', 'паразитарные и гельминтозы', 'Выявление IgG к аскаридам для диагностики аскаридоза.', 'Утром натощак или через 3 ч после лёгкого приёма пищи; можно пить воду. Накануне исключить алкоголь и жирную пищу.', 672);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('at-k-ag-lyambliy-igm', 'Антитела к антигенам лямблий IgM (АТ, Lamblia intestinalis, Giardia, лямблия, anti-Giardia IgM, антитела IgM, острый лямблиоз), качественный', 'Серология и инфекции', 'паразитарные и гельминтозы', 'Выявление IgM к лямблиям — маркёра острого или недавнего лямблиоза.', 'Утром натощак или через 3 ч после лёгкого приёма пищи; можно пить воду. Накануне исключить алкоголь и жирную пищу.', 673);
