INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('at-k-ag-ehinokokka-igg', 'Антитела к антигенам эхинококка IgG (АТ, Echinococcus granulosus, эхинококк, anti-Echinococcus IgG, антитела IgG, эхинококкоз), качественный', 'Серология и инфекции', 'паразитарные и гельминтозы', 'Выявление IgG к эхинококку для диагностики эхинококкоза.', 'Утром натощак или через 3 ч после лёгкого приёма пищи; можно пить воду. Накануне исключить алкоголь и жирную пищу.', 675);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('at-k-gelmintam-igg', 'Антитела к гельминтам IgG, комплекс (АТ, anti-helminth IgG, гельминты, описторх, трихинелла, токсокара, эхинококк, Opisthorchis, Trichinella, Toxocara, Echinococcus, комплексная серология гельминтозов), качественный', 'Серология и инфекции', 'паразитарные и гельминтозы', 'Комплексное выявление IgG к основным гельминтам (описторх, трихинелла, токсокара, эхинококк) для скрининга гельминтозов.', 'Утром натощак или через 3 ч после лёгкого приёма пищи; можно пить воду. Накануне исключить алкоголь и жирную пищу.', 676);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('at-k-toksokare-igg', 'Антитела к токсокаре IgG (АТ, Toxocara canis, токсокара, anti-Toxocara IgG, антитела IgG, токсокароз), качественный', 'Серология и инфекции', 'паразитарные и гельминтозы', 'Выявление IgG к токсокаре для диагностики токсокароза.', 'Утром натощак или через 3 ч после лёгкого приёма пищи; можно пить воду. Накануне исключить алкоголь и жирную пищу.', 677);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('at-k-opistorham-igg', 'Антитела к описторхам IgG (АТ, Opisthorchis felineus, описторх, anti-Opisthorchis IgG, антитела IgG, описторхоз), качественный', 'Серология и инфекции', 'паразитарные и гельминтозы', 'Выявление IgG к описторхам для диагностики описторхоза.', 'Утром натощак или через 3 ч после лёгкого приёма пищи; можно пить воду. Накануне исключить алкоголь и жирную пищу.', 678);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('at-k-trihinellam-igg', 'Антитела к трихинеллам IgG (АТ, Trichinella spiralis, трихинелла, anti-Trichinella IgG, антитела IgG, трихинеллёз), качественный', 'Серология и инфекции', 'паразитарные и гельминтозы', 'Выявление IgG к трихинеллам для диагностики трихинеллёза.', 'Утром натощак или через 3 ч после лёгкого приёма пищи; можно пить воду. Накануне исключить алкоголь и жирную пищу.', 679);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('at-k-tsistitserkam-igg', 'Антитела к цистицеркам IgG (АТ, Cysticercus, Taenia solium, цистицерк, anti-Cysticercus IgG, антитела IgG, цистицеркоз), качественный', 'Серология и инфекции', 'паразитарные и гельминтозы', 'Выявление IgG к цистицеркам для диагностики цистицеркоза.', 'Утром натощак или через 3 ч после лёгкого приёма пищи; можно пить воду. Накануне исключить алкоголь и жирную пищу.', 680);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('at-k-shistosomam-igg', 'Антитела к шистосомам IgG (АТ, Schistosoma, шистосома, anti-Schistosoma IgG, антитела IgG, шистосомоз, бильгарциоз), качественный', 'Серология и инфекции', 'паразитарные и гельминтозы', 'Выявление IgG к шистосомам для диагностики шистосомоза.', 'Утром натощак или через 3 ч после лёгкого приёма пищи; можно пить воду. Накануне исключить алкоголь и жирную пищу.', 681);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('at-k-entamoeba-histolytica-igg', 'Антитела к дизентерийной амёбе IgG (АТ, Entamoeba histolytica, амёба, anti-Entamoeba IgG, антитела IgG, амёбиаз), качественный', 'Серология и инфекции', 'паразитарные и гельминтозы', 'Выявление IgG к Entamoeba histolytica для диагностики амёбиаза.', 'Утром натощак или через 3 ч после лёгкого приёма пищи; можно пить воду. Накануне исключить алкоголь и жирную пищу.', 682);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('at-k-anizakidam-ige', 'Антитела к анизакидам IgE (АТ, Anisakis, анизакида, anti-Anisakis IgE, специфический IgE, анизакидоз, аллергия на рыбу), качественный', 'Серология и инфекции', 'паразитарные и гельминтозы', 'Определение специфических IgE к анизакидам для диагностики анизакидоза и связанных аллергических реакций.', 'Кровь натощак или через 3 ч после лёгкого приёма пищи; можно пить воду. Отмена антигистаминных препаратов перед анализом крови не требуется.', 683);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('at-k-helikobakteru-igm', 'Антитела к хеликобактеру IgM (АТ, Helicobacter pylori, хеликобактер пилори, H. pylori, anti-H. pylori IgM, антитела IgM, острая инфекция), качественный', 'Серология и инфекции', 'ЖКт инф', 'Выявление IgM к Helicobacter pylori — маркёра острой или недавней хеликобактерной инфекции.', 'Утром натощак или через 3 ч после лёгкого приёма пищи; можно пить воду. Накануне исключить алкоголь и жирную пищу.', 684);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('at-k-helikobakteru-igg', 'Антитела к хеликобактеру IgG (АТ, Helicobacter pylori, хеликобактер пилори, H. pylori, anti-H. pylori IgG, антитела IgG, текущая или перенесённая инфекция), качественный', 'Серология и инфекции', 'ЖКт инф', 'Выявление IgG к Helicobacter pylori — маркёра текущей или перенесённой инфекции при гастрите и язвенной болезни.', 'Утром натощак или через 3 ч после лёгкого приёма пищи; можно пить воду. Накануне исключить алкоголь и жирную пищу.', 685);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('at-k-helikobakteru-iga', 'Антитела к хеликобактеру IgA (АТ, Helicobacter pylori, хеликобактер пилори, H. pylori, anti-H. pylori IgA, антитела IgA, активность инфекции), качественный', 'Серология и инфекции', 'ЖКт инф', 'Выявление IgA к Helicobacter pylori — маркёра активности инфекции и местного иммунного ответа слизистой желудка.', 'Утром натощак или через 3 ч после лёгкого приёма пищи; можно пить воду. Накануне исключить алкоголь и жирную пищу.', 686);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('at-k-borreliyam-igg', 'Антитела к боррелиям IgG (АТ, Borrelia burgdorferi, боррелия, anti-Borrelia IgG, антитела IgG, болезнь Лайма, боррелиоз, укус клеща), качественный', 'Серология и инфекции', 'клещевые инфекции', 'Выявление IgG к боррелиям — маркёра текущего или перенесённого боррелиоза (болезни Лайма).', 'Утром натощак или через 3 ч после лёгкого приёма пищи; можно пить воду. Накануне исключить алкоголь и жирную пищу.', 687);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('at-k-borreliyam-igm', 'Антитела к боррелиям IgM (АТ, Borrelia burgdorferi, боррелия, anti-Borrelia IgM, антитела IgM, болезнь Лайма, боррелиоз, укус клеща), качественный', 'Серология и инфекции', 'клещевые инфекции', 'Выявление IgM к боррелиям — маркёра острого или недавнего боррелиоза (болезни Лайма).', 'Утром натощак или через 3 ч после лёгкого приёма пищи; можно пить воду. Накануне исключить алкоголь и жирную пищу.', 688);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('at-k-virusu-kleschevogo-entsefalita-igg', 'Антитела к вирусу клещевого энцефалита IgG (АТ, клещевой энцефалит, КЭ, tick-borne encephalitis, anti-TBE IgG, антитела IgG, иммунитет, укус клеща), качественный', 'Серология и инфекции', 'клещевые инфекции', 'Выявление IgG к вирусу клещевого энцефалита — маркёра перенесённой инфекции или поствакцинального иммунитета.', 'Утром натощак или через 3 ч после лёгкого приёма пищи; можно пить воду. Накануне исключить алкоголь и жирную пищу.', 689);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('at-k-virusu-kleschevogo-entsefalita-igm', 'Антитела к вирусу клещевого энцефалита IgM (АТ, клещевой энцефалит, КЭ, tick-borne encephalitis, anti-TBE IgM, антитела IgM, острая инфекция, укус клеща), качественный', 'Серология и инфекции', 'клещевые инфекции', 'Выявление IgM к вирусу клещевого энцефалита — маркёра острой или недавней инфекции после укуса клеща.', 'Утром натощак или через 3 ч после лёгкого приёма пищи; можно пить воду. Накануне исключить алкоголь и жирную пищу.', 690);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('posev-kala-na-vozbuditeley-kishechnoy-infektsii-s-opredeleni', 'Посев кала на возбудителей кишечных инфекций (бакпосев кала, Shigella, Salmonella, шигелла, сальмонелла, дизентерия, сальмонеллёз, чувствительность к антибиотикам, антибиотикограмма)', 'Микробиология', 'Бактериология (посевы)', 'Бактериологический посев кала на шигеллы и сальмонеллы с определением чувствительности к антибиотикам для диагностики кишечных инфекций.', 'Свежий кал в стерильный контейнер до начала антибиотиков. Без клизм и слабительных; не сдавать при менструации.', 691);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('posev-kala-na-uslovno-patogennuyu-floru-s-opredeleniem-chuvs', 'Посев кала на условно-патогенную флору (бакпосев кала, УПФ, условно-патогенные микроорганизмы, чувствительность к антибиотикам, антибиотикограмма)', 'Микробиология', 'Бактериология (посевы)', 'Бактериологический посев кала на условно-патогенную флору с определением чувствительности к антибиотикам.', 'Свежий кал в стерильный контейнер до начала антибиотиков. Без клизм и слабительных.', 692);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('posev-krovi-na-sterilnost', 'Посев крови на стерильность (гемокультура, bacteremia, бактериемия, сепсис, стерильность крови, чувствительность к антибиотикам)', 'Микробиология', 'Бактериология (посевы)', 'Бактериологический посев крови для выявления бактериемии и сепсиса с определением возбудителя.', 'Кровь берут до начала антибиотиков, желательно на высоте лихорадки. Забор проводит медработник в стерильные флаконы.', 693);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('posev-na-disbakterioz-s-opredeleniem-chuvstvitelnosti-k-osno', 'Посев на дисбактериоз (бакпосев на дисбактериоз кишечника, дисбиоз, микрофлора кишечника, чувствительность к антибиотикам, антибиотикограмма)', 'Микробиология', 'Бактериология (посевы)', 'Бактериологическое исследование кала на дисбактериоз с оценкой микрофлоры и чувствительности к антибиотикам.', 'Свежий кал в стерильный контейнер до начала антибиотиков и пробиотиков. Без клизм и слабительных.', 694);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('posev-mochi-na-floru-s-opredeleniem-chuvstvitelnosti-k-antib', 'Посев мочи на флору (бакпосев мочи, урокультура, uroculture, бактериурия, инфекция мочевых путей, чувствительность к антибиотикам, антибиотикограмма)', 'Микробиология', 'Бактериология (посевы)', 'Бактериологический посев мочи с определением чувствительности к антибиотикам для диагностики инфекций мочевых путей.', 'Утренняя средняя порция мочи в стерильный контейнер после туалета половых органов, до начала антибиотиков. Женщинам не сдавать при менструации.', 695);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('posev-otdelyaemogo-zeva-i-nosa-s-opredeleniem-chuvstvitelnos', 'Посев отделяемого зева и носа (бакпосев из зева и носа, мазок из зева и носа, микрофлора носоглотки, чувствительность к антибиотикам, антибиотикограмма)', 'Микробиология', 'Бактериология (посевы)', 'Бактериологический посев отделяемого зева и носа с определением чувствительности к антибиотикам.', 'Утром натощак до чистки зубов и полоскания, до начала антибиотиков. Не использовать спреи и капли перед взятием материала.', 696);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('posev-mokroty-s-opredeleniem-chuvstvitelnosti', 'Посев мокроты (бакпосев мокроты, микрофлора мокроты, инфекции дыхательных путей, чувствительность к антибиотикам, антибиотикограмма)', 'Микробиология', 'Бактериология (посевы)', 'Бактериологический посев мокроты с определением чувствительности к антибиотикам для диагностики инфекций дыхательных путей.', 'Утренняя мокрота при откашливании в стерильный контейнер, до начала антибиотиков. Предварительно почистить зубы и прополоскать рот водой.', 697);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('posev-otdelyaemogo-rany-s-opredeleniem-chuvstvitelnosti', 'Посев отделяемого раны (бакпосев из раны, раневое отделяемое, гнойное отделяемое, чувствительность к антибиотикам, антибиотикограмма)', 'Микробиология', 'Бактериология (посевы)', 'Бактериологический посев отделяемого раны с определением чувствительности к антибиотикам для подбора терапии.', 'Материал берут до обработки антисептиками и до начала антибиотиков. Взятие проводит медработник.', 698);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('posev-otdelyaemogo-urogenitalnogo-trakta-s-opredeleniem-chuv', 'Посев отделяемого урогенитального тракта (бакпосев урогенитальный, мазок на флору, микрофлора урогенитального тракта, чувствительность к антибиотикам, антибиотикограмма)', 'Микробиология', 'Бактериология (посевы)', 'Бактериологический посев отделяемого урогенитального тракта с определением чувствительности к антибиотикам.', 'До начала антибиотиков, за 3 часа не мочиться. Женщинам — вне менструации, накануне исключить спринцевания, свечи и половой контакт.', 699);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('posev-grudnogo-moloka', 'Посев грудного молока (бакпосев грудного молока, микрофлора молока, лактационный мастит, стерильность молока, чувствительность к антибиотикам)', 'Микробиология', 'Бактериология (посевы)', 'Бактериологический посев грудного молока для выявления инфекции при мастите и оценки чувствительности к антибиотикам.', 'До начала антибиотиков. Вымыть руки и грудь, обработать сосок; первую порцию молока сцедить, собрать в стерильный контейнер из каждой груди отдельно.', 700);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('mikroskopiya-mazka-okraska-po-gramu', 'Микроскопия мазка с окраской по Граму (окраска по Граму, Gram stain, грамокраска, бактериоскопия, микрофлора мазка)', 'Микробиология', 'Бактериология (посевы)', 'Микроскопия мазка с окраской по Граму для быстрой ориентировочной оценки микрофлоры и характера воспаления.', 'Материал берут до начала антибиотиков. Подготовка зависит от биоматериала (мазок, мокрота, отделяемое) — уточнить в лаборатории.', 701);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('opredelenie-minimalnoy-podavlyayuschey-kontsentratsii-antibi', 'Определение минимальной подавляющей концентрации антибиотиков (МПК, MIC, minimal inhibitory concentration, чувствительность к антибиотикам, антибиотикограмма)', 'Микробиология', 'Бактериология (посевы)', 'Определение минимальной подавляющей концентрации антибиотиков для точного подбора дозы и препарата.', 'Проводится на основе выделенной культуры возбудителя. Материал берут до начала антибиотиков; условия зависят от биоматериала.', 702);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('opredelenie-chuvstvitelnosti-k-bakteriofagam', 'Определение чувствительности к бактериофагам (фаготипирование, чувствительность к фагам, bacteriophage susceptibility, подбор бактериофага)', 'Микробиология', 'Бактериология (посевы)', 'Определение чувствительности выделенного возбудителя к бактериофагам для подбора фаготерапии.', 'Проводится на основе выделенной культуры. Материал берут до начала антибиотиков; условия зависят от биоматериала.', 703);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('posev-otdelyaemogo-glaza-s-opredeleniem-chuvstvitelnosti', 'Посев отделяемого глаза (бакпосев из глаза, отделяемое конъюнктивы, конъюнктивит, микрофлора глаза, чувствительность к антибиотикам, антибиотикограмма)', 'Микробиология', 'Бактериология (посевы)', 'Бактериологический посев отделяемого глаза с определением чувствительности к антибиотикам для диагностики инфекций глаза.', 'До начала антибиотиков и без закапывания капель. Утром не умываться; взятие проводит медработник.', 704);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('posev-otdelyaemogo-uha-s-opredeleniem-chuvstvitelnosti', 'Посев отделяемого уха (бакпосев из уха, отделяемое уха, отит, микрофлора уха, чувствительность к антибиотикам, антибиотикограмма)', 'Микробиология', 'Бактериология (посевы)', 'Бактериологический посев отделяемого уха с определением чувствительности к антибиотикам для диагностики инфекций уха.', 'До начала антибиотиков и без применения ушных капель. Не чистить и не обрабатывать ухо перед взятием материала.', 705);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('posev-zhelchi-s-opredeleniem-chuvstvitelnosti', 'Посев жёлчи (бакпосев жёлчи, желчь, микрофлора жёлчи, инфекции жёлчевыводящих путей, чувствительность к антибиотикам, антибиотикограмма)', 'Микробиология', 'Бактериология (посевы)', 'Бактериологический посев жёлчи с определением чувствительности к антибиотикам для диагностики инфекций жёлчных путей.', 'Жёлчь получают при дуоденальном зондировании, до начала антибиотиков. Процедуру проводит медработник натощак.', 706);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('posev-likvora-s-opredeleniem-chuvstvitelnosti', 'Посев ликвора (бакпосев ликвора, спинномозговая жидкость, СМЖ, менингит, чувствительность к антибиотикам, антибиотикограмма)', 'Микробиология', 'Бактериология (посевы)', 'Бактериологический посев спинномозговой жидкости с определением чувствительности к антибиотикам для диагностики менингита.', 'Ликвор получают при люмбальной пункции, до начала антибиотиков. Процедуру проводит врач в стерильных условиях.', 707);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('posev-na-meningokokk', 'Посев на менингококк (Neisseria meningitidis, менингококк, нейссерия, менингококковая инфекция, носительство, бакпосев)', 'Микробиология', 'Бактериология (посевы)', 'Бактериологический посев на менингококк для диагностики инфекции и выявления носительства.', 'Мазок из носоглотки до начала антибиотиков. Утром натощак, до чистки зубов и полоскания рта.', 708);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('posev-na-difteriynuyu-palochku', 'Посев на дифтерийную палочку (BL, Corynebacterium diphtheriae, коринебактерия, дифтерия, дифтерийная палочка, носительство, бакпосев)', 'Микробиология', 'Бактериология (посевы)', 'Бактериологический посев на возбудителя дифтерии для диагностики инфекции и выявления носительства.', 'Мазок из зева и носа до начала антибиотиков. Утром натощак, до чистки зубов и полоскания рта.', 709);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('posev-na-nositelstvo-zolotistogo-stafilokokka', 'Посев на носительство золотистого стафилококка (Staphylococcus aureus, золотистый стафилококк, стафилококк ауреус, носительство, бакпосев, чувствительность к антибиотикам)', 'Микробиология', 'Бактериология (посевы)', 'Бактериологический посев на золотистый стафилококк для выявления носительства и определения чувствительности к антибиотикам.', 'Мазок из носа и/или зева до начала антибиотиков. Не использовать местные препараты и мази перед взятием материала.', 710);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('posev-na-beta-gemoliticheskiy-streptokokk-gruppy-a', 'Посев на бета-гемолитический стрептококк группы A (Streptococcus pyogenes, БГСА, стрептококк группы А, GAS, ангина, бакпосев, чувствительность к антибиотикам)', 'Микробиология', 'Бактериология (посевы)', 'Бактериологический посев на бета-гемолитический стрептококк группы A для диагностики стрептококковой инфекции (ангины).', 'Мазок из зева до начала антибиотиков. Утром натощак, до чистки зубов и полоскания рта.', 711);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('identifikatsiya-mikroorganizma-metodom-maldi-tof', 'Идентификация микроорганизма методом MALDI-TOF (MALDI-TOF, масс-спектрометрия, идентификация возбудителя, видовая идентификация микроорганизма)', 'Микробиология', 'Бактериология (посевы)', 'Точная видовая идентификация выделенного микроорганизма методом масс-спектрометрии MALDI-TOF.', 'Проводится на основе выделенной культуры возбудителя. Первичный материал берут до начала антибиотиков.', 712);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('posev-na-mikrofloru-i-griby-s-opredeleniem-chuvstvitelnosti', 'Посев на микрофлору и грибы (бакпосев на флору и грибы, микрофлора, грибковая инфекция, микоз, чувствительность к антибиотикам и антимикотикам, антибиотикограмма)', 'Микробиология', 'Микология (грибы)', 'Бактериологический посев на микрофлору и грибы с определением чувствительности к антибиотикам и противогрибковым препаратам.', 'Материал берут до начала антибиотиков и противогрибковых препаратов. Подготовка зависит от биоматериала — уточнить в лаборатории.', 713);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('mikroskopiya-na-patogennye-griby', 'Микроскопия на патогенные грибы, соскоб кожи, ногтей, волос (микроскопия на грибы, KOH-микроскопия, дерматомикоз, онихомикоз, микоз, патогенные грибы)', 'Микробиология', 'Микология (грибы)', 'Микроскопия соскоба кожи, ногтей и волос для выявления грибковой инфекции (микоза, онихомикоза).', 'За 3–5 дней не использовать противогрибковые кремы, лаки и мази; не стричь и не обрабатывать поражённые ногти и кожу перед взятием материала.', 714);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('posev-na-drozhzhepodobnye-griby-candida-s-opredeleniem-chuvs', 'Посев на дрожжеподобные грибы Candida (бакпосев на кандиду, Candida, кандида, кандидоз, молочница, дрожжевые грибы, чувствительность к антимикотикам)', 'Микробиология', 'Микология (грибы)', 'Посев на дрожжеподобные грибы Candida с определением чувствительности к противогрибковым препаратам.', 'Материал берут до начала противогрибковых препаратов и антибиотиков. Подготовка зависит от биоматериала (соскоб, мазок, кал и др.) — уточнить в лаборатории.', 715);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('posev-na-dermatofity', 'Посев на дерматофиты (бакпосев на дерматофиты, Trichophyton, Microsporum, трихофития, микроспория, дерматомикоз, стригущий лишай, чувствительность к антимикотикам)', 'Микробиология', 'Микология (грибы)', 'Посев на дерматофиты (Trichophyton, Microsporum) для диагностики грибковых поражений кожи, волос и ногтей.', 'За 1–2 недели не использовать противогрибковые препараты (местные и системные). Не обрабатывать очаг перед взятием соскоба.', 716);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('posev-na-plesnevye-griby', 'Посев на плесневые грибы (бакпосев на плесень, Aspergillus, аспергилла, плесневые грибы, аспергиллёз, плесневый микоз, чувствительность к антимикотикам)', 'Микробиология', 'Микология (грибы)', 'Посев на плесневые грибы (Aspergillus) для диагностики плесневых микозов и подбора противогрибковой терапии.', 'Материал берут до начала противогрибковых препаратов. Подготовка зависит от биоматериала (мокрота, соскоб, отделяемое) — уточнить в лаборатории.', 717);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('mikroskopiya-krovi-na-malyariynyy-plazmodiy', 'Микроскопия крови на малярийный плазмодий (малярия, Plasmodium, малярийный плазмодий, толстая капля, мазок крови, паразиты крови)', 'Микробиология', 'Паразитология', 'Микроскопия крови для выявления малярийного плазмодия и диагностики малярии.', 'Специальной подготовки не требуется. Кровь желательно брать на высоте лихорадки или озноба; возможны повторные заборы по назначению врача.', 718);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('mikroskopiya-na-leyshmanii', 'Микроскопия на лейшмании (лейшманиоз, Leishmania, лейшмания, микроскопия мазка, паразиты)', 'Микробиология', 'Паразитология', 'Микроскопия биоматериала для выявления лейшманий и диагностики лейшманиоза.', 'Специальной подготовки не требуется. Материал (кровь, костный мозг, отделяемое язвы) берут по назначению врача.', 719);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('mikroskopiya-na-mikrofilyarii', 'Микроскопия на микрофилярии (филяриатоз, микрофилярии, Microfilaria, филярии, микроскопия крови, паразиты крови)', 'Микробиология', 'Паразитология', 'Микроскопия крови для выявления микрофилярий и диагностики филяриатозов.', 'Специальной подготовки не требуется. Время забора крови (часто ночью) определяет врач с учётом периодичности паразита.', 720);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('mikroskopiya-tolstoy-kapli-i-mazka-krovi-na-parazitov', 'Микроскопия толстой капли и мазка крови на паразитов (толстая капля, мазок крови, паразиты крови, малярия, кровепаразиты, микроскопия крови)', 'Микробиология', 'Паразитология', 'Микроскопия толстой капли и мазка крови для выявления малярийных плазмодиев и других кровепаразитов.', 'Специальной подготовки не требуется. Кровь желательно брать на высоте лихорадки; возможны повторные заборы по назначению врача.', 721);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('mikroskopiya-na-kislotoustoychivye-bakterii', 'Микроскопия на кислотоустойчивые бактерии, окраска по Цилю-Нильсену (КУБ, КУМ, БК, микобактерии, окраска по Цилю-Нильсену, Ziehl-Neelsen, микроскопия мокроты, туберкулёз)', 'Микробиология', 'туберкулёз', 'Микроскопия мазка с окраской по Цилю-Нильсену для выявления кислотоустойчивых микобактерий при туберкулёзе.', 'Утренняя мокрота при глубоком откашливании в стерильный контейнер, до начала противотуберкулёзной терапии. Предварительно почистить зубы и прополоскать рот водой.', 722);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('posev-na-mikobakterii-tuberkuleza', 'Посев на микобактерии туберкулёза (бакпосев на МБТ, культуральное исследование, микобактерии, палочка Коха, Mycobacterium tuberculosis, туберкулёз, чувствительность к противотуберкулёзным препаратам)', 'Микробиология', 'туберкулёз', 'Культуральный посев на микобактерии туберкулёза для выявления возбудителя и определения чувствительности к препаратам.', 'Утренняя мокрота при глубоком откашливании в стерильный контейнер (или другой материал по локализации), до начала терапии. Почистить зубы и прополоскать рот водой.', 723);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('posev-na-mbt-avtomatizirovannyy', 'Посев на МБТ автоматизированный, BACTEC (BACTEC MGIT, автоматизированный посев, ускоренный посев на микобактерии, культура МБТ, Mycobacterium tuberculosis, туберкулёз, чувствительность к препаратам)', 'Микробиология', 'туберкулёз', 'Ускоренный автоматизированный посев на микобактерии туберкулёза (BACTEC) для быстрого выявления возбудителя и чувствительности к препаратам.', 'Утренняя мокрота при глубоком откашливании в стерильный контейнер (или другой материал по локализации), до начала терапии. Почистить зубы и прополоскать рот водой.', 724);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('he4', 'HE4, секреторный белок эпидидимиса 4 (HE4, human epididymis protein 4, онкомаркер яичников, рак яичников)', 'Онкомаркеры', 'Гинекологические (яичники, эндометрий)', 'Определение онкомаркера HE4 для диагностики и мониторинга рака яичников, в том числе в составе алгоритма ROMA.', 'Утром натощак, 8–12 ч голодания; можно пить воду. За 2–3 дня отменить биотин. Накануне исключить алкоголь и интенсивные нагрузки.', 725);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('algoritm-roma-i', 'Алгоритм ROMA-I для пременопаузы (ROMA, risk of ovarian malignancy algorithm, индекс риска рака яичников, HE4 и CA-125, пременопауза)', 'Онкомаркеры', 'Гинекологические (яичники, эндометрий)', 'Расчёт риска рака яичников по HE4 и CA-125 для женщин в пременопаузе при объёмных образованиях малого таза.', 'Утром натощак, 8–12 ч голодания; можно пить воду. Не сдавать во время менструации. За 2–3 дня отменить биотин.', 726);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('algoritm-roma-ii', 'ROMA-II для постменопаузы (ROMA, risk of ovarian malignancy algorithm, индекс риска рака яичников, HE4 и CA-125, постменопауза)', 'Онкомаркеры', 'Гинекологические (яичники, эндометрий)', 'Расчёт риска рака яичников по HE4 и CA-125 для женщин в постменопаузе при объёмных образованиях малого таза.', 'Утром натощак, 8–12 ч голодания; можно пить воду. За 2–3 дня отменить биотин. Накануне исключить алкоголь.', 727);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('antigen-ca-125', 'Антиген CA 125 (CA-125, углеводный антиген 125, онкомаркер яичников, рак яичников)', 'Онкомаркеры', 'Гинекологические (яичники, эндометрий)', 'Определение онкомаркера CA-125 для диагностики и мониторинга рака яичников и контроля лечения.', 'Утром натощак, 8–12 ч голодания; можно пить воду. Не сдавать во время менструации (возможно физиологическое повышение). За 2–3 дня отменить биотин.', 728);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('antigen-ca-15-3', 'Антиген CA 15-3 (CA 15-3, углеводный антиген 15-3, онкомаркер молочной железы, рак молочной железы)', 'Онкомаркеры', 'молочная железа', 'Определение онкомаркера CA 15-3 для мониторинга течения и эффективности лечения рака молочной железы.', 'Утром натощак, 8–12 ч голодания; можно пить воду. За 2–3 дня отменить биотин. Накануне исключить алкоголь и интенсивные нагрузки.', 729);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('antigen-ca-27-29', 'Антиген CA 27-29 (CA 27-29, углеводный антиген 27-29, онкомаркер молочной железы, рак молочной железы)', 'Онкомаркеры', 'молочная железа', 'Определение онкомаркера CA 27-29 для мониторинга течения и эффективности лечения рака молочной железы.', 'Утром натощак, 8–12 ч голодания; можно пить воду. За 2–3 дня отменить биотин. Накануне исключить алкоголь и интенсивные нагрузки.', 730);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('antigen-ca-19-9', 'Антиген CA 19-9 (CA 19-9, углеводный антиген 19-9, онкомаркер поджелудочной железы, рак поджелудочной железы и жёлчных путей)', 'Онкомаркеры', 'жкт и пжж', 'Определение онкомаркера CA 19-9 для диагностики и мониторинга рака поджелудочной железы и жёлчевыводящих путей.', 'Утром натощак, 8–12 ч голодания; можно пить воду. За 2–3 дня отменить биотин. Накануне исключить алкоголь.', 731);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('antigen-ca-242', 'Антиген CA 242 (CA 242, углеводный антиген 242, онкомаркер поджелудочной железы и ЖКТ)', 'Онкомаркеры', 'жкт и пжж', 'Определение онкомаркера CA 242 для диагностики и мониторинга рака поджелудочной железы и желудочно-кишечного тракта.', 'Утром натощак, 8–12 ч голодания; можно пить воду. За 2–3 дня отменить биотин. Накануне исключить алкоголь.', 732);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('antigen-ca-72-4', 'Антиген CA 72-4 (CA 72-4, углеводный антиген 72-4, онкомаркер желудка, рак желудка и яичников)', 'Онкомаркеры', 'жкт и пжж', 'Определение онкомаркера CA 72-4 для диагностики и мониторинга рака желудка и яичников.', 'Утром натощак, 8–12 ч голодания; можно пить воду. За 2–3 дня отменить биотин. Накануне исключить алкоголь.', 733);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('antigen-rakovo-embrionalnyy', 'Раково-эмбриональный антиген (РЭА, CEA, carcinoembryonic antigen, онкомаркер, колоректальный рак)', 'Онкомаркеры', 'жкт и пжж', 'Определение РЭА — универсального онкомаркера для мониторинга колоректального рака и других опухолей.', 'Утром натощак, 8–12 ч голодания; можно пить воду. За 2–3 дня отменить биотин. Курильщикам сообщить о курении (влияет на результат).', 734);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('antigen-ca-50', 'Антиген CA 50 (CA 50, углеводный антиген 50, онкомаркер поджелудочной железы и ЖКТ)', 'Онкомаркеры', 'жкт и пжж', 'Определение онкомаркера CA 50 для диагностики и мониторинга рака поджелудочной железы и желудочно-кишечного тракта.', 'Утром натощак, 8–12 ч голодания; можно пить воду. За 2–3 дня отменить биотин. Накануне исключить алкоголь.', 735);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('opuholevaya-m2-piruvatkinaza', 'Опухолевая M2-пируваткиназа (Tumor M2-PK, M2-пируваткиназа, опухолевая пируваткиназа, онкомаркер, колоректальный рак)', 'Онкомаркеры', 'жкт и пжж', 'Определение опухолевой M2-пируваткиназы для выявления и мониторинга опухолей ЖКТ, в том числе колоректального рака.', 'Кровь утром натощак, 8–12 ч голодания; или свежий кал в чистый контейнер — в зависимости от вида теста (уточнить в лаборатории).', 736);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('progrp', 'ProGRP (ПроГРП, pro-gastrin-releasing peptide, предшественник гастрин-рилизинг пептида, онкомаркер, мелкоклеточный рак лёгкого)', 'Онкомаркеры', 'легкие', 'Определение онкомаркера ProGRP для диагностики и мониторинга мелкоклеточного рака лёгкого.', 'Утром натощак, 8–12 ч голодания; можно пить воду. За 2–3 дня отменить биотин. Накануне исключить алкоголь.', 737);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('cyfra-21-1-rastvorimye-fragmenty-tsitokeratina-19', 'Cyfra 21-1 (CYFRA 21-1, фрагменты цитокератина 19, растворимый цитокератин 19, онкомаркер, немелкоклеточный рак лёгкого)', 'Онкомаркеры', 'легкие', 'Определение онкомаркера Cyfra 21-1 для диагностики и мониторинга немелкоклеточного рака лёгкого.', 'Утром натощак, 8–12 ч голодания; можно пить воду. За 2–3 дня отменить биотин. Накануне исключить алкоголь.', 738);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('neyron-spetsificheskaya-enolaza', 'Нейрон-специфическая енолаза (NSE, нейронспецифическая енолаза, neuron-specific enolase, онкомаркер, мелкоклеточный рак лёгкого, нейробластома)', 'Онкомаркеры', 'легкие', 'Определение NSE для диагностики и мониторинга мелкоклеточного рака лёгкого и нейроэндокринных опухолей.', 'Утром натощак, 8–12 ч голодания; можно пить воду. За 2–3 дня отменить биотин. Кровь берут аккуратно (гемолиз завышает результат).', 739);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('prostaticheskiy-spetsificheskiy-antigen-obschiy', 'ПСА общий (общий простатический специфический антиген, PSA total, total PSA, онкомаркер простаты, рак предстательной железы)', 'Онкомаркеры', 'предстательная', 'Определение общего ПСА для скрининга, диагностики и мониторинга рака и болезней предстательной железы.', 'Утром натощак; можно пить воду. За 7–10 дней исключить массаж простаты, ТРУЗИ, катетеризацию, езду на велосипеде; за 2 дня — эякуляцию. После биопсии — не ранее 6 недель.', 740);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('prostaticheskiy-spetsificheskiy-antigen-svobodnyy', 'ПСА свободный (свободный простатический специфический антиген, free PSA, fPSA, онкомаркер простаты)', 'Онкомаркеры', 'предстательная', 'Определение свободного ПСА; используется вместе с общим ПСА для уточнения риска рака простаты.', 'Утром натощак; можно пить воду. За 7–10 дней исключить массаж простаты, ТРУЗИ, катетеризацию, езду на велосипеде; за 2 дня — эякуляцию. После биопсии — не ранее 6 недель.', 741);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('sootnoshenie-svobodnogo-i-obschego-psa', 'Соотношение свободного и общего ПСА (индекс ПСА, free/total PSA ratio, % свободного ПСА, соотношение ПСА, рак простаты)', 'Онкомаркеры', 'предстательная', 'Расчёт соотношения свободного и общего ПСА для уточнения риска рака предстательной железы при пограничных значениях ПСА.', 'Утром натощак; можно пить воду. За 7–10 дней исключить массаж простаты, ТРУЗИ, катетеризацию, велосипед; за 2 дня — эякуляцию. После биопсии — не ранее 6 недель.', 742);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('indeks-zdorovya-prostaty', 'Индекс здоровья простаты PHI (PHI, prostate health index, индекс здоровья простаты, -2proPSA, p2PSA, риск рака простаты)', 'Онкомаркеры', 'предстательная', 'Расчётный индекс на основе форм ПСА (включая -2proPSA) для точной оценки риска рака предстательной железы.', 'Утром натощак; можно пить воду. За 7–10 дней исключить массаж простаты, ТРУЗИ, катетеризацию, велосипед; за 2 дня — эякуляцию. После биопсии — не ранее 6 недель.', 743);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('prostaticheskaya-kislaya-fosfataza', 'Простатическая кислая фосфатаза (ПКФ, PAP, prostatic acid phosphatase, кислая фосфатаза простаты, онкомаркер простаты)', 'Онкомаркеры', 'предстательная', 'Определение простатической кислой фосфатазы; применяется в диагностике и мониторинге рака предстательной железы.', 'Утром натощак; можно пить воду. За 2–3 дня исключить массаж простаты, ТРУЗИ, катетеризацию и езду на велосипеде.', 744);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('alfa-fetoprotein', 'Альфа-фетопротеин (АФП, AFP, alpha-fetoprotein, онкомаркер печени, герминогенные опухоли, гепатоцеллюлярный рак)', 'Онкомаркеры', 'печень и герминогенные', 'Определение АФП для диагностики и мониторинга гепатоцеллюлярного рака и герминогенных опухолей.', 'Утром натощак, 8–12 ч голодания; можно пить воду. За 2–3 дня отменить биотин. Накануне исключить алкоголь.', 745);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('horionicheskiy-gonadotropin-onkomarker-germinogennyh-opuhole', 'Хорионический гонадотропин, онкомаркер (ХГЧ, бета-ХГЧ, hCG, онкомаркер герминогенных опухолей, опухоли яичек и яичников, трофобластические опухоли)', 'Онкомаркеры', 'печень и герминогенные', 'Определение ХГЧ как онкомаркера герминогенных и трофобластических опухолей яичек, яичников и плаценты.', 'Утром натощак, 8–12 ч голодания; можно пить воду. За 2–3 дня отменить биотин.', 746);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('pivka-ii', 'PIVKA-II (ПИВКА-II, des-gamma-carboxy prothrombin, DCP, онкомаркер печени, гепатоцеллюлярный рак, ГЦК)', 'Онкомаркеры', 'печень и герминогенные', 'Определение PIVKA-II для диагностики и мониторинга гепатоцеллюлярного рака, в том числе вместе с АФП.', 'Утром натощак, 8–12 ч голодания; можно пить воду. Приём варфарина и других антикоагулянтов заранее согласовать с врачом (влияет на результат).', 747);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('belok-s-100', 'Белок S100 (S100, protein S100, S-100, онкомаркер меланомы, меланома)', 'Онкомаркеры', 'меланома и нейроэндокринные', 'Определение белка S100 для диагностики и мониторинга меланомы, в том числе оценки распространённости и рецидива.', 'Утром натощак, 8–12 ч голодания; можно пить воду. За 2–3 дня отменить биотин. Кровь берут аккуратно (гемолиз влияет на результат).', 748);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('hromogranin-a', 'Хромогранин А (CgA, chromogranin A, хромогранин А, онкомаркер, нейроэндокринные опухоли, НЭО, карциноид)', 'Онкомаркеры', 'меланома и нейроэндокринные', 'Определение хромогранина А для диагностики и мониторинга нейроэндокринных опухолей, в том числе карциноида.', 'Утром натощак, 8–12 ч голодания; можно пить воду. За 7–14 дней по согласованию с врачом отменить ингибиторы протонной помпы (сильно завышают результат).', 749);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('antigen-ploskokletochnoy-kartsinomy', 'Антиген плоскоклеточной карциномы (SCC, SCCA, squamous cell carcinoma antigen, онкомаркер плоскоклеточного рака, рак шейки матки, рак лёгкого, рак головы и шеи)', 'Онкомаркеры', 'плоскоклеточный', 'Определение онкомаркера SCCA для диагностики и мониторинга плоскоклеточного рака (шейки матки, лёгкого, головы и шеи, пищевода).', 'Утром натощак, 8–12 ч голодания; можно пить воду. За 2–3 дня отменить биотин. Кровь берут аккуратно, избегая загрязнения кожей и слюной (завышают результат).', 750);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('tireoglobulin-2', 'Тиреоглобулин, онкомаркер (ТГ, Tg, thyroglobulin, онкомаркер щитовидной железы, мониторинг рака щитовидной железы, дифференцированный рак ЩЖ)', 'Онкомаркеры', 'щитовидная железа', 'Определение тиреоглобулина для контроля после лечения дифференцированного рака щитовидной железы и выявления рецидива.', 'Утром натощак; можно пить воду. За 2–3 дня отменить биотин. Сдавать вместе с антителами к тиреоглобулину; после операции/пункции ЩЖ выждать срок по назначению врача.', 751);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('at-k-tireoglobulinu-soprovozhdenie-testa-na-tireoglobulin', 'Антитела к тиреоглобулину, сопровождение (АТ-ТГ, anti-Tg, anti-thyroglobulin, антитела к тиреоглобулину, контроль интерференции при тесте на тиреоглобулин)', 'Онкомаркеры', 'щитовидная железа', 'Определение антител к тиреоглобулину как обязательного сопровождения теста на тиреоглобулин для оценки достоверности результата.', 'Утром натощак; можно пить воду. За 2–3 дня отменить биотин. Сдаётся одновременно с тиреоглобулином.', 752);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('kaltsitonin-2', 'Кальцитонин, онкомаркер (кальцитонин, тиреокальцитонин, calcitonin, онкомаркер, медуллярный рак щитовидной железы)', 'Онкомаркеры', 'щитовидная железа', 'Определение кальцитонина для диагностики и мониторинга медуллярного рака щитовидной железы.', 'Утром натощак, 8–12 ч голодания; можно пить воду. За 2–3 дня отменить биотин. Накануне исключить алкоголь и интенсивные нагрузки.', 753);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('beta-2-mikroglobulin', 'Бета-2-микроглобулин (β2-микроглобулин, beta-2 microglobulin, B2M, онкомаркер, миелома, лимфома, оценка прогноза)', 'Онкомаркеры', 'гематологические', 'Определение бета-2-микроглобулина для оценки прогноза при миеломе и лимфомах, а также функции почек.', 'Утром натощак, 8–12 ч голодания; можно пить воду. Накануне исключить алкоголь и интенсивные нагрузки.', 754);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('timidinkinaza', 'Тимидинкиназа (ТК, thymidine kinase, TK1, онкомаркер, маркёр пролиферации, лимфопролиферативные заболевания)', 'Онкомаркеры', 'гематологические', 'Определение тимидинкиназы — маркёра пролиферативной активности клеток при лимфомах и лейкозах.', 'Утром натощак, 8–12 ч голодания; можно пить воду. Накануне исключить интенсивные физические нагрузки.', 755);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('svobodnye-legkie-tsepi-kappa-i-lyambda-2', 'Свободные лёгкие цепи каппа и лямбда (свободные лёгкие цепи, FLC, kappa/lambda, каппа/лямбда, соотношение лёгких цепей, миелома, парапротеинемия)', 'Онкомаркеры', 'гематологические', 'Определение свободных лёгких цепей каппа и лямбда с соотношением для диагностики и мониторинга миеломы и парапротеинемий.', 'Утром натощак, 8–12 ч голодания; можно пить воду. Накануне исключить алкоголь.', 756);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('immunofiksatsiya-paraproteina', 'Иммунофиксация парапротеина (иммунофиксация, IFE, immunofixation, типирование парапротеина, моноклональный белок, М-градиент, миелома)', 'Онкомаркеры', 'гематологические', 'Выявление и типирование парапротеина (моноклонального белка) методом иммунофиксации при миеломе и парапротеинемиях.', 'Утром натощак, 8–12 ч голодания; можно пить воду. Накануне исключить алкоголь.', 757);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('at-k-retseptoram-ttg', 'Антитела к рецепторам ТТГ (АТ-рТТГ, TRAb, anti-TSH receptor, антитела к рецептору тиреотропного гормона, болезнь Грейвса, Базедова болезнь, диффузный токсический зоб)', 'Аутоиммунная диагностика', 'Аутоиммунные болезни щитовидной железы', 'Определение антител к рецепторам ТТГ для диагностики болезни Грейвса (Базедовой болезни) и контроля её лечения.', 'Утром натощак; можно пить воду. За 2–3 дня отменить биотин. Накануне исключить стресс и интенсивные нагрузки.', 758);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('at-k-tireoidnoy-peroksidaze', 'Антитела к тиреоидной пероксидазе (АТ-ТПО, anti-TPO, антитела к тиреопероксидазе, микросомальные антитела, аутоиммунный тиреоидит, тиреоидит Хашимото)', 'Аутоиммунная диагностика', 'Аутоиммунные болезни щитовидной железы', 'Определение антител к тиреопероксидазе для диагностики аутоиммунного тиреоидита (тиреоидита Хашимото) и других аутоиммунных болезней ЩЖ.', 'Утром натощак; можно пить воду. За 2–3 дня отменить биотин.', 759);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('at-k-tireoglobulinu', 'Антитела к тиреоглобулину (АТ-ТГ, anti-Tg, антитела к тиреоглобулину, аутоиммунный тиреоидит, тиреоидит Хашимото)', 'Аутоиммунная диагностика', 'Аутоиммунные болезни щитовидной железы', 'Определение антител к тиреоглобулину для диагностики аутоиммунных заболеваний щитовидной железы.', 'Утром натощак; можно пить воду. За 2–3 дня отменить биотин.', 760);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('at-k-tsiklicheskomu-tsitrulinovomu-peptidu', 'Антитела к циклическому цитруллиновому пептиду (АТ к ЦЦП, анти-ЦЦП, anti-CCP, ACPA, антитела к циклическому цитруллинированному пептиду, ревматоидный артрит)', 'Аутоиммунная диагностика', 'Ревматологические', 'Определение антител к ЦЦП — раннего и специфичного маркёра ревматоидного артрита.', 'Утром натощак, 8–12 ч голодания; можно пить воду. Накануне исключить алкоголь и интенсивные нагрузки.', 761);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('at-k-yadernym-antigenam-skrining', 'Антитела к ядерным антигенам, скрининг (ANA screen, антинуклеарные антитела, АНА скрининг, скрининг АНА, системные заболевания соединительной ткани, СКВ)', 'Аутоиммунная диагностика', 'Ревматологические', 'Скрининговое определение антинуклеарных антител для выявления системных аутоиммунных заболеваний соединительной ткани.', 'Утром натощак, 8–12 ч голодания; можно пить воду. Накануне исключить алкоголь.', 762);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('antistreptolizin-o', 'Антистрептолизин-О (АСЛ-О, ASLO, ASO, антистрептолизин, стрептококковая инфекция, ревматизм)', 'Аутоиммунная диагностика', 'Ревматологические', 'Определение антистрептолизина-О — маркёра недавней стрептококковой инфекции и её осложнений (ревматизм, гломерулонефрит).', 'Утром натощак, 8–12 ч голодания; можно пить воду. Накануне исключить алкоголь и жирную пищу.', 763);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('revmatoidnyy-faktor', 'Ревматоидный фактор (РФ, RF, rheumatoid factor, ревмофактор, ревматоидный артрит)', 'Аутоиммунная диагностика', 'Ревматологические', 'Определение ревматоидного фактора для диагностики ревматоидного артрита и других аутоиммунных заболеваний.', 'Утром натощак, 8–12 ч голодания; можно пить воду. Накануне исключить алкоголь и жирную пищу.', 764);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('antinuklearnyy-faktor-na-kletkah-hep-2', 'Антинуклеарный фактор на клетках HEp-2 (АНФ, ANA HEp-2, антинуклеарный фактор, антинуклеарные антитела, непрямая иммунофлюоресценция, тип свечения, СКВ)', 'Аутоиммунная диагностика', 'Ревматологические', 'Определение антинуклеарного фактора на клетках HEp-2 с типом свечения для диагностики системных аутоиммунных болезней.', 'Утром натощак, 8–12 ч голодания; можно пить воду. Накануне исключить алкоголь.', 765);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('ena-skrin', 'ENA-скрин (ЭНА скрининг, ENA screen, экстрагируемые ядерные антигены, Sm, RNP, SSA/Ro, SSB/La, Scl-70, Jo-1, системные заболевания соединительной ткани)', 'Аутоиммунная диагностика', 'Ревматологические', 'Скрининговое определение антител к экстрагируемым ядерным антигенам (ENA) для диагностики системных аутоиммунных болезней.', 'Утром натощак, 8–12 ч голодания; можно пить воду. Накануне исключить алкоголь.', 766);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('ena-razvernutyy-profil', 'ENA развёрнутый профиль, иммуноблот (ЭНА профиль, ENA blot, экстрагируемые ядерные антигены, иммуноблот, типирование антител, СКВ, склеродермия, синдром Шёгрена)', 'Аутоиммунная диагностика', 'Ревматологические', 'Развёрнутое определение антител к экстрагируемым ядерным антигенам методом иммуноблота для дифференциальной диагностики аутоиммунных болезней.', 'Утром натощак, 8–12 ч голодания; можно пить воду. Накануне исключить алкоголь.', 767);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('antsa-at-k-mieloperoksidaze-i-proteinaze-3', 'АНЦА: антитела к MPO и PR3 (ANCA, АНЦА, антинейтрофильные цитоплазматические антитела, антитела к миелопероксидазе, антитела к протеиназе-3, MPO, PR3, системные васкулиты)', 'Аутоиммунная диагностика', 'Ревматологические', 'Определение антинейтрофильных цитоплазматических антител (к MPO и PR3) для диагностики системных васкулитов.', 'Утром натощак, 8–12 ч голодания; можно пить воду. Накануне исключить алкоголь.', 768);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('at-k-modifitsirovannomu-tsitrullinirovannomu-vimentinu', 'Антитела к модифицированному цитруллинированному виментину (anti-MCV, АТ к МЦВ, антитела к цитруллинированному виментину, ревматоидный артрит)', 'Аутоиммунная диагностика', 'Ревматологические', 'Определение антител к модифицированному цитруллинированному виментину для ранней диагностики ревматоидного артрита.', 'Утром натощак, 8–12 ч голодания; можно пить воду. Накануне исключить алкоголь и интенсивные нагрузки.', 769);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('krioglobuliny-2', 'Криоглобулины (cryoglobulins, криоглобулинемия, холодовые белки, васкулит, ревматология)', 'Аутоиммунная диагностика', 'Ревматологические', 'Выявление криоглобулинов в крови при васкулитах, аутоиммунных болезнях и хронических инфекциях.', 'Утром натощак. Важно: пробу берут и доставляют в тепле (37 °C) — уточните условия взятия в лаборатории заранее.', 770);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('spetsificheskie-at-igg-protiv-komponentov-yadra-i-tsitoplazm', 'Специфические IgG к компонентам ядра и цитоплазмы, 18 показателей (антинуклеарные антитела, ANA профиль иммуноблот, 18 антигенов, компоненты ядра и цитоплазмы, системные заболевания соединительной ткани)', 'Аутоиммунная диагностика', 'Ревматологические', 'Развёрнутое определение IgG к 18 ядерным и цитоплазматическим антигенам для дифференциальной диагностики системных аутоиммунных болезней.', 'Утром натощак, 8–12 ч голодания; можно пить воду. Накануне исключить алкоголь.', 771);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('at-k-beta-2-glikoproteinu-1-summarno', 'Антитела к бета-2-гликопротеину 1 суммарно (АБ2ГП, anti-β2-GP1, антитела к бета-2-гликопротеину, суммарные, IgG и IgM, антифосфолипидный синдром, АФС)', 'Аутоиммунная диагностика', 'Антифосфолипидный синдром и волчанка', 'Определение суммарных антител к бета-2-гликопротеину 1 для диагностики антифосфолипидного синдрома.', 'Утром натощак, 8–12 ч голодания; можно пить воду. Накануне исключить алкоголь.', 772);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('at-k-dvuspiralnoy-dnk', 'Антитела к двуспиральной ДНК (АТ к дсДНК, anti-dsDNA, антитела к нативной ДНК, двухцепочечная ДНК, системная красная волчанка, СКВ)', 'Аутоиммунная диагностика', 'Антифосфолипидный синдром и волчанка', 'Определение антител к двуспиральной ДНК — высокоспецифичного маркёра системной красной волчанки и её активности.', 'Утром натощак, 8–12 ч голодания; можно пить воду. Накануне исключить алкоголь.', 773);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('at-k-kardiolipinu-igg', 'Антитела к кардиолипину IgG (АКЛ IgG, anti-cardiolipin IgG, антитела к кардиолипину, антифосфолипидный синдром, АФС)', 'Аутоиммунная диагностика', 'Антифосфолипидный синдром и волчанка', 'Определение антител класса IgG к кардиолипину для диагностики антифосфолипидного синдрома.', 'Утром натощак, 8–12 ч голодания; можно пить воду. Накануне исключить алкоголь.', 774);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('at-k-odnospiralnoy-dnk', 'Антитела к односпиральной ДНК (АТ к оцДНК, anti-ssDNA, антитела к денатурированной ДНК, одноцепочечная ДНК, аутоиммунные заболевания)', 'Аутоиммунная диагностика', 'Антифосфолипидный синдром и волчанка', 'Определение антител к односпиральной ДНК; применяется в диагностике аутоиммунных заболеваний, в том числе СКВ.', 'Утром натощак, 8–12 ч голодания; можно пить воду. Накануне исключить алкоголь.', 775);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('at-k-fosfolipidam-igg', 'Антитела к фосфолипидам IgG (АФЛ IgG, anti-phospholipid IgG, антифосфолипидные антитела, антифосфолипидный синдром, АФС)', 'Аутоиммунная диагностика', 'Антифосфолипидный синдром и волчанка', 'Определение антифосфолипидных антител класса IgG для диагностики антифосфолипидного синдрома.', 'Утром натощак, 8–12 ч голодания; можно пить воду. Накануне исключить алкоголь.', 776);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('at-k-fosfolipidam-igm', 'Антитела к фосфолипидам IgM (АФЛ IgM, anti-phospholipid IgM, антифосфолипидные антитела, антифосфолипидный синдром, АФС)', 'Аутоиммунная диагностика', 'Антифосфолипидный синдром и волчанка', 'Определение антифосфолипидных антител класса IgM для диагностики антифосфолипидного синдрома.', 'Утром натощак, 8–12 ч голодания; можно пить воду. Накануне исключить алкоголь.', 777);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('volchanochnyy-antikoagulyant-skrining', 'Волчаночный антикоагулянт, скрининг (ВА скрининг, lupus anticoagulant screen, LA скрининг, волчаночный антикоагулянт, антифосфолипидный синдром, АФС), скрининговый', 'Аутоиммунная диагностика', 'Антифосфолипидный синдром и волчанка', 'Скрининговое выявление волчаночного антикоагулянта — маркёра антифосфолипидного синдрома и риска тромбозов.', 'Утром натощак; можно пить воду. Приём антикоагулянтов (гепарин, варфарин, НОАК) заранее согласовать с врачом — влияют на результат.', 778);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('at-k-kardiolipinu-igm', 'Антитела к кардиолипину IgM (АКЛ IgM, anti-cardiolipin IgM, антитела к кардиолипину, антифосфолипидный синдром, АФС)', 'Аутоиммунная диагностика', 'Антифосфолипидный синдром и волчанка', 'Определение антител класса IgM к кардиолипину для диагностики антифосфолипидного синдрома.', 'Утром натощак, 8–12 ч голодания; можно пить воду. Накануне исключить алкоголь.', 779);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('at-k-beta-2-glikoproteinu-1-igg', 'Антитела к бета-2-гликопротеину 1 IgG (anti-β2-GP1 IgG, антитела к бета-2-гликопротеину IgG, антифосфолипидный синдром, АФС)', 'Аутоиммунная диагностика', 'Антифосфолипидный синдром и волчанка', 'Определение антител класса IgG к бета-2-гликопротеину 1 для диагностики антифосфолипидного синдрома.', 'Утром натощак, 8–12 ч голодания; можно пить воду. Накануне исключить алкоголь.', 780);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('at-k-beta-2-glikoproteinu-1-igm', 'Антитела к бета-2-гликопротеину 1 IgM (anti-β2-GP1 IgM, антитела к бета-2-гликопротеину IgM, антифосфолипидный синдром, АФС)', 'Аутоиммунная диагностика', 'Антифосфолипидный синдром и волчанка', 'Определение антител класса IgM к бета-2-гликопротеину 1 для диагностики антифосфолипидного синдрома.', 'Утром натощак, 8–12 ч голодания; можно пить воду. Накануне исключить алкоголь.', 781);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('volchanochnyy-antikoagulyant-podtverzhdayuschiy-test', 'Волчаночный антикоагулянт, подтверждающий тест (ВА подтверждающий, lupus anticoagulant confirm, LA подтверждающий, волчаночный антикоагулянт, антифосфолипидный синдром, АФС), подтверждающий', 'Аутоиммунная диагностика', 'Антифосфолипидный синдром и волчанка', 'Подтверждающий тест на волчаночный антикоагулянт после положительного скрининга для диагностики антифосфолипидного синдрома.', 'Утром натощак; можно пить воду. Приём антикоагулянтов (гепарин, варфарин, НОАК) заранее согласовать с врачом — влияют на результат.', 782);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('antitela-k-gliadinu-iga', 'Антитела к глиадину IgA (АГА IgA, anti-gliadin IgA, антитела к глиадину, целиакия, глютеновая энтеропатия)', 'Аутоиммунная диагностика', 'Аутоиммунные болезни ЖКТ', 'Определение антител класса IgA к глиадину для диагностики целиакии (глютеновой энтеропатии).', 'Утром натощак, 8–12 ч голодания; можно пить воду. Не переходить на безглютеновую диету до анализа (искажает результат).', 783);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('at-k-alfa-gliadinu-igg', 'Антитела к альфа-глиадину IgG (ААГ IgG, anti-gliadin IgG, антитела к глиадину, целиакия, глютеновая энтеропатия)', 'Аутоиммунная диагностика', 'Аутоиммунные болезни ЖКТ', 'Определение антител класса IgG к альфа-глиадину для диагностики целиакии, в том числе при дефиците IgA.', 'Утром натощак, 8–12 ч голодания; можно пить воду. Не переходить на безглютеновую диету до анализа (искажает результат).', 784);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('at-k-transglutaminaze-iga', 'Антитела к тканевой трансглутаминазе IgA (анти-tTG IgA, tissue transglutaminase IgA, антитела к трансглутаминазе, целиакия)', 'Аутоиммунная диагностика', 'Аутоиммунные болезни ЖКТ', 'Определение антител класса IgA к тканевой трансглутаминазе — основного маркёра целиакии.', 'Утром натощак, 8–12 ч голодания; можно пить воду. Не переходить на безглютеновую диету до анализа (искажает результат).', 785);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('at-k-transglutaminaze-igg', 'Антитела к тканевой трансглутаминазе IgG (анти-tTG IgG, tissue transglutaminase IgG, антитела к трансглутаминазе, целиакия, дефицит IgA)', 'Аутоиммунная диагностика', 'Аутоиммунные болезни ЖКТ', 'Определение антител класса IgG к тканевой трансглутаминазе для диагностики целиакии, особенно при дефиците IgA.', 'Утром натощак, 8–12 ч голодания; можно пить воду. Не переходить на безглютеновую диету до анализа (искажает результат).', 786);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('at-k-endomiziyu-iga', 'Антитела к эндомизию IgA (EMA IgA, anti-endomysial IgA, антитела к эндомизию, целиакия)', 'Аутоиммунная диагностика', 'Аутоиммунные болезни ЖКТ', 'Определение антител класса IgA к эндомизию — высокоспецифичного маркёра целиакии.', 'Утром натощак, 8–12 ч голодания; можно пить воду. Не переходить на безглютеновую диету до анализа (искажает результат).', 787);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('at-k-parietalnym-kletkam-zheludka', 'Антитела к париетальным клеткам желудка (АТ к париетальным клеткам, anti-parietal cell antibody, APCA, обкладочные клетки, аутоиммунный гастрит, B12-дефицитная анемия)', 'Аутоиммунная диагностика', 'Аутоиммунные болезни ЖКТ', 'Определение антител к париетальным клеткам желудка для диагностики аутоиммунного гастрита и пернициозной анемии.', 'Утром натощак, 8–12 ч голодания; можно пить воду. Накануне исключить алкоголь.', 788);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('at-k-vnutrennemu-faktoru-kastla', 'Антитела к внутреннему фактору Кастла (АТ к фактору Кастла, anti-intrinsic factor, внутренний фактор, пернициозная анемия, B12-дефицитная анемия)', 'Аутоиммунная диагностика', 'Аутоиммунные болезни ЖКТ', 'Определение антител к внутреннему фактору Кастла для диагностики пернициозной (B12-дефицитной) анемии.', 'Утром натощак, 8–12 ч голодания; можно пить воду. За несколько дней по согласованию с врачом не вводить препараты витамина B12.', 789);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('asca-igg-i-iga', 'ASCA, антитела к Saccharomyces cerevisiae IgG и IgA (ASCA, anti-Saccharomyces cerevisiae, антитела к пекарским дрожжам, болезнь Крона, воспалительные заболевания кишечника, ВЗК)', 'Аутоиммунная диагностика', 'Аутоиммунные болезни ЖКТ', 'Определение антител ASCA (IgG и IgA) для дифференциальной диагностики болезни Крона и язвенного колита.', 'Утром натощак, 8–12 ч голодания; можно пить воду. Накануне исключить алкоголь.', 790);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('at-k-bokalovidnym-kletkam-kishechnika', 'Антитела к бокаловидным клеткам кишечника (АТ к бокаловидным клеткам, anti-goblet cell antibody, GAB, язвенный колит, воспалительные заболевания кишечника, ВЗК)', 'Аутоиммунная диагностика', 'Аутоиммунные болезни ЖКТ', 'Определение антител к бокаловидным клеткам кишечника для диагностики язвенного колита и других ВЗК.', 'Утром натощак, 8–12 ч голодания; можно пить воду. Накануне исключить алкоголь.', 791);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('gad-65', 'GAD-65, антитела к глутаматдекарбоксилазе (GAD, анти-GAD, антитела к глутаматдекарбоксилазе, GADA, аутоиммунный диабет, сахарный диабет 1 типа, LADA)', 'Аутоиммунная диагностика', 'Аутоиммунный диабет', 'Определение антител к глутаматдекарбоксилазе (GAD-65) — основного маркёра аутоиммунного диабета 1 типа и LADA.', 'Утром натощак, 8–12 ч голодания; можно пить воду. Накануне исключить алкоголь и интенсивные нагрузки.', 792);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('at-k-insulinu', 'Антитела к инсулину (АТ к инсулину, IAA, insulin autoantibodies, аутоантитела к инсулину, сахарный диабет 1 типа)', 'Аутоиммунная диагностика', 'Аутоиммунный диабет', 'Определение антител к инсулину для диагностики аутоиммунного диабета 1 типа, преимущественно у детей.', 'Утром натощак, 8–12 ч голодания; можно пить воду. Желательно сдавать до начала инсулинотерапии (терапия влияет на результат).', 793);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('at-k-ostrovkovym-kletkam-podzheludochnoy-zhelezy', 'Антитела к островковым клеткам поджелудочной железы (ICA, islet cell antibodies, антитела к островковым клеткам, бета-клетки, сахарный диабет 1 типа)', 'Аутоиммунная диагностика', 'Аутоиммунный диабет', 'Определение антител к островковым клеткам поджелудочной железы для диагностики и прогноза аутоиммунного диабета 1 типа.', 'Утром натощак, 8–12 ч голодания; можно пить воду. Накануне исключить алкоголь.', 794);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('at-k-tirozinfosfataze', 'Антитела к тирозинфосфатазе IA-2 (IA-2, anti-IA-2, антитела к тирозинфосфатазе, IA-2A, сахарный диабет 1 типа)', 'Аутоиммунная диагностика', 'Аутоиммунный диабет', 'Определение антител к тирозинфосфатазе (IA-2) — маркёра аутоиммунного диабета 1 типа и оценки риска.', 'Утром натощак, 8–12 ч голодания; можно пить воду. Накануне исключить алкоголь.', 795);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('at-k-transporteru-tsinka-8', 'Антитела к транспортёру цинка 8 (ZnT8, anti-ZnT8, антитела к транспортёру цинка, ZnT8A, сахарный диабет 1 типа)', 'Аутоиммунная диагностика', 'Аутоиммунный диабет', 'Определение антител к транспортёру цинка 8 (ZnT8) для диагностики аутоиммунного диабета 1 типа и уточнения риска.', 'Утром натощак, 8–12 ч голодания; можно пить воду. Накануне исключить алкоголь.', 796);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('at-k-ag-membrany-mitohondriy', 'Антитела к митохондриям AMA-M2 (АМА-М2, AMA-M2, anti-mitochondrial antibody, антимитохондриальные антитела, первичный билиарный холангит, билиарный цирроз)', 'Аутоиммунная диагностика', 'аутоиммунные заболевания печени', 'Определение антимитохондриальных антител (AMA-M2) — основного маркёра первичного билиарного холангита (билиарного цирроза).', 'Утром натощак, 8–12 ч голодания; можно пить воду. Накануне исключить алкоголь.', 797);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('anti-sla-lp-igg-antitela-pechenochno-pankreaticheskomu-antig', 'Антитела к SLA/LP IgG (anti-SLA/LP, антитела к печёночно-панкреатическому антигену, soluble liver antigen, аутоиммунный гепатит)', 'Аутоиммунная диагностика', 'аутоиммунные заболевания печени', 'Определение антител к SLA/LP — высокоспецифичного маркёра аутоиммунного гепатита.', 'Утром натощак, 8–12 ч голодания; можно пить воду. Накануне исключить алкоголь.', 798);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('at-k-mikrosomalnoy-fraktsii-pecheni-i-pochek', 'Антитела к микросомам печени и почек LKM-1 (LKM-1, anti-LKM-1, антитела к микросомальной фракции печени и почек, аутоиммунный гепатит 2 типа)', 'Аутоиммунная диагностика', 'аутоиммунные заболевания печени', 'Определение антител к микросомам печени и почек (LKM-1) для диагностики аутоиммунного гепатита 2 типа.', 'Утром натощак, 8–12 ч голодания; можно пить воду. Накануне исключить алкоголь.', 799);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('at-k-gladkoy-muskulature', 'Антитела к гладкой мускулатуре ASMA (ASMA, anti-smooth muscle antibody, антитела к гладким мышцам, SMA, аутоиммунный гепатит 1 типа)', 'Аутоиммунная диагностика', 'аутоиммунные заболевания печени', 'Определение антител к гладкой мускулатуре (ASMA) для диагностики аутоиммунного гепатита 1 типа.', 'Утром натощак, 8–12 ч голодания; можно пить воду. Накануне исключить алкоголь.', 800);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('at-k-rastvorimomu-pechenochnomu-antigenu', 'Антитела к растворимому печёночному антигену anti-SLA (anti-SLA, антитела к растворимому печёночному антигену, soluble liver antigen, аутоиммунный гепатит)', 'Аутоиммунная диагностика', 'аутоиммунные заболевания печени', 'Определение антител к растворимому печёночному антигену (anti-SLA) — специфичного маркёра аутоиммунного гепатита.', 'Утром натощак, 8–12 ч голодания; можно пить воду. Накануне исключить алкоголь.', 801);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('autoimmunnyy-profil-pecheni-i-pochek', 'Аутоиммунный профиль печени и почек, 10 показателей (аутоиммунный профиль печени, иммуноблот, AMA-M2, LKM-1, SLA/LP, ASMA и др., аутоиммунный гепатит, первичный билиарный холангit)', 'Аутоиммунная диагностика', 'аутоиммунные заболевания печени', 'Комплексное определение 10 аутоантител для дифференциальной диагностики аутоиммунных заболеваний печени.', 'Утром натощак, 8–12 ч голодания; можно пить воду. Накануне исключить алкоголь.', 802);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('at-k-atsetilholinovym-retseptoram', 'Антитела к ацетилхолиновым рецепторам (АХР, anti-AChR, антитела к рецепторам ацетилхолина, acetylcholine receptor antibody, миастения, миастения гравис)', 'Аутоиммунная диагностика', 'неврологические и прочие аутоиммунные', 'Определение антител к ацетилхолиновым рецепторам — основного маркёра миастении (myasthenia gravis).', 'Утром натощак, 8–12 ч голодания; можно пить воду. Накануне исключить алкоголь и интенсивные нагрузки.', 803);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('at-k-akvaporinu-4', 'Антитела к аквапорину-4 (AQP4, anti-aquaporin-4, антитела к аквапорину 4, NMO-IgG, нейромиелит зрительного нерва, оптиконевромиелит, болезнь Девика)', 'Аутоиммунная диагностика', 'неврологические и прочие аутоиммунные', 'Определение антител к аквапорину-4 для диагностики нейромиелита зрительного нерва (оптиконевромиелита).', 'Утром натощак, 8–12 ч голодания; можно пить воду. Накануне исключить алкоголь.', 804);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('at-k-skeletnym-myshtsam', 'Антитела к скелетным мышцам (АТ к скелетным мышцам, anti-striated muscle antibody, антитела к поперечно-полосатой мускулатуре, миастения, тимома)', 'Аутоиммунная диагностика', 'неврологические и прочие аутоиммунные', 'Определение антител к скелетным мышцам; применяется при миастении, особенно в сочетании с тимомой.', 'Утром натощак, 8–12 ч голодания; можно пить воду. Накануне исключить алкоголь и интенсивные нагрузки.', 805);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('at-k-bazalnoy-membrane-klubochkov', 'Антитела к базальной мембране клубочков (анти-БМК, anti-GBM, антитела к гломерулярной базальной мембране, синдром Гудпасчера, быстропрогрессирующий гломерулонефрит)', 'Аутоиммунная диагностика', 'неврологические и прочие аутоиммунные', 'Определение антител к базальной мембране клубочков для диагностики синдрома Гудпасчера и БМК-нефрита.', 'Утром натощак, 8–12 ч голодания; можно пить воду. Накануне исключить алкоголь.', 806);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('at-k-desmogleinu-1-i-3', 'Антитела к десмоглеину 1 и 3 (anti-desmoglein 1/3, антитела к десмоглеину, десмоглеин 1 и 3, вульгарная пузырчатка, листовидная пузырчатка, пемфигус)', 'Аутоиммунная диагностика', 'неврологические и прочие аутоиммунные', 'Определение антител к десмоглеину 1 и 3 для диагностики и типирования пузырчатки (пемфигуса).', 'Утром натощак, 8–12 ч голодания; можно пить воду. Накануне исключить алкоголь.', 807);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('at-k-mielinu', 'Антитела к миелину (anti-myelin antibody, антитела к миелину, демиелинизирующие заболевания, рассеянный склероз)', 'Аутоиммунная диагностика', 'неврологические и прочие аутоиммунные', 'Определение антител к миелину; применяется при демиелинизирующих заболеваниях нервной системы.', 'Утром натощак, 8–12 ч голодания; можно пить воду. Накануне исключить алкоголь.', 808);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('at-k-antigenam-organov', 'Антитела к антигенам органов, скрининг (органоспецифические антитела, скрининг аутоантител, тканевые антитела, аутоиммунное поражение органов)', 'Аутоиммунная диагностика', 'антитела к антигенам органов', 'Скрининговое определение антител к антигенам органов для выявления органоспецифических аутоиммунных процессов.', 'Утром натощак, 8–12 ч голодания; можно пить воду. Накануне исключить алкоголь.', 809);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('at-k-antigenam-pochek', 'Антитела к антигенам почек (антитела к ткани почек, anti-kidney antibody, почечные аутоантитела, аутоиммунное поражение почек)', 'Аутоиммунная диагностика', 'антитела к антигенам органов', 'Определение антител к антигенам почек для выявления аутоиммунного поражения почечной ткани.', 'Утром натощак, 8–12 ч голодания; можно пить воду. Накануне исключить алкоголь.', 810);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('at-k-antigenam-tolstogo-i-tonkogo-kishechnika', 'Антитела к антигенам толстого и тонкого кишечника (антитела к ткани кишечника, anti-intestinal antibody, кишечные аутоантитела, воспалительные заболевания кишечника, ВЗК)', 'Аутоиммунная диагностика', 'антитела к антигенам органов', 'Определение антител к антигенам тонкого и толстого кишечника для выявления аутоиммунного поражения кишечника.', 'Утром натощак, 8–12 ч голодания; можно пить воду. Накануне исключить алкоголь.', 811);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('antitrombin-iii-aktivnosti', 'Антитромбин III, % активности (АТ III, antithrombin III, антитромбин 3, активность антитромбина, тромбофилия, риск тромбозов)', 'Коагулология', 'Свёртывание крови', 'Определение активности антитромбина III — естественного антикоагулянта; используется в диагностике тромбофилии.', 'Утром натощак или через 3 ч после лёгкого приёма пищи; можно пить воду. Приём антикоагулянтов согласовать с врачом.', 812);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('achtv', 'АЧТВ (АЧТВ, APTT, активированное частичное тромбопластиновое время, активированное парциальное тромбопластиновое время)', 'Коагулология', 'Свёртывание крови', 'Определение АЧТВ для оценки внутреннего пути свёртывания и контроля терапии гепарином.', 'Утром натощак или через 3 ч после лёгкого приёма пищи; можно пить воду. Контроль гепаринотерапии — на фоне назначенной схемы.', 813);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('vremya-svertyvaniya', 'Время свёртывания крови (время свёртывания, clotting time, ВСК, свёртываемость крови)', 'Коагулология', 'Свёртывание крови', 'Определение времени свёртывания крови для ориентировочной оценки состояния системы гемостаза.', 'Утром натощак или через 3 ч после лёгкого приёма пищи; можно пить воду. Накануне исключить алкоголь.', 814);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('d-dimer', 'D-димер (Д-димер, D-dimer, продукты деградации фибрина, тромбоз, ТЭЛА, тромбоэмболия)', 'Коагулология', 'Свёртывание крови', 'Определение D-димера для диагностики тромбозов, тромбоэмболии лёгочной артерии и оценки риска тромбообразования.', 'Утром натощак или через 3 ч после лёгкого приёма пищи; можно пить воду. Накануне исключить интенсивные физические нагрузки.', 815);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('protrombin-mno', 'Протромбин, МНО (МНО, INR, protrombin, международное нормализованное отношение, контроль варфарина, антикоагулянтная терапия)', 'Коагулология', 'Свёртывание крови', 'Определение МНО для оценки внешнего пути свёртывания и контроля терапии варфарином.', 'Утром натощак или через 3 ч после лёгкого приёма пищи; можно пить воду. Контроль терапии варфарином — на фоне назначенной схемы приёма.', 816);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('trombinovoe-vremya', 'Тромбиновое время (ТВ, thrombin time, TT, тромбиновое время свёртывания)', 'Коагулология', 'Свёртывание крови', 'Определение тромбинового времени для оценки конечного этапа свёртывания — превращения фибриногена в фибрин.', 'Утром натощак или через 3 ч после лёгкого приёма пищи; можно пить воду. Приём антикоагулянтов согласовать с врачом.', 817);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('fibrinogen', 'Фибриноген (fibrinogen, фактор I свёртывания, фибриноген крови)', 'Коагулология', 'Свёртывание крови', 'Определение фибриногена — белка свёртывания и маркёра воспаления; важен для оценки гемостаза и риска тромбозов.', 'Утром натощак или через 3 ч после лёгкого приёма пищи; можно пить воду. Накануне исключить алкоголь и жирную пищу.', 818);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('protrombinovoe-vremya', 'Протромбиновое время (ПВ, PT, prothrombin time, протромбиновое время свёртывания)', 'Коагулология', 'Свёртывание крови', 'Определение протромбинового времени для оценки внешнего пути свёртывания и функции печени.', 'Утром натощак или через 3 ч после лёгкого приёма пищи; можно пить воду. Приём антикоагулянтов согласовать с врачом.', 819);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('protrombinovyy-indeks', 'Протромбиновый индекс (ПТИ, prothrombin index, протромбиновый индекс по Квику, протромбин по Квику)', 'Коагулология', 'Свёртывание крови', 'Определение протромбинового индекса для оценки внешнего пути свёртывания крови и функции печени.', 'Утром натощак или через 3 ч после лёгкого приёма пищи; можно пить воду. Приём антикоагулянтов согласовать с врачом.', 820);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('gemostaziogramma-rasshirennaya', 'Гемостазиограмма расширенная (коагулограмма расширенная, развёрнутая коагулограмма, гемостаз, АЧТВ, протромбин, МНО, фибриноген, антитромбин III, D-димер)', 'Коагулология', 'Расширенная коагулограмма', 'Расширенная оценка системы свёртывания крови для диагностики нарушений гемостаза, тромбозов и кровоточивости.', 'Утром натощак или через 3 ч после лёгкого приёма пищи; можно пить воду. Приём антикоагулянтов согласовать с врачом; накануне исключить нагрузки.', 821);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('gemostaziogramma-skrining', 'Гемостазиограмма скрининг (коагулограмма скрининг, базовая коагулограмма, гемостаз, АЧТВ, протромбин, МНО, фибриноген)', 'Коагулология', 'Расширенная коагулограмма', 'Базовая оценка системы свёртывания крови для скрининга нарушений гемостаза.', 'Утром натощак или через 3 ч после лёгкого приёма пищи; можно пить воду. Приём антикоагулянтов согласовать с врачом.', 822);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('protein-c', 'Протеин C (protein C, протеин Ц, естественный антикоагулянт, тромбофилия, риск тромбозов)', 'Коагулология', 'Расширенная коагулограмма', 'Определение протеина C — естественного антикоагулянта; используется в диагностике тромбофилии.', 'Утром натощак; можно пить воду. Приём антикоагулянтов (особенно варфарина) согласовать с врачом — влияет на результат.', 823);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('protein-s', 'Протеин S (protein S, протеин Эс, естественный антикоагулянт, тромбофилия, риск тромбозов)', 'Коагулология', 'Расширенная коагулограмма', 'Определение протеина S — естественного антикоагулянта; используется в диагностике тромбофилии.', 'Утром натощак; можно пить воду. Приём антикоагулянтов (особенно варфарина) согласовать с врачом — влияет на результат.', 824);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('faktor-villebranda', 'Фактор Виллебранда (von Willebrand factor, vWF, фактор фон Виллебранда, болезнь Виллебранда, нарушение свёртывания)', 'Коагулология', 'Расширенная коагулограмма', 'Определение фактора Виллебранда для диагностики болезни Виллебранда и оценки первичного гемостаза.', 'Утром натощак или через 3 ч после лёгкого приёма пищи; можно пить воду. Накануне исключить интенсивные нагрузки и стресс.', 825);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('rezistentnost-k-aktivirovannomu-proteinu-c', 'Резистентность к активированному протеину C (APC-R, APC resistance, устойчивость к активированному протеину C, фактор V Лейден, тромбофилия)', 'Коагулология', 'Расширенная коагулограмма', 'Определение резистентности к активированному протеину C для диагностики наследственной тромбофилии (мутация фактора V Лейден).', 'Утром натощак; можно пить воду. Приём антикоагулянтов согласовать с врачом — влияет на результат.', 826);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('plazminogen', 'Плазминоген (plasminogen, плазминоген крови, фибринолиз, система фибринолиза)', 'Коагулология', 'Расширенная коагулограмма', 'Определение плазминогена для оценки системы фибринолиза (растворения тромбов).', 'Утром натощак; можно пить воду. Приём антикоагулянтов и тромболитиков согласовать с врачом.', 827);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('rfmk', 'РФМК (растворимые фибрин-мономерные комплексы, soluble fibrin monomer complexes, РФМК, активация свёртывания, ДВС-синдром)', 'Коагулология', 'Расширенная коагулограмма', 'Определение РФМК — маркёра внутрисосудистого свёртывания и активации тромбообразования (в том числе при ДВС-синдроме).', 'Утром натощак или через 3 ч после лёгкого приёма пищи; можно пить воду. Накануне исключить интенсивные нагрузки.', 828);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('agregatsiya-trombotsitov', 'Агрегация тромбоцитов (agregation, агрегация тромбоцитов, функция тромбоцитов, тромбоцитарный гемостаз)', 'Коагулология', 'Расширенная коагулограмма', 'Оценка способности тромбоцитов к склеиванию (агрегации) для диагностики нарушений тромбоцитарного гемостаза.', 'Утром натощак; можно пить воду. За 7–10 дней по согласованию с врачом отменить аспирин и другие дезагреганты; накануне исключить кофе и жирную пищу.', 829);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('faktor-svertyvaniya-viii', 'Фактор свёртывания VIII (factor VIII, фактор 8, антигемофильный глобулин, гемофилия A)', 'Коагулология', 'Расширенная коагулограмма', 'Определение фактора свёртывания VIII для диагностики гемофилии A и других нарушений свёртывания.', 'Утром натощак или через 3 ч после лёгкого приёма пищи; можно пить воду. Накануне исключить интенсивные нагрузки и стресс.', 830);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('faktor-svertyvaniya-ix', 'Фактор свёртывания IX (factor IX, фактор 9, фактор Кристмаса, гемофилия B)', 'Коагулология', 'Расширенная коагулограмма', 'Определение фактора свёртывания IX для диагностики гемофилии B и других нарушений свёртывания.', 'Утром натощак или через 3 ч после лёгкого приёма пищи; можно пить воду. Накануне исключить интенсивные нагрузки и стресс.', 831);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('indutsirovannaya-agregatsiya-trombotsitov', 'Индуцированная агрегация тромбоцитов (индуцированная агрегация, АДФ, адреналин, коллаген, ристоцетин, функция тромбоцитов, тромбоцитарный гемостаз)', 'Коагулология', 'Расширенная коагулограмма', 'Оценка агрегации тромбоцитов с индукторами (АДФ, адреналин, коллаген, ристоцетин) для детальной диагностики нарушений тромбоцитов.', 'Утром натощак; можно пить воду. За 7–10 дней по согласованию с врачом отменить аспирин и другие дезагреганты; накануне исключить кофе и жирную пищу.', 832);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('antitela-k-trombotsitam', 'Антитела к тромбоцитам (АТ к тромбоцитам, anti-platelet antibody, антитромбоцитарные антитела, иммунная тромбоцитопения, ИТП)', 'Коагулология', 'Расширенная коагулограмма', 'Определение антител к тромбоцитам для диагностики иммунной тромбоцитопении и аутоиммунного разрушения тромбоцитов.', 'Утром натощак или через 3 ч после лёгкого приёма пищи; можно пить воду. Накануне исключить алкоголь.', 833);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('tromboelastografiya', 'Тромбоэластография (ТЭГ, TEG, thromboelastography, тромбоэластограмма, интегральная оценка гемостаза)', 'Коагулология', 'Расширенная коагулограмма', 'Интегральная оценка всех этапов свёртывания и фибринолиза в реальном времени для комплексной диагностики гемостаза.', 'Утром натощак или через 3 ч после лёгкого приёма пищи; можно пить воду. Приём антикоагулянтов и дезагрегантов согласовать с врачом; проба исследуется быстро.', 834);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('valproevaya-kislota', 'Вальпроевая кислота (valproic acid, вальпроат, депакин, конвулекс, лекарственный мониторинг, ТЛМ, противоэпилептический препарат)', 'Лекарственный мониторинг', 'Противоэпилептические препараты', 'Определение концентрации вальпроевой кислоты в крови для контроля дозы и безопасности противоэпилептической терапии.', 'Кровь берут перед приёмом очередной дозы (остаточная концентрация), обычно утром натощак. Точное время приёма препарата сообщить лаборатории.', 835);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('karbamazepin', 'Карбамазепин (carbamazepine, финлепсин, тегретол, лекарственный мониторинг, ТЛМ, противоэпилептический препарат)', 'Лекарственный мониторинг', 'Противоэпилептические препараты', 'Определение концентрации карбамазепина в крови для контроля дозы и безопасности противоэпилептической терапии.', 'Кровь берут перед приёмом очередной дозы (остаточная концентрация), обычно утром натощак. Точное время приёма препарата сообщить лаборатории.', 836);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('fenitoin', 'Фенитоин (phenytoin, дифенин, лекарственный мониторинг, ТЛМ, противоэпилептический препарат)', 'Лекарственный мониторинг', 'Противоэпилептические препараты', 'Определение концентрации фенитоина в крови для контроля дозы и безопасности противоэпилептической терапии.', 'Кровь берут перед приёмом очередной дозы (остаточная концентрация), обычно утром натощак. Точное время приёма препарата сообщить лаборатории.', 837);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('fenobarbital', 'Фенобарбитал (phenobarbital, люминал, лекарственный мониторинг, ТЛМ, противоэпилептический препарат)', 'Лекарственный мониторинг', 'Противоэпилептические препараты', 'Определение концентрации фенобарбитала в крови для контроля дозы и безопасности противоэпилептической терапии.', 'Кровь берут перед приёмом очередной дозы (остаточная концентрация), обычно утром натощак. Точное время приёма препарата сообщить лаборатории.', 838);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('lamotridzhin', 'Ламотриджин (lamotrigine, ламиктал, лекарственный мониторинг, ТЛМ, противоэпилептический препарат)', 'Лекарственный мониторинг', 'Противоэпилептические препараты', 'Определение концентрации ламотриджина в крови для контроля дозы и безопасности противоэпилептической терапии.', 'Кровь берут перед приёмом очередной дозы (остаточная концентрация), обычно утром натощак. Точное время приёма препарата сообщить лаборатории.', 839);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('levetiratsetam', 'Леветирацетам (levetiracetam, кеппра, лекарственный мониторинг, ТЛМ, противоэпилептический препарат)', 'Лекарственный мониторинг', 'Противоэпилептические препараты', 'Определение концентрации леветирацетама в крови для контроля дозы и безопасности противоэпилептической терапии.', 'Кровь берут перед приёмом очередной дозы (остаточная концентрация), обычно утром натощак. Точное время приёма препарата сообщить лаборатории.', 840);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('litiy', 'Литий (lithium, литий крови, препараты лития, лекарственный мониторинг, ТЛМ, психиатрические препараты, биполярное расстройство)', 'Лекарственный мониторинг', 'Психиатрические препараты', 'Определение концентрации лития в крови для контроля дозы и безопасности терапии препаратами лития.', 'Кровь берут через 12 часов после последнего приёма (перед очередной дозой), обычно утром натощак. Точное время приёма препарата сообщить лаборатории.', 841);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('digoksin', 'Дигоксин (digoxin, дигоксин крови, сердечные гликозиды, лекарственный мониторинг, ТЛМ, кардиопрепараты)', 'Лекарственный мониторинг', 'Антикоагулянты и кардиопрепараты', 'Определение концентрации дигоксина в крови для контроля дозы и предупреждения токсичности сердечного гликозида.', 'Кровь берут не ранее 6–8 часов после приёма дозы (перед очередным приёмом). Точное время приёма препарата сообщить лаборатории.', 842);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('amiodaron', 'Амиодарон (amiodarone, кордарон, амиодарон крови, антиаритмические препараты, лекарственный мониторинг, ТЛМ, кардиопрепараты)', 'Лекарственный мониторинг', 'Антикоагулянты и кардиопрепараты', 'Определение концентрации амиодарона в крови для контроля антиаритмической терапии и оценки риска токсичности.', 'Кровь берут перед приёмом очередной дозы, обычно утром натощак. Точное время приёма препарата сообщить лаборатории.', 843);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('takrolimus', 'Такролимус (tacrolimus, FK-506, програф, такролимус крови, лекарственный мониторинг, ТЛМ, иммуносупрессанты, трансплантация)', 'Лекарственный мониторинг', 'Иммуносупрессанты', 'Определение концентрации такролимуса в крови для контроля иммуносупрессивной терапии после трансплантации органов.', 'Цельная кровь строго перед приёмом очередной дозы (остаточная концентрация C0), обычно утром. Точное время приёма препарата сообщить лаборатории.', 844);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('tsiklosporin', 'Циклоспорин (cyclosporine, циклоспорин А, сандиммун, циклоспорин крови, лекарственный мониторинг, ТЛМ, иммуносупрессанты, трансплантация)', 'Лекарственный мониторинг', 'Иммуносупрессанты', 'Определение концентрации циклоспорина в крови для контроля иммуносупрессивной терапии после трансплантации.', 'Цельная кровь строго перед приёмом очередной дозы (остаточная концентрация C0), обычно утром. Точное время приёма препарата сообщить лаборатории.', 845);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('sirolimus', 'Сиролимус (sirolimus, рапамицин, сиролимус крови, лекарственный мониторинг, ТЛМ, иммуносупрессанты, трансплантация)', 'Лекарственный мониторинг', 'Иммуносупрессанты', 'Определение концентрации сиролимуса в крови для контроля иммуносупрессивной терапии после трансплантации.', 'Цельная кровь строго перед приёмом очередной дозы (остаточная концентрация C0), обычно утром. Точное время приёма препарата сообщить лаборатории.', 846);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('everolimus', 'Эверолимус (everolimus, эверолимус крови, лекарственный мониторинг, ТЛМ, иммуносупрессанты, трансплантация)', 'Лекарственный мониторинг', 'Иммуносупрессанты', 'Определение концентрации эверолимуса в крови для контроля иммуносупрессивной терапии после трансплантации.', 'Цельная кровь строго перед приёмом очередной дозы (остаточная концентрация C0), обычно утром. Точное время приёма препарата сообщить лаборатории.', 847);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('mikofenolovaya-kislota', 'Микофеноловая кислота (mycophenolic acid, MPA, микофенолат мофетил, селлсепт, лекарственный мониторинг, ТЛМ, иммуносупрессанты, трансплантация)', 'Лекарственный мониторинг', 'Иммуносупрессанты', 'Определение концентрации микофеноловой кислоты в крови для контроля иммуносупрессивной терапии после трансплантации.', 'Кровь берут перед приёмом очередной дозы (остаточная концентрация C0), обычно утром. Точное время приёма препарата сообщить лаборатории.', 848);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('metotreksat', 'Метотрексат (methotrexate, MTX, метотрексат крови, лекарственный мониторинг, ТЛМ, онкологические препараты, химиотерапия)', 'Лекарственный мониторинг', 'Онкологические препараты', 'Определение концентрации метотрексата в крови для контроля безопасности терапии и предупреждения токсичности.', 'Кровь берут в назначенное врачом время после введения дозы (для контроля выведения). Точное время введения препарата сообщить лаборатории.', 849);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('teofillin', 'Теофиллин (theophylline, теофиллин крови, эуфиллин, лекарственный мониторинг, ТЛМ, бронхолитики)', 'Лекарственный мониторинг', 'Прочие препараты', 'Определение концентрации теофиллина в крови для контроля дозы и предупреждения токсичности при лечении бронхолёгочных заболеваний.', 'Кровь берут перед приёмом очередной дозы (остаточная концентрация), обычно утром. Точное время приёма препарата сообщить лаборатории.', 850);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('paratsetamol', 'Парацетамол при передозировке (paracetamol, acetaminophen, ацетаминофен, парацетамол крови, передозировка, токсикология, лекарственный мониторинг)', 'Лекарственный мониторинг', 'Прочие препараты', 'Определение концентрации парацетамола в крови для оценки тяжести передозировки и решения о терапии.', 'Кровь берут по назначению врача, обычно через 4 и более часов после приёма. Точное время приёма препарата сообщить лаборатории.', 851);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('salitsilaty', 'Салицилаты (salicylates, ацетилсалициловая кислота, аспирин, салицилаты крови, передозировка, токсикология, лекарственный мониторинг)', 'Лекарственный мониторинг', 'Прочие препараты', 'Определение концентрации салицилатов в крови для диагностики и оценки тяжести отравления аспирином.', 'Кровь берут по назначению врача с учётом времени приёма. Точное время приёма препарата сообщить лаборатории.', 852);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('vankomitsin', 'Ванкомицин (vancomycin, ванкомицин крови, лекарственный мониторинг, ТЛМ, антибиотики, гликопептиды)', 'Лекарственный мониторинг', 'Антибиотики', 'Определение концентрации ванкомицина в крови для контроля эффективности и предупреждения нефро- и ототоксичности.', 'Кровь берут в назначенное врачом время — остаточная (перед дозой) и/или пиковая концентрация. Точное время введения препарата сообщить лаборатории.', 853);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('amikatsin', 'Амикацин (amikacin, амикацин крови, лекарственный мониторинг, ТЛМ, антибиотики, аминогликозиды)', 'Лекарственный мониторинг', 'Антибиотики', 'Определение концентрации амикацина в крови для контроля эффективности и предупреждения нефро- и ототоксичности.', 'Кровь берут в назначенное врачом время — остаточная (перед дозой) и/или пиковая концентрация. Точное время введения препарата сообщить лаборатории.', 854);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('gentamitsin', 'Гентамицин (gentamicin, гентамицин крови, лекарственный мониторинг, ТЛМ, антибиотики, аминогликозиды)', 'Лекарственный мониторинг', 'Антибиотики', 'Определение концентрации гентамицина в крови для контроля эффективности и предупреждения нефро- и ототоксичности.', 'Кровь берут в назначенное врачом время — остаточная (перед дозой) и/или пиковая концентрация. Точное время введения препарата сообщить лаборатории.', 855);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('etanol-v-krovi', 'Этанол в крови (алкоголь в крови, ethanol, этиловый спирт, концентрация алкоголя, токсикология)', 'Лекарственный мониторинг', 'токсикология и наркотики', 'Определение концентрации этанола (алкоголя) в крови для оценки степени алкогольного опьянения или отравления.', 'Кровь берут по показаниям, в любое время. Кожу перед забором обрабатывают без спиртового антисептика.', 856);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('skrining-narkoticheskih-veschestv-v-moche', 'Скрининг наркотических веществ в моче, мультипанель (наркотики в моче, drug screen, мультипанель, скрининг ПАВ, токсикология, наркологический анализ)', 'Лекарственный мониторинг', 'токсикология и наркотики', 'Скрининговое выявление основных групп наркотических и психоактивных веществ в моче.', 'Разовая порция мочи в чистый контейнер. Сообщить лаборатории о принимаемых лекарствах (возможны перекрёстные реакции).', 857);
INSERT INTO lab_panel_templates (code, name, category, specimen, description, preparation, sort_order) VALUES ('opiaty-v-moche', 'Опиаты в моче (опиаты, opiates, морфин, кодеин, героин, наркотические вещества, токсикология)', 'Лекарственный мониторинг', 'токсикология и наркотики', 'Выявление опиатов в моче для диагностики употребления или отравления.', 'Разовая порция мочи в чистый контейнер. Сообщить лаборатории о принимаемых лекарствах.', 858);
