-- LAB_TEMPLATES_V1 — a read-only catalogue of laboratory panels the clinic
-- imports from, replacing the cloud medcore gateway this offline build cannot
-- reach. Source: the Symptex service catalogue workbook
-- ("service complete list (v5 first-row preview).xlsx"), laboratory branch only:
-- 16 categories, 105 types, 1002 services.
--
-- These are TEMPLATES, not the clinic's own data. Nothing here appears in the
-- Services list or the lab until someone picks a template and imports it, which
-- copies it into lab_panels / lab_panel_analytes as a fully editable clinic panel.
--
-- REFERENCE RANGES ARE DELIBERATELY ABSENT from the template analyte table. They
-- depend on the analyser and method each lab uses, so one clinic's numbers are
-- wrong in another. The clinic fills its own in Настройки → Лаборатория; 050.test.js
-- pins that guarantee so a future seed cannot quietly introduce them.

CREATE TABLE lab_panel_templates (
  id           INTEGER PRIMARY KEY AUTOINCREMENT,
  code         TEXT UNIQUE,          -- catalogue slug, stable across re-seeds
  name         TEXT NOT NULL,
  category     TEXT,                 -- «Биохимия», «Гормоны», …
  specimen     TEXT,                 -- the catalogue's type: «Кровь», «Моча», …
  modality     TEXT NOT NULL DEFAULT 'lab',
  description  TEXT,
  preparation  TEXT,                 -- patient prep, carried onto the service
  sort_order   INTEGER NOT NULL DEFAULT 0,
  active       INTEGER NOT NULL DEFAULT 1,
  created_at   TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ','now'))
);
CREATE INDEX idx_lab_panel_templates_cat ON lab_panel_templates(category);

-- Indicators belonging to a template. NO ref_* columns by design — see above.
CREATE TABLE lab_panel_template_analytes (
  id            INTEGER PRIMARY KEY AUTOINCREMENT,
  template_id   INTEGER NOT NULL REFERENCES lab_panel_templates(id),
  code          TEXT,
  name          TEXT NOT NULL,
  unit          TEXT,
  value_type    TEXT NOT NULL DEFAULT 'numeric' CHECK (value_type IN ('numeric','text','select')),
  value_options TEXT,
  decimals      INTEGER NOT NULL DEFAULT 0,
  group_label   TEXT,
  sort_order    INTEGER NOT NULL DEFAULT 0
);
CREATE INDEX idx_lab_tpl_analytes_tpl ON lab_panel_template_analytes(template_id);


-- ── the 1002 laboratory templates ──────────────────────────────────
